        const string SQL_SalesBillwise = @"with billsummary as (
select bill.id,
sum(billitems.discount) summarydiscount, sum(billitems.schemediscount) summaryschemediscount, 
sum(billitems.additionaldiscount::numeric * billitems.qty::numeric) summaryadditionaldiscount
from bill 
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
left outer join customer on customer.id = bill.customerid
where bill.isactive = true and bill.isb2b=@isb2b {0} and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end 
group by bill.id	
),
billtaxdetail as (
Select bill.id, bill.isinterstatesale, bill.istransfer, bill.isexport, customer.gstno, customercity.name as customercityname, 
customerstate.code customerstatecode, customerstate.name customerstatename, companystate.code companystatecode, companystate.name companystatename,
location.name as location, 
counter.name as counter, employee.name employeename, customer.name customername, customer.mobileno,billno, billdate, 
rounding,(receivable+rounding) receivable, tax, discount, additionaldiscount, qty , bill.billtype, 
returnreason.name retreason,modifiedbyemployee.name memployeename, bill.createdon, bill.modifiedon,
billattributes->>'remarks' remarks,	saleref.name salerefname,
cast(billattributes->>'spentreward' as numeric) spentreward,
billsummary.summarydiscount, billsummary.summaryadditionaldiscount, billsummary.summaryschemediscount
from bill inner join referencelist location on location.id = bill.locationid
inner join company on company.id = bill.companyid
left outer join billsummary on billsummary.id = bill.id
left outer join referencelist counter on counter.id = bill.counterid
left outer join referencelist returnreason on returnreason.id = bill.returnreasonid
left outer join users on users.id = bill.createdby
left outer join employee on employeeid = employee.id 
left outer join users modifeduser on modifeduser.id = bill.modifiedby
left outer join employee modifiedbyemployee on modifiedbyemployee.id = modifeduser.employeeid 
left outer join customer on customer.id = bill.customerid
left outer join referencelist customercity on customercity.id = customer.cityid
left outer join referencelist customerstate on customerstate.id = customer.stateid
left outer join referencelist companystate on companystate.id = company.stateid
left outer join employee saleref on saleref.id = cast(billattributes->>'salesrefid' as bigint)
where bill.isactive = true and bill.isb2b=@isb2b {0} and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end 
order by bill.id
),
additionalcharge as (
Select bill.id billid,Billadditionalcharges.taxpercentage,
sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 
sum(Billadditionalcharges.tax) tax,
sum(Billadditionalcharges.amount - (Billadditionalcharges.charge+Billadditionalcharges.tax)) rounding
from bill inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
left outer join customer on customer.id = bill.customerid
where bill.isactive = true and bill.isb2b=@isb2b {0} and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end 
and Billadditionalcharges.taxpercentage>0 and Billadditionalcharges.tax != 0	
group by bill.id, Billadditionalcharges.taxpercentage
)
select billtaxdetail.id, billtaxdetail.isinterstatesale, billtaxdetail.istransfer, billtaxdetail.isexport, billtaxdetail.gstno, 
billtaxdetail.customerstatecode, billtaxdetail.customerstatename, billtaxdetail.companystatecode, billtaxdetail.companystatename,
billtaxdetail.customercityname, billtaxdetail.location, billtaxdetail.salerefname, billtaxdetail.spentreward,
billtaxdetail.counter, billtaxdetail.employeename, billtaxdetail.customername, billtaxdetail.mobileno, billno, billdate, 
billtaxdetail.discount, billtaxdetail.additionaldiscount, billtaxdetail.qty , billtaxdetail.billtype, billtaxdetail.retreason,
billtaxdetail.receivable receivable, memployeename, billtaxdetail.createdon, billtaxdetail.modifiedon, billtaxdetail.remarks,
billtaxdetail.summarydiscount, billtaxdetail.summaryadditionaldiscount, billtaxdetail.summaryschemediscount,
billtaxdetail.tax + case when additionalcharge.tax is null then 0 else additionalcharge.tax end tax, 
billtaxdetail.rounding + case when additionalcharge.rounding is null then 0 else additionalcharge.rounding end rounding,
case when additionalcharge.tax is null then 0 else additionalcharge.tax end additionaltax
from billtaxdetail left outer join additionalcharge on additionalcharge.billid = billtaxdetail.id 
order by billtaxdetail.id";

        const string SQL_SalesBillTaxwise = @"Select bill.id,taxpercentage,sum(billitems.receivable) receivable,
                                    sum(billitems.tax) tax,bill.isinterstatesale
                                    from bill 
                                    inner join billitems on billitems.billid = bill.id and billitems.isactive = true
                                    where bill.isactive = true and bill.isb2b=@isb2b {0} and bill.billdate>=@fromdate and bill.billdate<@todate
                                    and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
                                    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end    
                                    group by bill.id,isinterstatesale,taxpercentage";

        const string SQL_DiscSalesBillwise = @"with billsummary
as
(
select bill.id,
sum(billitems.discount) summarydiscount, sum(billitems.schemediscount) summaryschemediscount, 
sum(billitems.additionaldiscount::numeric * billitems.qty::numeric) summaryadditionaldiscount
from bill 
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
where bill.isactive = true and bill.isb2b=false {0} and bill.billdate>=@fromdate and bill.billdate<@todate and (bill.discount>0 or bill.additionaldiscount>0)
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end 
group by bill.id	
)
Select bill.id, bill.isinterstatesale, customer.gstno, customercity.name as customercityname,customer.mobileno,location.name as location, counter.name as counter, 
                                    employee.name employeename, customer.name customername, billno, billdate, rounding,(receivable+rounding) receivable, tax, discount, additionaldiscount, qty , bill.billtype, returnreason.name retreason,
                                    billsummary.summarydiscount, billsummary.summaryschemediscount, billsummary.summaryadditionaldiscount, modifiedemployee.name modifiedemployeename,billattributes->>'remarks' remarks,
                                    cast(billattributes->>'spentreward' as numeric) spentreward
                                    from bill inner join referencelist location on location.id = bill.locationid
                                    left outer join billsummary on billsummary.id = bill.id
                                    left outer join referencelist counter on counter.id = bill.counterid
                                    left outer join referencelist returnreason on returnreason.id = bill.returnreasonid
                                    left outer join users on users.id = bill.createdby
                                    left outer join employee on employeeid = employee.id 
                                    left outer join users modifieduser on modifieduser.id = bill.modifiedby
                                    left outer join employee modifiedemployee on modifieduser.employeeid = modifiedemployee.id 
                                    left outer join customer on customer.id = bill.customerid
                                    left outer join referencelist customercity on customercity.id = customer.cityid
                                    where bill.isactive = true and bill.isb2b=false {0} and bill.billdate>=@fromdate and bill.billdate<@todate and (bill.discount>0 or bill.additionaldiscount>0)
                                    and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
                                    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end 
                                    order by bill.id";

