        //	case when POSITION('/' IN billno)>0 then cast(substring(billno,POSITION('/' IN billno)+1) as int) else cast(billno as int) end billno,companyid,locationid,billtype from bill
        //where billdate>=@fromdate and  billdate<@todate and isactive = true
