        const string SQL_SalesNoSummary = @"with billnosummary
as
(
    select case when POSITION('/' IN billno)>0 then substring(billno,0,LENGTH(billno) - STRPOS(REVERSE(billno), '/') + 1) else '' end prefix,
    case when POSITION('/' IN billno)>0 and substring(billno,LENGTH(billno) - STRPOS(REVERSE(billno), '/') + 2) ~ '^-?[0-9]+(\.[0-9]+)?$' 
            then cast(substring(billno,LENGTH(billno) - STRPOS(REVERSE(billno), '/') + 2) as int) 
        when billno ~ '^-?[0-9]+(\.[0-9]+)?$' then cast(billno as int)
        else -1 end 
        billno,companyid,locationid,billtype from bill
    where billdate>=@fromdate and  billdate<@todate and isactive = true
)
select prefix,min(billno) startno,max(billno) endno,sum(case when billtype=9 then 1 else 0 end) cancelledbills
,sum(case when billtype=9 then 0 else 1 end) normalbill,count(*) billnosummary from billnosummary
group by prefix";


        internal NotificationSummary GetNotifications()
        {

            NotificationSummary notificationSummary = new NotificationSummary();

            string pendingbundlequery = string.Format(@"select bundles.code,company.name companyname,qty,
        referencelistf.name fromlocation, referencelistt.name tolocation, packedon, receivedon, employee.name packedby
        from bundles 
        left outer join referencelist referencelistf on referencelistf.type ='LOCATION' and referencelistf.id = fromlocationid
        left outer join referencelist referencelistt on referencelistt.type ='LOCATION' and referencelistt.id = tolocationid
		left outer join company on company.id = tocompanyid
        left outer join employee on employee.id = packedby 
        where bundles.isactive =true and bundles.status = 0 and tolocationid in ({0})
        order by packedon desc", string.Join(",", Context.accessiblelocation));
            List<OutwardReport> lst = new List<OutwardReport>();
            notificationSummary.PendingBundles = lst;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                var command = GetCommand(pendingbundlequery, conn);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        OutwardReport oitem = new OutwardReport();
                        oitem.code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString();
                        oitem.fromlocation = reader["fromlocation"] == DBNull.Value ? "" : reader["fromlocation"].ToString();
                        oitem.tolocation = reader["tolocation"] == DBNull.Value ? "" : reader["tolocation"].ToString();
                        oitem.tocompany = reader["companyname"] == DBNull.Value ? "" : reader["companyname"].ToString();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.packedon = reader["packedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["packedon"]);
                        oitem.packedby = reader["packedby"] == DBNull.Value ? "" : reader["packedby"].ToString();
                        lst.Add(oitem);
                    }
                }
            }
            catch (Exception exp)
            {
                if (conn.State != System.Data.ConnectionState.Closed)
                    conn.Close();
            }

            Data.ReorderrulesDataService reorderrulesDataService = new ReorderrulesDataService() { Context = this.Context };
            notificationSummary.Reorders = reorderrulesDataService.Report(new Models.ReorderrulesCreteria()
            {
                locationid = Context.accessiblelocation.Count == 1 ? Context.accessiblelocation[0] : 0,
                companyid = Context.CompanyID
            });
            return notificationSummary;
        }

        internal List<SoldBarcodes> SearchSoldBarcodes(StockReportCreteria item)
        {
            List<SoldBarcodes> result = new List<SoldBarcodes>();
            string query = @"select billitems.barcode,sum(billitems.qty) qty from billitems
inner join bill on bill.id = billitems.billid
inner join stock on stock.id = billitems.stockid
left outer join items on items.id = stock.itemid
left outer join products on products.id = stock.productid
where bill.isactive = true and billtype!=9 and bill.billdate>=@fromdate and bill.billdate<@todate {0}
group by billitems.barcode";
            var param = new SortedList<string, object>();
            param.Add("fromdate", item.fromdate.Date);
            param.Add("todate", item.todate.AddDays(1).Date);

            param.Add("productid", item.productid);
            param.Add("brandid", item.brandid);
            param.Add("sectionid", item.sectionid);
            param.Add("locationid", item.locationid);

            string condition = "";
            if (item.locationid > 0)
                condition += " and bill.locationid = @locationid";
            if (item.productid > 0)
                condition += " and stock.productid = @productid";
            if (item.brandid > 0)
                condition += " and items.brandid= @brandid";
            if (item.sectionid > 0)
                condition += " and products.salescounterid = @sectionid";

            using (var reader = ExecuteReader(string.Format(query, condition), param))
            {
                while (reader.Read())
                {
                    result.Add(new SoldBarcodes()
                    {
                        barcode = reader.GetString(0),
                        qty = reader.GetDecimal(1)
                    });
                }
            }

            return result;
        }

        internal List<SettlementReport> SearchSettlementByTax(RetailReportCreteria _reportcreteria)
        {
            if (Context.HasPermission(PermissionSet.hidecashcollection, InfyPOS.Common.Action.View))
            {
                if (_reportcreteria.fromdate.Date < DateTimeNow.Date.AddDays(-2))
                {
                    throw new Exception("Don't have permission to view collection report");
                }
            }

            List<SettlementReport> lst = new List<SettlementReport>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;

                command = GetCommand(SQL_SettlementBytax, conn);
                if (_reportcreteria.locationid <= 0)
                {
                    command = GetCommand(SQL_SettlementBytax.Replace("and billsettlement.locationid = @locationid", ""), conn);
                }
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                //and billsettlement.locationid = @locationid
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        //receivable,tax,taxpercentage,companyid
                        SettlementReport oitem = new SettlementReport();
                        oitem.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        oitem.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        oitem.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        oitem.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        oitem.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                        oitem.paid_cash = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]);
                        oitem.paid_card = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]);
                        oitem.paid_upi = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]);
                        oitem.paid_credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                        oitem.paid_voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);
                        lst.Add(oitem);
                    }
                }
                conn.Close();

                if (lst.Exists(e => e.receivable < 0))
                {
                    foreach (var item in lst.FindAll(e => e.receivable < 0))
                    {
                        item.paid_cash += item.receivable;
                    }
                }

                List<SettlementReport> result = new List<SettlementReport>();
                foreach (var sm in lst.GroupBy(e => e.id))
                {
                    bool adjustrefund = (sm.Count() > 1 && sm.ToList().Exists(e => e.receivable < 0));
                    var settlement = sm.First();
                    foreach (var item in sm.GroupBy(e => new { e.companyid, e.taxpercentage }))
                    {
                        SettlementReport settlementReport = new SettlementReport()
                        {
                            companyid = item.Key.companyid,
                            taxpercentage = item.Key.taxpercentage,
                            receivable = item.Sum(e => e.receivable)
                        };
                        result.Add(settlementReport);


                        foreach (var tran in item)
                        {
                            if (tran.receivable < 0)
                            {
                                settlementReport.paid_cash += tran.receivable;
                            }
                            else
                            {
                                if (tran.receivable > 0 && settlement.paid_cash > 0)
                                {
                                    if (tran.receivable <= settlement.paid_cash)
                                    {
                                        settlementReport.paid_cash += tran.receivable;
                                        settlement.paid_cash -= tran.receivable;
                                        tran.receivable = 0;
                                    }
                                    else
                                    {
                                        settlementReport.paid_cash += settlement.paid_cash;
                                        tran.receivable -= settlement.paid_cash;
                                        settlement.paid_cash = 0;
                                    }
                                }

                                if (tran.receivable > 0 && settlement.paid_card > 0)
                                {
                                    if (tran.receivable <= settlement.paid_card)
                                    {
                                        settlementReport.paid_card += tran.receivable;
                                        settlement.paid_card -= tran.receivable;
                                        tran.receivable = 0;
                                    }
                                    else
                                    {
                                        settlementReport.paid_card += settlement.paid_card;
                                        tran.receivable -= settlement.paid_card;
                                        settlement.paid_card = 0;
                                    }
                                }

                                if (tran.receivable > 0 && settlement.paid_voucher > 0)
                                {
                                    if (tran.receivable <= settlement.paid_voucher)
                                    {
                                        settlementReport.paid_voucher += tran.receivable;
                                        settlement.paid_voucher -= tran.receivable;
                                        tran.receivable = 0;
                                    }
                                    else
                                    {
                                        settlementReport.paid_voucher += settlement.paid_voucher;
                                        tran.receivable -= settlement.paid_voucher;
                                        settlement.paid_voucher = 0;
                                    }
                                }

                                if (tran.receivable > 0 && settlement.paid_credit > 0)
                                {
                                    if (tran.receivable <= settlement.paid_credit)
                                    {
                                        settlementReport.paid_credit += tran.receivable;
                                        settlement.paid_credit -= tran.receivable;
                                        tran.receivable = 0;
                                    }
                                    else
                                    {
                                        settlementReport.paid_credit += settlement.paid_credit;
                                        tran.receivable -= settlement.paid_credit;
                                        settlement.paid_credit = 0;
                                    }
                                }

                                if (tran.receivable > 0 && settlement.paid_upi > 0)
                                {
                                    if (tran.receivable <= settlement.paid_upi)
                                    {
                                        settlementReport.paid_upi += tran.receivable;
                                        settlement.paid_upi -= tran.receivable;
                                        tran.receivable = 0;
                                    }
                                    else
                                    {
                                        settlementReport.paid_upi += settlement.paid_upi;
                                        tran.receivable -= settlement.paid_upi;
                                        settlement.paid_upi = 0;
                                    }
                                }

                                if (tran.receivable > 0)
                                {
                                    if (adjustrefund)
                                    {
                                        settlementReport.paid_cash += tran.receivable;
                                        settlement.paid_cash += tran.receivable;
                                    }
                                    else
                                    {
                                        settlementReport.adjustment_paid += tran.receivable;
                                        settlement.adjustment_paid -= tran.receivable;
                                    }
                                }
                            }
                        }
                    }
                }
                lst = result.GroupBy(e => new { e.companyid, e.taxpercentage }).ToList().ConvertAll(ex =>
                    {
                        return new SettlementReport()
                        {
                            companyid = ex.Key.companyid,
                            taxpercentage = ex.Key.taxpercentage,
                            receivable = ex.Sum(e => e.receivable),
                            tax = ex.Key.taxpercentage <= 0 ? 0 : ex.Sum(e => e.receivable / (100 + ex.Key.taxpercentage) * ex.Key.taxpercentage),
                            paid_card = ex.Sum(e => e.paid_card),
                            paid_cash = ex.Sum(e => e.paid_cash),
                            paid_credit = ex.Sum(e => e.paid_credit),
                            paid_upi = ex.Sum(e => e.paid_upi),
                            paid_voucher = ex.Sum(e => e.paid_voucher),
                            adjustment_paid = ex.Sum(e => e.adjustment_paid)
                        };
                    });
                if (_reportcreteria.companyid > 0)
                {
                    lst = lst.FindAll(e => e.companyid == _reportcreteria.companyid);
                }
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst.OrderBy(e => e.taxpercentage).ToList();
        }

        internal List<LocationViewItem> GetLocationView()
        {
            string query = @"select sum(bill.receivable+bill.rounding) as monthsales,
sum(case when bill.receivable >0 and billdate>=@todayfrom and billdate<@todayto then bill.receivable+bill.rounding else 0 end) as todaysales,
bill.locationid,
sum(case when bill.receivable >0 then 1 else 0 end) monthbillcount,
sum(case when bill.receivable >0 then bill.qty else 0 end) monthsalesqty,
sum(case when bill.receivable >0 and billdate>=@todayfrom and billdate<@todayto then 1 else 0 end) as todaybillcount,
sum(case when bill.receivable >0 and billdate>=@todayfrom and billdate<@todayto then bill.qty else 0 end) as todaysalesqty
from bill
where bill.billdate>=@monthfrom and bill.billdate<@monthto and bill.billtype != 9 and bill.isactive = true
group by bill.locationid;

select -1::int as locationid,sum(stock.qty-stock.transfered-stock.journalqty-stock.damagedqty-returnqty) stockqty,
            sum(buyingprice::numeric * (stock.qty-stock.transfered-stock.journalqty-stock.damagedqty-returnqty)::numeric) stockcostvalue,
            sum((price::numeric-discount::numeric) * (stock.qty-stock.transfered-stock.journalqty-stock.damagedqty-returnqty)::numeric) salevalue
            from stock 
            where stock.isactive = true and stock.hasstock = true and stock.qty-stock.journalqty-stock.transfered-stock.damagedqty-returnqty>0;

select salablegoods.locationid,sum((salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty))::numeric*stock.buyingprice::numeric) as stockcostvalue,
sum((salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty))::numeric) stockqty from salablegoods
inner join stock on stock.id = stockid
where salablegoods.hasstock=true and salablegoods.isactive = true
group by salablegoods.locationid;

select sum(case when status=1 or status=2 then (schemelist ->> 'aqty')::numeric else 0::numeric end) bundleqty,
sum(case when status=1 or status=2 then (schemelist ->> 'aqty')::numeric*stock.ibuyingprice::numeric else 0::numeric end) bundlevalue,
sum(case when status=0 then 1::int else 0::int end) pending,
tolocationid as locationid from bundles 
LEFT JOIN LATERAL
json_array_elements (case when bundles.items is null or bundles.items::text ='null' then '[]'::json else bundles.items :: json end) schemelist ON true
inner join stock ON (schemelist ->> 'stockid') :: BIGINT = stock.id
where receivedon>=@monthfrom and receivedon<@monthto
group by tolocationid;";
            List<LocationViewItem> result = new List<LocationViewItem>();
            var param = new SortedList<string, object>();
            param.Add("todayfrom", DateTimeNow.Date);
            param.Add("todayto", DateTimeNow.Date.AddDays(1));
            param.Add("monthfrom", new DateTime(DateTimeNow.Date.Year, DateTimeNow.Date.Month, 1));
            param.Add("monthto", new DateTime(DateTimeNow.Date.Year, DateTimeNow.Date.Month, 1).AddMonths(1));
            ReferencelistDataService referencelistDataService = new ReferencelistDataService() { Context = this.Context };
            var locations = referencelistDataService.SearchList(new ReferencelistCreteria()
            {
                type = "LOCATION"
            });

            if (Services.ConfigManager.Instance(Context.OrganizationID).Config.analyser_stock_removeaqty)
                query = query.Replace("salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty)", "salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty+salablegoods.aqty)");

            using (var reader = ExecuteReader(query, param, 10000))
            {
                while (reader.Read())
                {
                    long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                    if (!result.Exists(e => e.id == locationid))
                        result.Add(new LocationViewItem()
                        {
                            id = locationid,
                            name = !locations.Exists(e => e.id == locationid) ? "Warehouse" : locations.Find(e => e.id == locationid).name
                        });

                    var location = result.Find(e => e.id == locationid);
                    //location.todayreturn = reader["todayreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["todayreturn"]);
                    //location.todayreturnqty = reader["todayreturnqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["todayreturnqty"]);
                    location.todaysales = reader["todaysales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["todaysales"]);
                    //location.todaysalesqty = reader["todaysalesqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["todaysalesqty"]);
                    //location.monthreturn = reader["monthreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["monthreturn"]);
                    //location.monthreturnqty = reader["monthreturnqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["monthreturnqty"]);
                    location.monthsales = reader["monthsales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["monthsales"]);

                    location.monthbillcount = reader["monthbillcount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["monthbillcount"]);
                    location.todaybillcount = reader["todaybillcount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["todaybillcount"]);
                    location.monthsalesqty = reader["monthsalesqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["monthsalesqty"]);
                    location.todaysalesqty = reader["todaysalesqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["todaysalesqty"]);
                    //location.monthsalesqty = reader["monthsalesqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["monthsalesqty"]);
                }

                if (reader.NextResult())
                    while (reader.Read())
                    {
                        long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        if (!result.Exists(e => e.id == locationid))
                            result.Add(new LocationViewItem()
                            {
                                id = locationid,
                                name = !locations.Exists(e => e.id == locationid) ? "Warehouse" : locations.Find(e => e.id == locationid).name
                            });

                        var location = result.Find(e => e.id == locationid);
                        location.stockcostvalue = reader["stockcostvalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockcostvalue"]);
                        location.stockqty = reader["stockqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockqty"]);
                    }


                if (reader.NextResult())
                    while (reader.Read())
                    {
                        long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        if (!result.Exists(e => e.id == locationid))
                            result.Add(new LocationViewItem()
                            {
                                id = locationid,
                                name = !locations.Exists(e => e.id == locationid) ? "Warehouse" : locations.Find(e => e.id == locationid).name
                            });

                        var location = result.Find(e => e.id == locationid);
                        location.stockcostvalue = reader["stockcostvalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockcostvalue"]);
                        location.stockqty = reader["stockqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockqty"]);
                    }

                if (reader.NextResult())
                    while (reader.Read())
                    {
                        long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        if (!result.Exists(e => e.id == locationid))
                            result.Add(new LocationViewItem()
                            {
                                id = locationid,
                                name = !locations.Exists(e => e.id == locationid) ? "Warehouse" : locations.Find(e => e.id == locationid).name
                            });
                        var location = result.Find(e => e.id == locationid);
                        location.pendinginward = reader["pending"] == DBNull.Value ? 0 : Convert.ToInt32(reader["pending"]);
                        location.bundleqty = reader["bundleqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["bundleqty"]);
                        location.bundlevalue = reader["bundlevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["bundlevalue"]);
                    }
            }

            if (Context != null &&
    Context.accessiblelocation != null &&
    !Context.accessiblelocation.Contains(-1))
                result.RemoveAll(e => !Context.accessiblelocation.Exists(x => x == e.id));

            if (result.Count > 1)
                result.Add(new LocationViewItem()
                {
                    id = 0,
                    name = "All Store",
                    bundleqty = result.Sum(e => e.bundleqty),
                    pendinginward = result.Sum(e => e.pendinginward),
                    bundlevalue = result.Sum(e => e.bundlevalue),
                    stockcostvalue = result.Sum(e => e.stockcostvalue),
                    stockqty = result.Sum(e => e.stockqty),
                    todaysales = result.Sum(e => e.todaysales),
                    monthsales = result.Sum(e => e.monthsales),
                    todaysalesqty = result.Sum(e => e.todaysalesqty),
                    monthsalesqty = result.Sum(e => e.monthsalesqty),
                    todaybillcount = result.Sum(e => e.todaybillcount),
                    monthbillcount = result.Sum(e => e.monthbillcount),
                });

            result.ForEach(x =>
            {
                x.bundleqty = Math.Round(x.bundleqty);
                x.monthsalesqty = Math.Round(x.monthsalesqty);
                x.stockcostvalue = Math.Round(x.stockcostvalue);
                x.stockqty = Math.Round(x.stockqty);
                x.todaysalesqty = Math.Round(x.todaysalesqty);
            });
            return result;
        }

        public class BillNoSummary
        {
            public string prefix { get; set; }
            public int start { get; set; }
            public int end { get; set; }
            public int cancelledbills { get; set; }
            public int normalbill { get; set; }
            public int billnosummary { get; set; }
        }
        internal List<BillNoSummary> SearchBillNoSummary(SaleRetailCreteria item)
        {
            var result = new List<BillNoSummary>();
            var param = new SortedList<string, object>();
            param.Add("fromdate", item.fromdate.Date);
            param.Add("todate", item.todate.Date.AddDays(1));
            using (var reader = ExecuteReader(SQL_SalesNoSummary, param))
            {
                while (reader.Read())
                {
                    BillNoSummary billNoSummary = new BillNoSummary();
                    billNoSummary.prefix = reader["prefix"].ToString();
                    billNoSummary.start = Convert.ToInt32(reader["startno"]);
                    billNoSummary.end = Convert.ToInt32(reader["endno"]);
                    billNoSummary.cancelledbills = Convert.ToInt32(reader["cancelledbills"]);
                    billNoSummary.normalbill = Convert.ToInt32(reader["normalbill"]);
                    billNoSummary.billnosummary = Convert.ToInt32(reader["billnosummary"]);
                    result.Add(billNoSummary);
                }
            }
            return result;
        }

        const string SQL_SalesTaxValidation = @"select taxpercentage,sum(billitems.receivable) billincludetax,
sum(billitems.receivable) billexcludetax,sum(billitems.receivable-billitems.tax) taxableamount,sum(billitems.tax) tax from bill 
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
where billdate>=@fromdate and  billdate<@todate and bill.isb2b=@isb2b and bill.isactive = true and billtype != 9
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
group by taxpercentage;

select sum(rounding) from bill 
where billdate>=@fromdate and  billdate<@todate and bill.isb2b=@isb2b and bill.isactive = true and billtype != 9
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
";
        public class BillTaxValidationSummary
        {
            public string description { get; set; }
            public decimal billincludetax { get; set; }
            public decimal billexcludetax { get; set; }
            public decimal tax { get; set; }
            public decimal taxableamount { get; set; }

            public decimal taxpercentage { get; set; }
            public decimal taxdiff { get; set; }
        }
        internal List<BillTaxValidationSummary> SearchBillTaxValidation(SaleRetailCreteria item)
        {
            var result = new List<BillTaxValidationSummary>();
            var param = new SortedList<string, object>();
            param.Add("fromdate", item.fromdate.Date);
            param.Add("todate", item.todate.Date.AddDays(1));
            param.Add("locationid", item.locationid);
            param.Add("companyid", item.companyid);
            param.Add("isb2b", item.isb2b);
            using (var reader = ExecuteReader(SQL_SalesTaxValidation, param))
            {
                while (reader.Read())
                {
                    BillTaxValidationSummary billNoSummary = new BillTaxValidationSummary();
                    billNoSummary.taxpercentage = Convert.ToDecimal(reader["taxpercentage"]);
                    billNoSummary.description = reader["taxpercentage"].ToString();
                    billNoSummary.billincludetax = Convert.ToDecimal(reader["billincludetax"]);
                    billNoSummary.billexcludetax = Convert.ToDecimal(reader["billexcludetax"]);
                    billNoSummary.taxableamount = Convert.ToDecimal(reader["taxableamount"]);
                    billNoSummary.tax = Convert.ToDecimal(reader["tax"]);
                    if (billNoSummary.taxpercentage > 0)
                    {
                        var tax = billNoSummary.billincludetax / (billNoSummary.taxpercentage + 100) * billNoSummary.taxpercentage;
                        billNoSummary.taxdiff = billNoSummary.tax - tax;
                    }
                    result.Add(billNoSummary);
                }
                if (reader.NextResult() && reader.Read())
                {
                    BillTaxValidationSummary billNoSummary = new BillTaxValidationSummary();
                    billNoSummary.description = "Rounding";
                    billNoSummary.billincludetax = reader.GetDecimal(0);
                    billNoSummary.billexcludetax = reader.GetDecimal(0);
                    billNoSummary.taxableamount = reader.GetDecimal(0);
                    result.Add(billNoSummary);
                }
            }
            return result;
        }

        const string SQL_SalesSummaryLocationwise = @"Select location.name as location,  sum(bill.rounding) rounding, sum(bill.receivable+bill.rounding) receivable, sum(tax) tax, sum(discount) discount, 
sum(additionaldiscount) additionaldiscount, sum(billqty.billedqty) qty
from bill 
inner join referencelist location on location.id = bill.locationid
inner join (select sum(billitems.qty) billedqty,billid from bill
            inner join billitems on billitems.billid = bill.id and billitems.isactive=true
            where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate
            and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
            and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
            group by billid
            ) billqty on billqty.billid = bill.id
where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
group by location.name
order by location";

        const string SQL_SalesSummaryCompanywise = @"Select company.name as companyname,  sum(bill.rounding) rounding, sum(bill.receivable+bill.rounding) receivable, sum(tax) tax, sum(discount) discount, 
sum(additionaldiscount) additionaldiscount, sum(billqty.billedqty) qty
from bill 
inner join company company on company.id = bill.companyid
inner join (select sum(billitems.qty) billedqty,billid from bill
            inner join billitems on billitems.billid = bill.id and billitems.isactive=true
            where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate
            and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
            and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
            group by billid
            ) billqty on billqty.billid = bill.id
where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b {0} and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
group by company.name
order by companyname";


