                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["exchange"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["exchange"]),
                            name = "Exchange Bills (With SR)",
                            id = "EXCHANGEBILLS"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["exchangevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["exchangevalue"]),
                            name = "Exchange Value (With SR)",
                            id = "EXCHANGEVALUE"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["return"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["return"]),
                            name = "Sales Return Count",
                            id = "RETURNBILL"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["returnvalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["returnvalue"]),
                            name = "Sales Return Value",
                            id = "RETURNVALUE"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cancel"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cancel"]),
                            name = "Cancel Bills"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cancelvalue"] == DBNull.Value ? 0 : Math.Abs(Convert.ToDecimal(reader["cancelvalue"])),
                            name = "Cancel Values"
                        });
                        itemgroup.Items.RemoveAll(e => e.value == 0);
                    }

                    var exchangeitems = daySummary.Groups[0].Items;
                    if (reader.NextResult() && reader.Read())
                    {
                        itemgroup = new DaySummary.Group() { name = "SALES SUMMARY", type = DaySummary.Group.Types.Bill, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Insert(0, itemgroup);
                        itemgroup.value = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["rewards"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rewards"]),
                            name = "Rewards"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = (reader["sales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sales"]) + exchangevalue) +
                            (reader["cashdiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashdiscount"])),
                            name = "Total sales"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cashdiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashdiscount"]),
                            name = "Cash Discount"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = (reader["sales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sales"]) + exchangevalue),
                            name = "sales"
                        });

                        if (!exchangeitems.Exists(e => e.id == "EXCHANGEVALUE"))
                        {
                            exchangeitems.Add(new DaySummary.Item()
                            {
                                name = "Exchange Value (With SR)",
                                id = "EXCHANGEVALUE"
                            });
                        }

                        if (!exchangeitems.Exists(e => e.id == "EXCHANGEBILLS"))
                        {
                            exchangeitems.Add(new DaySummary.Item()
                            {
                                name = "Exchange Bills (With SR)",
                                id = "EXCHANGEBILLS"
                            });
                        }

                        if (reader["salesreturn"] != DBNull.Value)
                            exchangeitems.Find(e => e.id == "EXCHANGEVALUE").value += Convert.ToDecimal(reader["salesreturn"]);
                        if (reader["salesreturncount"] != DBNull.Value)
                            exchangeitems.Find(e => e.id == "EXCHANGEBILLS").value += Convert.ToDecimal(reader["salesreturncount"]);

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["billcount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billcount"]),
                            name = "Bill Count"
                        });

                        itemgroup.Items.RemoveAll(e => e.value == 0);
                    }



                    if (reader.NextResult() && reader.Read())
                    {
                        itemgroup = new DaySummary.Group() { name = "SETTLEMENT SUMMARY", type = DaySummary.Group.Types.Settlement, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Add(itemgroup);

                        cashsales = reader["cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash"]);
                        cashrefund = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash"]),
                            name = "Cash Sales"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["card"]),
                            name = "Card Sales"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["upi"]),
                            name = "UPI Sales"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["credit"]),
                            name = "Credit Sales"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["loan"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["loan"]),
                            name = "EMI Sales"
                        });

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucher"]),
                            name = "Voucher Sales"
                        });
                        itemgroup.value = itemgroup.Items.Sum(e => e.value) - cashrefund;
                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]),
                            name = "Refund"
                        });
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        itemgroup = new DaySummary.Group() { name = "PETTY CASH", type = DaySummary.Group.Types.PettyCash, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Add(itemgroup);

                        decimal opening = reader["opening"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["opening"]);
                        pettycashexpense = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);


                        /*itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = opening,
                            name = "Petty cash Opening"
                        });*/

                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = pettycashexpense,
                            name = reader["displayname"].ToString()
                        });

                        while (reader.Read())
                        {
                            pettycashexpense += reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]),
                                name = reader["displayname"].ToString()
                            });
                        }

                        closing = opening - pettycashexpense;
                        itemgroup.value = closing;
                        cashinhand = cashsales - cashrefund;
                        //+ closing;

                        //itemgroup.Items.Add(new DaySummary.Item()
                        //{
                        //    value = closing,
                        //    name = "Closing Petty Cash"
                        //});

                        //itemgroup.Items.Add(new DaySummary.Item()
                        //{
                        //    value = cashinhand,
                        //    name = "Cash In Hand"
                        //});
                    }
                    //else
                    //{
                    //    itemgroup.Items.Add(new DaySummary.Item()
                    //    {
                    //        value = cashsales - cashrefund,
                    //        name = "Cash In Hand"
                    //    });
                    //}


                    if (reader.NextResult())
                    {
                        itemgroup = new DaySummary.Group() { name = "EC", type = DaySummary.Group.Types.Loans, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Add(itemgroup);

                        if (reader.Read())
                        {
                            var amount = reader["rate"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rate"]);
                            itemgroup.value = amount;
                            eccash = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]);
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]),
                                name = "Cash"
                            });
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]),
                                name = "Card"
                            });
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]),
                                name = "UPI"
                            });
                        }
                    }

                    if (reader.NextResult())
                    {
                        itemgroup = new DaySummary.Group() { name = "EC-Card Payment", type = DaySummary.Group.Types.ECCardPayment, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Add(itemgroup);

                        while (reader.Read())
                        {
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]),
                                name = reader["bankname"].ToString() + "(" + reader["tid"].ToString() + ") - EC",
                                id = reader["tid"].ToString()
                            });
                        }
                        itemgroup.value = itemgroup.Items.Sum(e => e.value);
                    }

                    if (reader.NextResult())
                    {
                        itemgroup = new DaySummary.Group() { name = "EMI", type = DaySummary.Group.Types.Loans, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Add(itemgroup);

                        while (reader.Read())
                        {
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["loan_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["loan_paid"]),
                                name = reader["loanprovider"].ToString() + "(" + reader["loan_reference"].ToString() + ")",
                                id = reader["loan_reference"].ToString()
                            });
                        }
                        itemgroup.value = itemgroup.Items.Sum(e => e.value);
                    }

                    if (reader.NextResult())
                    {
                        itemgroup = new DaySummary.Group() { name = "CARD", type = DaySummary.Group.Types.Loans, Items = new List<DaySummary.Item>() };
                        daySummary.Groups.Add(itemgroup);

                        while (reader.Read())
                        {
                            if (reader["paid_card"] != DBNull.Value && Convert.ToDecimal(reader["paid_card"]) > 0)
                            {
                                itemgroup.Items.Add(new DaySummary.Item()
                                {
                                    value = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]),
                                    name = reader["bankname"].ToString() + "(" + reader["tid"].ToString() + ")",
                                    id = reader["tid"].ToString()
                                });
                            }
                            else
                            {
                                itemgroup.Items.Add(new DaySummary.Item()
                                {
                                    value = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]),
                                    name = reader["upiname"].ToString(),
                                    id = "UPI"
                                });
                            }
                        }

                        if (daySummary.Groups.Exists(e => e.type == DaySummary.Group.Types.ECCardPayment))
                        {
                            foreach (var eccardpayment in daySummary.Groups.Find(e => e.type == DaySummary.Group.Types.ECCardPayment).Items)
                            {
                                itemgroup.Items.Add(eccardpayment);
                            }
                            daySummary.Groups.RemoveAll(e => e.type == DaySummary.Group.Types.ECCardPayment);
                        }
                        itemgroup.value = itemgroup.Items.Sum(e => e.value);
                    }


                    itemgroup = new DaySummary.Group() { name = "CASH", type = DaySummary.Group.Types.Inventory, Items = new List<DaySummary.Item>() };
                    daySummary.Groups.Add(itemgroup);
                    VoucherDataService voucherDataService = new VoucherDataService() { Context = this.Context };
                    cashopening = voucherDataService.CashClosing(item, 0, VoucherDataService.CashMode.Both);

                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        value = cashopening,
                        name = "Opening Cash"
                    });
                    itemgroup.value += itemgroup.Items.Last().value;

                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        value = cashsales - cashrefund,
                        name = "Sales - Cash"
                    });
                    itemgroup.value += itemgroup.Items.Last().value;
                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        value = eccash,
                        name = "EC - Cash"
                    });
                    itemgroup.value += itemgroup.Items.Last().value;
                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]),
                                name = reader["display"].ToString()
                            });
                            if (itemgroup.Items.Last().name.StartsWith("Cash Deposit - "))
                                //itemgroup.value -= itemgroup.Items.Last().value;
                                itemgroup.Items.Last().value = itemgroup.Items.Last().value * -1;
                            //if (itemgroup.Items.Last().name.StartsWith("Cash Widhrawal - "))
                            //    itemgroup.value += itemgroup.Items.Last().value;
                            if (itemgroup.Items.Last().name.StartsWith("Main Cash to Petty Cash"))
                                //itemgroup.value -= itemgroup.Items.Last().value;
                                itemgroup.Items.Last().value = itemgroup.Items.Last().value * -1;
                            //if (itemgroup.Items.Last().name.StartsWith("Petty Cash to Main Cash"))
                            //    itemgroup.value += itemgroup.Items.Last().value;
                            if (itemgroup.Items.Last().name.StartsWith("Expense"))
                                //itemgroup.value -= itemgroup.Items.Last().value;
                                itemgroup.Items.Last().value = itemgroup.Items.Last().value * -1;
                            itemgroup.value += itemgroup.Items.Last().value;
                        }
                    }

                    if (pettycashexpense != 0)
                    {
                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            value = Math.Abs(pettycashexpense) * -1,
                            name = "Petty Cash Expenses"
                        });
                        itemgroup.value += itemgroup.Items.Last().value;
                    }
                    //itemgroup.Items.Add(new DaySummary.Item()
                    //{
                    //    value = itemgroup.value,
                    //    name = "Cash Closing"
                    //});

                    itemgroup = new DaySummary.Group() { name = "SALE QTY", type = DaySummary.Group.Types.Inventory, Items = new List<DaySummary.Item>() };
                    daySummary.Groups.Add(itemgroup);
                    if (reader.NextResult())
                    {
                        if (reader.Read())
                        {
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["sold"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sold"]),
                                name = "Sold Qty"
                            });
                            itemgroup.value = itemgroup.Items.Last().value;
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["return"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["return"]),
                                name = "Return Qty"
                            });
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]),
                                name = "Amount"
                            });
                        }
                    }

                    itemgroup = new DaySummary.Group() { name = "MOBILE", type = DaySummary.Group.Types.Inventory, Items = new List<DaySummary.Item>() };
                    daySummary.Groups.Add(itemgroup);
                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]),
                                name = reader["printingname"] == DBNull.Value ? "" : Convert.ToString(reader["printingname"]),
                            });
                        }
                        itemgroup.value = itemgroup.Items.Sum(e => e.value);
                    }

                    itemgroup = new DaySummary.Group() { name = "Discount", type = DaySummary.Group.Types.Inventory, Items = new List<DaySummary.Item>() };
                    daySummary.Groups.Add(itemgroup);
                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            itemgroup.Items.Add(new DaySummary.Item()
                            {
                                value = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]),
                                name = reader["printingname"] == DBNull.Value ? "" : Convert.ToString(reader["printingname"]),
                            });
                        }
                        itemgroup.value = itemgroup.Items.Sum(e => e.value);
                    }

                    itemgroup = new DaySummary.Group() { name = "INVENTORY", type = DaySummary.Group.Types.Inventory, Items = new List<DaySummary.Item>() };
                    daySummary.Groups.Add(itemgroup);

                    decimal currentstock = 0;
                    decimal todaytransferin = 0;
                    decimal todaytransferout = 0;
                    decimal directtransfer = 0;
                    decimal laterinward = 0;
                    decimal latersales = 0;

                    if (reader.NextResult() && reader.Read())
                    {
                        currentstock = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        todaytransferout = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        todaytransferin = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        directtransfer = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        laterinward = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        latersales = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    }

                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        name = "Stock as on " + item.todate.ToString("dd-MM-yyyy"),
                        value = currentstock - (laterinward - latersales)
                    });
                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        name = "Today Transfer In",
                        value = todaytransferin
                    });
                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        name = "Today Transfer Out",
                        value = todaytransferout
                    });
                    itemgroup.Items.Add(new DaySummary.Item()
                    {
                        name = "Direct In",
                        value = directtransfer
                    });
                    if (item.todate < DateTimeNow.Date)
                    {
                        itemgroup.Items.Add(new DaySummary.Item()
                        {
                            name = "Current Stock " + DateTimeNow.ToString("dd-MM-yyyy"),
                            value = currentstock
                        });
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null && conn.State != System.Data.ConnectionState.Closed)
                    conn.Close();
            }
            if (daySummary.Groups != null)
            {
                daySummary.Groups.ForEach(e => e.Items.RemoveAll(x => x.value == 0));
                daySummary.Groups.RemoveAll(e => e.Items.Count == 0);
            }
            return daySummary;
        }

        internal List<DaySettlement> SettlementSummaryByDay(RetailReportCreteria _reportcreteria)
        {
            string query = @"with settlementbyday
as
(
select billsettlementmaster.companyid,billsettlementmaster.locationid,billsettlementmaster.settlementon::date,
                            sum(billsettlementmaster.paid_cash) paid_cash,sum(billsettlementmaster.paid_upi) paid_upi,sum(paid_card) as paid_card,sum(paid_voucher) as paid_voucher,
                            sum(paid_credit) as paid_credit,sum(paid_debt) as paid_debt,sum(paid_discount) as paid_discount,
                            sum(paid_discount) as paid_discount,sum(case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'cash_return' as numeric) else 0 end) cashreturn, 
                            sum(case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'creditnote_refund' as numeric) else 0 end) creditnoterefund,
                            sum(cast(paymentinfo->>'adjustment_paid' as numeric)) adjustment_paid
                            from billsettlementmaster
                            where billsettlementmaster.isactive = true  
							and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate {0}
                            group by billsettlementmaster.companyid,billsettlementmaster.locationid,billsettlementmaster.settlementon::date
)

select settlementbyday.*,company.name companyname,referencelist.name locationname from settlementbyday
inner join company on company.id = companyid
inner join referencelist on referencelist.id = locationid";


            List<DaySettlement> lst = new List<DaySettlement>();


            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                string condition = "";
                if (_reportcreteria.locationid > 0)
                    condition += " and billsettlementmaster.locationid=@locationid ";

                if (_reportcreteria.companyid > 0)
                    condition += " and billsettlementmaster.companyid=@companyid ";
                if (_reportcreteria.counterid > 0)
                    condition += " and billsettlementmaster.counterid=@counterid ";

                NpgsqlCommand command = GetCommand(string.Format(query, condition), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DaySettlement oitem = new DaySettlement();
                        oitem.settlementon = reader["settlementon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["settlementon"]);
                        oitem.companyname = reader["companyname"] == DBNull.Value ? "" : Convert.ToString(reader["companyname"]);
                        oitem.locationname = reader["locationname"] == DBNull.Value ? "" : Convert.ToString(reader["locationname"]);
                        oitem.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        oitem.paid_cash = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]);
                        oitem.paid_card = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]);
                        oitem.paid_upi = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]);
                        oitem.paid_credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                        oitem.paid_debt = reader["paid_debt"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_debt"]);
                        oitem.paid_adjustment = reader["adjustment_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["adjustment_paid"]);
                        oitem.paid_refund = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        oitem.paid_discount = reader["paid_discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_discount"]);
                        oitem.paid_voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);
                        oitem.total = oitem.paid_cash + oitem.paid_card + oitem.paid_upi + oitem.paid_credit + oitem.paid_voucher - oitem.paid_refund;
                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        internal BillSummary SearchBillSummary(SaleRetailCreteria item)
        {
            string query = @"select sum(receivable+rounding) salevalue, count(*) billcount from bill 
    where billdate>=@fromdate  and billdate<@todate and billtype != 9 and bill.isactive = true 
    and bill.isb2b=@isb2b and bill.locationid = @locationid and bill.companyid = @companyid and counterid=@counterid ; 

    select sum(receivable+rounding) salevalue, count(*) billcount from bill 
    where billdate>=@fromdate  and billdate<@todate and bill.isactive = true and bill.isreturn=true
    and bill.isb2b=@isb2b and bill.locationid = @locationid and bill.companyid = @companyid and counterid=@counterid; 

    select billno,billdate,billtype,settled,isreturn,returnbillno,iscancel,receivable+rounding receivable from bill 
    where billdate>=@fromdate  and billdate<@todate and bill.isactive = true 
    and billtype = 9 and bill.iscancel=true and bill.isreturn=false and bill.locationid = @locationid 
    and bill.companyid = @companyid and counterid=@counterid
    order by id;

    select billno from bill 
    where billdate>=@fromdate  and billdate<@todate and billtype != 9 and bill.isactive = true 
    and bill.isb2b=@isb2b and bill.locationid = @locationid and bill.companyid = @companyid and counterid=@counterid 
    order by id limit 1;

    select billno from bill 
    where billdate>=@fromdate  and billdate<@todate and billtype != 9 and bill.isactive = true 
    and bill.isb2b=@isb2b and bill.locationid = @locationid and bill.companyid = @companyid and counterid=@counterid 
    order by id desc limit 1
    ";

            BillSummary result = new BillSummary();
            List<SaleRecord> lst = new List<SaleRecord>();
            NpgsqlConnection conn = CreateConnection();

            if (item.companyid <= 0)
            {
                query = query.Replace("and bill.companyid = @companyid", "");
            }
            if (item.counterid <= 0)
            {
                query = query.Replace("and counterid=@counterid", "");
            }
            try
            {
                conn.Open();
                var command = GetCommand(GetSQL4B2B("", query), conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = item.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = item.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = item.counterid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = item.fromdate.Date;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = item.todate.AddDays(1).Date;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = item.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    if (reader.Read())
                    {
                        result.netsale = reader["salevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salevalue"]);
                        result.billcount = reader["billcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["billcount"]);
                    }
                    if (reader.NextResult() && reader.Read())
                    {
                        result.returnvalue = reader["salevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salevalue"]);
                        result.returnbillcount = reader["billcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["billcount"]);
                    }
                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            SaleRecord oitem = new SaleRecord();
                            oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            oitem.billno = reader["billno"] == DBNull.Value ? "" : Convert.ToString(reader["billno"]);
                            oitem.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            lst.Add(oitem);
                        }
                        if (lst.Count > 0)
                        {
                            result.cancelbillcount = lst.Count;
                            result.cancelvalue = lst.Sum(e => e.amount);
                        }
                    }
                    result.totalsale = result.netsale + (result.returnvalue * -1) + result.cancelvalue;

                    if (reader.NextResult() && reader.Read())
                    {
                        result.startingbillno = reader["billno"] == DBNull.Value ? "" : Convert.ToString(reader["billno"]);
                    }
                    if (reader.NextResult() && reader.Read())
                    {
                        result.endingbillno = reader["billno"] == DBNull.Value ? "" : Convert.ToString(reader["billno"]);
                    }
                }
                conn.Close();
                result.cancelledbills = lst;
            }
            catch (Exception exp)
            {
                if (conn != null && conn.State != System.Data.ConnectionState.Closed)
                    conn.Close();
            }
            return result;
        }

        public PettycashVoucher GetPettyCashSummary(SaleRetailCreteria item)
        {
            var response = new PettycashVoucher();
            VoucherDataService VoucherData = new VoucherDataService() { Context = this.Context };

            LedgerDataService ledgerDataService = new LedgerDataService() { Context = this.Context };
            var allpettycash = ledgerDataService.Search(new LedgerCreteria()
            {
                typeid = 13
            });
            foreach (var ledger in allpettycash)
            {
                response.opening += VoucherData.CashClosing(new SaleRetailCreteria()
                {
                    companyid = item.companyid,
                    locationid = item.locationid,
                    fromdate = item.fromdate
                }, 0, VoucherDataService.CashMode.PettyCash);

                var cashinout = VoucherData.CashInOut(new SaleRetailCreteria()
                {
                    companyid = item.companyid,
                    locationid = item.locationid,
                    fromdate = item.fromdate
                }, 0);

                response.cashexpense += cashinout.CashExpense;
                response.cashincome += cashinout.CashIncome;
                response.cashdeposit += cashinout.CashDeposit;
                response.cashwithdraw += cashinout.CashWithdraw;
            }
            return response;
        }
        internal DaySummary SearchDaySummary(SaleRetailCreteria item)
        {
            //select count(*),sum(case when  returnbillno like '~%' then 1 else 0 end) exchange,
            //sum(case when returnbillno like '~%' then receivable else 0 end) exchangevalue,
            //sum(case when returnbillno != '' and returnbillno not like '~%' then 1 else 0 end) cancel,
            //sum(case when returnbillno != '' and returnbillno not like '~%' then receivable else 0 end) cancelvalue from bill
            //where billdate >= @fromdate  and billdate<@todate and bill.isb2b= @isb2b
            //and billtype = 9 and bill.isactive = true and bill.locationid = @locationid and bill.companyid = @companyid;

            string query = @"
select count(*),sum(case when  isreturn=true then 1 else 0 end) exchange,
sum(case when isreturn=true then receivable else 0 end) exchangevalue,
sum(case when isreturn=false and iscancel=true then 1 else 0 end) cancel,
sum(case when isreturn=false and iscancel=true then receivable else 0 end) cancelvalue from bill
where billdate>=@fromdate  and billdate<@todate and bill.isb2b=@isb2b 
and billtype = 9 and bill.isactive = true and bill.locationid = @locationid and bill.companyid = @companyid;

select sum(cast(billattributes->>'rewardamount' as numeric)+
cast(billattributes->>'manualrewardamount' as numeric)) as rewards,
sum(case when receivable>0 then receivable+rounding else 0 end) sales,
sum(case when receivable<0 then receivable+rounding*-1::numeric else 0 end) salesreturn,
sum(additionaldiscount) cashdiscount,
sum(case when receivable<0 then 1 else 0 end) salesreturncount,
count(*) billcount
from bill 
where billdate>=@fromdate  and billdate<@todate and billtype != 9 and bill.isactive = true 
and bill.isb2b=@isb2b and bill.locationid = @locationid and bill.companyid = @companyid;

select sum(paid_cash) cash,
sum(paid_card) card,
sum(paid_upi) upi,
sum(paid_credit) credit,
sum(paid_voucher) voucher, 
sum(case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'cash_return' as numeric) else 0 end) cashreturn,
sum(case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'creditnote_refund' as numeric) else 0 end) creditnoterefund
from billsettlementmaster 
where settlementon>=@fromdate and settlementon<@todate and billsettlementmaster.locationid = @locationid  and billsettlementmaster.companyid = @companyid and billsettlementmaster.isactive = true;

Select sum(paidamount) advance from customerorder 
where customerorder.isactive=true and customerorder.status!=3 
and orderdate>=@fromdate and orderdate<@todate and isactive=true; 

select dledger.displayname,sum(voucheritems.amount) amount from voucher
inner join voucheritems on voucheritems.voucherid = voucher.id
inner join ledger cledger on cledger.id = adjustmentledgerid and cledger.typeid = 13
inner join ledger dledger on dledger.id = voucheritems.ledgerid 
where voucher.locationid = @locationid and voucherdate>=@fromdate and voucherdate <@todate and voucher.isactive = true and voucher.companyid=@companyid
group by dledger.displayname;

Select sum(billitems.qty) qty, sum(billitems.qty::numeric*stock.buyingprice::numeric) buyingprice, 
sum(billitems.tax) tax, sum(billitems.receivable) sellingprice
from bill 
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
inner join salablegoods on salablegoods.id = billitems.salablegoodsid
inner join stock on stock.id = salablegoods.stockid
where billdate>=@fromdate  and billdate<@todate and bill.isb2b=@isb2b 
and billtype != 9 and bill.isactive = true and bill.locationid = @locationid and bill.companyid = @companyid; ";

            List<Salablegoodshistory> lst = new List<Salablegoodshistory>();
            NpgsqlConnection conn = CreateConnection();

            if (item.companyid <= 0)
            {
                query = query.Replace("and voucher.companyid=@companyid", "").Replace("and billsettlementmaster.companyid = @companyid", "")
                            .Replace("and bill.companyid = @companyid", "");
            }
            decimal cashsales = 0;
            decimal cashrefund = 0;
            decimal cashinhand = 0;
            decimal closing = 0;
            DaySummary daySummary = new DaySummary();
            try
            {
                var voucherinfo = GetPettyCashSummary(item);
                conn.Open();
                var command = GetCommand(GetSQL4B2B("", query), conn);

                daySummary.Items = new List<DaySummary.Item>();
                daySummary.fromdate = item.fromdate;
                daySummary.todate = item.todate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = item.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = item.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = item.fromdate.Date;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = item.todate.AddDays(1).Date;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = item.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {

                    decimal exchangevalue = 0;
                    if (reader.Read())
                    {
                        exchangevalue = reader["exchangevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["exchangevalue"]);
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["exchange"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["exchange"]),
                            name = "exchange bills (With SR)",
                            id = "EXCHANGEBILLS"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["exchangevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["exchangevalue"]),
                            name = "exchange value (With SR)",
                            id = "EXCHANGEVALUE"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cancel"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cancel"]),
                            name = "cancel bills"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cancelvalue"] == DBNull.Value ? 0 : Math.Abs(Convert.ToDecimal(reader["cancelvalue"])),
                            name = "cancel values"
                        });
                    }

                    var exchangeitems = daySummary.Items;
                    daySummary.Items = new List<DaySummary.Item>();

                    if (reader.NextResult() && reader.Read())
                    {
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            istitle = true,
                            name = "Sales Summary"
                        });


                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["rewards"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rewards"]),
                            name = "Rewards"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            //value = (reader["sales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sales"])) + exchangevalue,
                            value = (reader["sales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sales"])),
                            name = "sales"
                        });


                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cashdiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashdiscount"]),
                            name = "cash discount"
                        });

                        if (!exchangeitems.Exists(e => e.id == "EXCHANGEVALUE"))
                        {
                            exchangeitems.Add(new DaySummary.Item()
                            {
                                name = "exchange value (With SR)"
                            });
                        }

                        if (!exchangeitems.Exists(e => e.id == "EXCHANGEBILLS"))
                        {
                            exchangeitems.Add(new DaySummary.Item()
                            {
                                name = "exchange bills (With SR)"
                            });
                        }

                        exchangeitems.Find(e => e.id == "EXCHANGEVALUE").value += reader["salesreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salesreturn"]);
                        exchangeitems.Find(e => e.id == "EXCHANGEBILLS").value += reader["salesreturncount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salesreturncount"]);

                        //daySummary.Items.Add(new DaySummary.Item()
                        //{
                        //    value = Convert.ToDecimal(reader["salesreturn"]),
                        //    name = "sales return"
                        //});

                        //daySummary.Items.Add(new DaySummary.Item()
                        //{
                        //    value = Convert.ToDecimal(reader["salesreturncount"]),
                        //    name = "sales return bills"
                        //});


                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["billcount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billcount"]),
                            name = "bill count"
                        });
                    }

                    daySummary.Items.AddRange(exchangeitems);

                    if (reader.NextResult() && reader.Read())
                    {
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            istitle = true,
                            name = "Settlement Summary"
                        });

                        cashsales = reader["cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash"]);
                        cashrefund = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash"]),
                            name = "cash sales"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["card"]),
                            name = "card sales"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["upi"]),
                            name = "upi sales"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["credit"]),
                            name = "credit sales"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucher"]),
                            name = "voucher sales"
                        });

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]),
                            name = "refund"
                        });
                    }

                    if (reader.NextResult() && reader.Read())
                    {
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = reader["advance"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["advance"]),
                            name = "Customer Advance"
                        });
                    }

                    decimal expense = 0;

                    if (reader.NextResult())
                    {
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            istitle = true,
                            name = "Petty Cash Expense"

                        });


                        while (reader.Read())
                        {
                            expense += reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]),
                                name = reader["displayname"].ToString()
                            });
                        }

                        cashinhand = cashsales - cashrefund + (voucherinfo.opening + voucherinfo.cashdeposit
                            - voucherinfo.cashwithdraw + voucherinfo.cashincome - voucherinfo.cashexpense);

                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = cashinhand,
                            name = "Cash In Hand"
                        });
                    }
                    else
                    {
                        daySummary.Items.Add(new DaySummary.Item()
                        {
                            value = cashsales - cashrefund,
                            name = "Cash In Hand"
                        });
                    }

                    if (reader.NextResult())
                    {
                        if (reader.Read())
                        {
                            var qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            var buyingprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                            var tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            var sellingprice = reader["sellingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sellingprice"]);
                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = qty,
                                name = "Billed Qty"
                            });
                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = sellingprice,
                                name = "Goods Sold"
                            });
                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = buyingprice,
                                name = "Cost Of Goods Sold"
                            });
                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = tax,
                                name = "Tax Of Goods Sold"
                            });
                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = sellingprice - (tax + buyingprice),
                                name = "Margin Of Goods Sold"
                            });

                            daySummary.Items.Add(new DaySummary.Item()
                            {
                                value = expense,
                                name = "Total Expenses"
                            });
                        }
                    }
                }

                conn.Close();

                if (daySummary.Items != null && daySummary.Items.Count > 0)
                {
                    daySummary.Items.RemoveAll(e => e.istitle);
                    daySummary.Items.ForEach(e =>
                    {
                        e.name = e.name.ToUpper();
                        e.value = Math.Round(e.value, 0);
                    });
                }
            }
            catch (Exception exp)
            {
                if (conn != null && conn.State != System.Data.ConnectionState.Closed)
                    conn.Close();
            }
            return daySummary;
        }
        internal List<DaySalesSummary> SearchDaySalesSummary(SaleRetailCreteria item)
        {
            List<CompanySettlement> lst = SettlementSummaryByCompany(new RetailReportCreteria()
            {
                fromdate = item.fromdate,
                todate = item.todate,
                locationid = item.locationid
            });

            List<DaySalesSummary> lstdaysummary = new List<DaySalesSummary>();
            foreach (var settlement in lst)
            {
                DaySalesSummary _daysummary = new DaySalesSummary();
                _daysummary.companyname = settlement.companyname;
                _daysummary.cashsales = settlement.paid_cash;
                _daysummary.cardsales = settlement.paid_card;
                _daysummary.upisales = settlement.paid_upi;
                _daysummary.creditsales = settlement.paid_credit;
                _daysummary.cashrefund = settlement.paid_refund;
                _daysummary.cashierdiscount = settlement.paid_discount;
                _daysummary.cashieradjustment = settlement.paid_adjustment;
                _daysummary.totalcollection = settlement.total;

                item.companyid = settlement.companyid;
                DaySummary salesdata = SearchDaySummaryAutoSettlement(item);
                if (salesdata != null && salesdata.Items != null && salesdata.Items.Count > 0)
                {
                    _daysummary.billcount = Convert.ToInt32(salesdata.Items.Exists(e => e.id == "BILLCOUNT") ? salesdata.Items.Find(e => e.id == "BILLCOUNT").value : 0);
                    _daysummary.totalsales = salesdata.Items.Exists(e => e.id == "TOTALSALES") ? salesdata.Items.Find(e => e.id == "TOTALSALES").value : 0;
                    _daysummary.billerdiscount = salesdata.Items.Exists(e => e.id == "BILLERDISCOUNT") ? salesdata.Items.Find(e => e.id == "BILLERDISCOUNT").value : 0;
                    _daysummary.returnbills = salesdata.Items.Exists(e => e.id == "EXCHANGEBILLS") ? salesdata.Items.Find(e => e.id == "EXCHANGEBILLS").value : 0;
                    _daysummary.returnvalue = salesdata.Items.Exists(e => e.id == "EXCHANGEVALUE") ? salesdata.Items.Find(e => e.id == "EXCHANGEVALUE").value : 0;
                    _daysummary.cancelbills = salesdata.Items.Exists(e => e.id == "CANCELBILLS") ? salesdata.Items.Find(e => e.id == "CANCELBILLS").value : 0;
                    _daysummary.cancelvalue = salesdata.Items.Exists(e => e.id == "CANCELVALUE") ? salesdata.Items.Find(e => e.id == "CANCELVALUE").value : 0;
                    _daysummary.approvedbills = salesdata.Items.Exists(e => e.id == "APPROVEDBILLS") ? salesdata.Items.Find(e => e.id == "APPROVEDBILLS").value : 0;
                    _daysummary.approvedvalue = salesdata.Items.Exists(e => e.id == "APPROVEDBILLVALUE") ? salesdata.Items.Find(e => e.id == "APPROVEDBILLVALUE").value : 0;
                }
                lstdaysummary.Add(_daysummary);
            }
            return lstdaysummary;
        }
