case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'cash_return' as numeric) else 0 end cashreturn, 
cast(paymentinfo->> 'cash_return' as numeric) voucheradjustedcashreturn,
case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'creditnote_refund' as numeric) else 0 end creditnoterefund, 
cast(paymentinfo->>'adjustment_paid' as numeric) adjustment, cast(paymentinfo->>'discount_paid' as numeric) discount 
from bill 
left outer join billsettlement on bill.id = billsettlement.billid and billsettlement.isactive = true
left outer join billsettlementmaster on billsettlementmaster.id = billsettlement.billsettlementmasterid and billsettlementmaster.isactive=true 
left outer join billsummary on billsummary.billsummaryid = bill.id
inner join referencelist location on location.id = billsettlementmaster.locationid
inner join referencelist counter on counter.id = billsettlementmaster.counterid
left outer join customer on bill.customerid = customer.id 
left outer join users on users.id = billsettlementmaster.createdby
left outer join employee on users.employeeid = employee.id
where bill.isactive=true and billsettlementmaster.isactive = true and 
((bill.billdate>=@fromdate and bill.billdate<@todate) or (billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate))
and bill.locationid = @locationid
and bill.billtype != 9 and bill.isb2b=false order by bill.id";

        const string SQL_Stock = @"select salablegoods.id, salablegoods.locationid,salablegoods.companyid,stock.invoiceitemid,inwardon,salablegoods.barcode,salablegoods.iqty,salablegoods.oqty,salablegoods.dqty,salablegoods.jqty,stock.serialno,
                                    stock.printingname,salablegoods.price,stock.buyingprice taxable,stock.buyingprice,stock.ibuyingprice,(stock.ibuyingprice-stock.buyingprice) tax,salablegoods.discount,salablegoods.stockid , stock.stockdate stockdate,
                                    salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty) rstock, stock.dealerprice,stock.serialno, supplier.name suppliername, brand.name brandname,
                                    products.productgroup, products.salescounterid, products.name as productname, stock.designid, stock.hsncode, products.sellingmode,
                                    items.sizeid, items.typeid, items.colourid,items.materialid,items.styleid,items.brandid,items.patternid,lrinvoiceitems.mrp,items.sleeveid,items.fitid,  
                                    style.name stylename,pattern.name patternname,size.name sizename, colour.name colourname,type.name typename,material.name materialname,sleeve.name sleevename,fit.name fitname,  
                                    pricetag.name pricetagname, EXTRACT(day from @current_date - lrinvoice.entrydate) age, lrentry.stockholdingperiod, EXTRACT(day from @current_date - stock.stockdate) age1,
                                    lrinvoiceitems.itbuscode
                                    from stock
									inner join salablegoods on salablegoods.stockid = stock.id and salablegoods.isactive = true
									left outer join lrinvoiceitems on lrinvoiceitems.id = stock.invoiceitemid and lrinvoiceitems.isactive = true 
									left outer join lrinvoice on lrinvoice.id=lrinvoiceitems.lrinvoiceid and lrinvoice.isactive=true
                                    left outer join lrentry on lrentry.id = lrinvoice.lrid
                                    left outer join items on items.id = stock.itemid
                                    left outer join products on products.id = stock.productid
                                    left outer join supplier on supplier.id = lrentry.supplierid
                        left outer join brand brand on brand.id = items.brandid
                        left outer join referencelist colour on colour.id = colourid
                        left outer join referencelist size on size.id = sizeid
                        left outer join referencelist style on style.id = styleid
                        left outer join referencelist pattern on pattern.id = patternid
                        left outer join referencelist material on material.id = materialid
                        left outer join referencelist type on type.id = typeid
                        left outer join referencelist sleeve on sleeve.id = sleeveid
                        left outer join referencelist fit on fit.id = fitid
                        left outer join referencelist pricetag on pricetag.id = stock.pricetagid
                                    where stock.isactive=true";

