        string SQL_SalesTax = @"Select bill.billdate::date,billitems.taxpercentage, sum(billitems.receivable) receivable, sum(billitems.tax) tax,sum(rounding) rounding
                        from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
