        const string SQL_SalesHSN = @"
Select billitems.hsncode, products.name, billitems.taxpercentage, sum(billitems.receivable) receivable, sum(billitems.qty) qty, sum(billitems.tax) tax,
case when products.sellingmode = 3 then 'M' else 'N' end as Measure
                        from bill 
                        inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        inner join salablegoods on salablegoods.id = billitems.salablegoodsid
                        inner join stock on stock.id = salablegoods.stockid
                        inner join products on products.id = stock.productid
                        where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end {0}
                        group by billitems.hsncode, products.name, billitems.taxpercentage,case when products.sellingmode = 3 then 'M' else 'N' end
                        UNION ALL
Select cast(additionalinfo->>'formula' as character varying(10)) as hsncode, Billadditionalcharges.name, Billadditionalcharges.taxpercentage, 
sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 0 qty, sum(Billadditionalcharges.tax) tax,
'N' as Measure
                        from bill inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                        inner join referencelist on referencelist.id = Billadditionalcharges.additionalchargestypeid
                        where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b 
                        and cast(additionalinfo->>'paytype' as character varying(10)) != 'EXPORTGST'
                        and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
