                        --and Billadditionalcharges.taxpercentage>0 and Billadditionalcharges.tax != 0
                        group by cast(additionalinfo->>'formula' as character varying(10)), Billadditionalcharges.name, Billadditionalcharges.taxpercentage, Measure
						order by hsncode ";

