        const string SQL_SalesBarcode = @"
Select stock.serialno, billitems.barcode, products.name productname, brand.name brandname, stock.designid, billitems.hsncode, 
style.name stylename,pattern.name patternname,size.name sizename, colour.name colourname,type.name typename,
material.name materialname, case when products.sellingmode = 3 then 'M' else 'N' end as Measure, supplier.name suppliername, lrinvoice.invoiceno, lrinvoice.invoicedate, 
bill.billno, bill.billdate, returnreason.name returnreason,
salablegoods.price, stock.buyingprice, stock.ibuyingprice,
billitems.taxpercentage, section.name sectionname, lrinvoiceitems.itbuscode,

CASE
WHEN CUSTOMERSTATEID IS NOT NULL  AND CUSTOMERSTATEID>0 THEN CUSTOMERSTATEID 
WHEN CUSTOMER.GSTNO IS NOT NULL AND CUSTOMER.GSTNO != '' AND CUSTOMER.STATEID>0 THEN CUSTOMER.STATEID 
ELSE CUSTOMER.STATEID END AS POSID,

bill.isinterstatesale, customer.name customername, customer.gstno, company.name companyname, location.name locationname,
sum(billitems.receivable) receivable, sum(billitems.qty) qty, sum(billitems.tax) tax,
sum(billitems.discount) discount, sum(billitems.schemediscount) schemediscount, 
sum(billitems.additionaldiscount::numeric * billitems.qty::numeric) additionaldiscount
from bill 
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
inner join salablegoods on salablegoods.id = billitems.salablegoodsid
inner join stock on stock.id = salablegoods.stockid
inner join products on products.id = stock.productid
inner join company on company.id = bill.companyid
inner join referencelist location on location.id = bill.locationid
left outer join customer on customer.id = bill.customerid
left outer join lrinvoiceitems on lrinvoiceitems.id = stock.invoiceitemid  and lrinvoiceitems.isactive = true
left outer join lrinvoice on  lrinvoice.id = lrinvoiceitems.lrinvoiceid  and lrinvoice.isactive = true
left outer join lrentry on lrentry.id=lrinvoice.lrid
left outer join supplier on supplier.id=lrentry.supplierid 
left outer join items on stock.itemid = items.id 
left outer join brand brand on brand.id = items.brandid
left outer join referencelist colour on colour.id = colourid
left outer join referencelist size on size.id = sizeid
left outer join referencelist style on style.id = styleid
left outer join referencelist pattern on pattern.id = patternid
left outer join referencelist material on material.id = materialid
left outer join referencelist type on type.id = typeid
left outer join referencelist section on section.id = products.salescounterid
left outer join referencelist returnreason on returnreason.id = bill.returnreasonid
where bill.isactive = true and billtype in (8, 9) and bill.isreturn=true and bill.unsettledcancelled=false
{0} and bill.billdate>=@fromdate and bill.billdate<@todate 
and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end 
{1}
group by stock.serialno, billitems.barcode, products.name, brand.name, stock.designid, billitems.hsncode, 
style.name,pattern.name,size.name, colour.name,type.name,material.name, bill.billno, bill.billdate, returnreason.name,
salablegoods.price, stock.buyingprice, stock.ibuyingprice, case when products.sellingmode = 3 then 'M' else 'N' end, supplier.name, 
lrinvoice.invoiceno, lrinvoice.invoicedate, billitems.taxpercentage, section.name, lrinvoiceitems.itbuscode,
bill.isinterstatesale, customer.name, customer.gstno, company.name, location.name,
CASE
WHEN CUSTOMERSTATEID IS NOT NULL  AND CUSTOMERSTATEID>0 THEN CUSTOMERSTATEID 
WHEN CUSTOMER.GSTNO IS NOT NULL AND CUSTOMER.GSTNO != '' AND CUSTOMER.STATEID>0 THEN CUSTOMER.STATEID 
ELSE CUSTOMER.STATEID END";

