        const string SQL_Salesman = @"with billcount as (
                    Select salesmanid, count(distinct bill.id) billcount
					from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                    where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate  {0}
                    and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
                    and case when @salesmanid=0 then billitems.salesmanid >= 0 else billitems.salesmanid = @salesmanid end
                    group by salesmanid
                    )
                    Select employeecode, employee.name, floor.name floor, section.name section, billcount.billcount, sum(billitems.qty) qty, sum(billitems.tax) tax, sum(billitems.receivable) amount,
                    sum(stock.buyingprice) buyingprice, sum(stock.ibuyingprice) buyingprice
					from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                    inner join stock on stock.id = billitems.stockid
					left outer join employee on salesmanid = employee.id
					left outer join referencelist section on section.id = employee.sectionid
                    left outer join referencelist floor on floor.id = employee.floorid
                    left outer join billcount on billcount.salesmanid = billitems.salesmanid
                    where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate  {0}
                    and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
                    and case when @salesmanid=0 then billitems.salesmanid >= 0 else billitems.salesmanid = @salesmanid end
                    group by employeecode, employee.name, section.name, floor.name, billcount.billcount
                    order by section.name,case when employeecode ~ '^[0-9]+$' then cast(employeecode as numeric) else cast(0 as numeric) end";

