        string SQL_SalesVsStockDashboard_Stock = @"select sum((salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty))::numeric*buyingprice) as value from salablegoods
                        inner join stock on stock.id = salablegoods.stockid
                        where salablegoods.isactive = true and (salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty))>0;
                        
                        select sum((stock.qty-(stock.transfered+stock.journalqty+stock.damagedqty+stock.returnqty))::numeric*buyingprice) as value from  stock
                        where stock.isactive = true and stock.qty-(stock.transfered+stock.journalqty+stock.damagedqty+stock.returnqty)>0;

                        select sum(buyingqty-(damagedqty+sellableqty)) as value from lrinvoiceitems
                        inner join lrinvoice on lrinvoice.id = lrinvoiceitems.lrinvoiceid  and lrinvoice.isactive = true
                        where lrinvoiceitems.isactive = true and lrinvoice.isactive and buyingqty-(damagedqty+sellableqty)>0;";

        string SQL_SalesVsStockDashboard_LocationFiltered = @"with basestock as
(
	select stock.id,stockdate::date,stock.qty-(stock.transfered+stock.journalqty+stock.damagedqty+stock.returnqty)::numeric*buyingprice stockvalue,
	stock.qty-(stock.transfered+stock.damagedqty+stock.returnqty+stock.journalqty) stockqty,buyingprice from stock
	where stock.isactive = true and stockdate>=@fromdate
),inword as 
(
	select sum(stockvalue) as value,stockdate date from basestock where stockqty>0 group by stockdate union all
    select sum((salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty))::numeric*buyingprice) as value,stockdate::date date from salablegoods
    inner join basestock on basestock.id = salablegoods.stockid
    where salablegoods.isactive = true and salablegoods.hasstock = true {0}
    and salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty)>0
    group by stockdate
	union all 
	select sum(billitems.qty::numeric*buyingprice) as value,stockdate date from billitems 
					    inner join salablegoods on salablegoods.id = billitems.salablegoodsid
					    inner join basestock on basestock.id = salablegoods.stockid
					    where billid in (select id from bill where bill.isactive = true {1} and billdate>=@fromdate)
					    group by stockdate
)
select * from inword;
select sum(billitems.receivable-billitems.tax) as value,billdate::date date, sum(billitems.qty::numeric*buyingprice) as cost from bill
                        inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        inner join stock on stock.id = billitems.stockid and stock.isactive = true
                        where bill.isactive = true and billtype!=9 and billdate>=@fromdate {1}
                        group by billdate::date;";

