                                        from salablegoods inner join salablegoodshistory on  salablegoodshistory.salablegoodsid = salablegoods.id
                                        inner join stock on stock.id = salablegoods.stockid 
                                        inner join products on products.id = stock.productid
                                        inner join users on users.id = salablegoodshistory.modifiedby
                                        left outer join items on items.id = stock.itemid 
                                        left outer join employee on employeeid = employee.id
                                        where actiontype = 1 ";

        const string SQL_StockAudit = @"select stock.id, stock.barcode, products.name printingname,stock.locationid, stockhistory.price,
                                        stockhistory.discount, stock.qty-(stock.transfered+stock.returnqty+stock.journalqty+stock.damagedqty) as currentqty, stockhistory.id, 
                                        stockhistory.qty-(stockhistory.transfered+stockhistory.returnqty+stockhistory.journalqty+stockhistory.damagedqty) as whenqty, stockhistory.auditqty, 
                                        stockhistory.modifiedon, stockhistory.modifiedby,employee.name as empname, stockhistory.reason
                                        from stock
										inner join stockhistory on  stockhistory.stockid = stock.id
                                        inner join products on products.id = stock.productid
                                        inner join users on users.id = stockhistory.modifiedby
                                        left outer join items on items.id = stock.itemid 
                                        left outer join employee on employeeid = employee.id
                                        where actiontype = 1 ";


        public List<RetailReport> SearchSales(SaleRetailCreteria _reportcreteria)
