            string SQL_APPBILL = @"Select bulkbill.id, bulkbill.isinterstatesale, customer.gstno, customercity.name as customercityname, location.name as location, counter.name as counter, employee.name employeename, customer.name customername, customer.mobileno,billno, billdate, rounding,(receivable+rounding) receivable, tax, discount, additionaldiscount, qty , bulkbill.billtype, returnreason.name retreason,bulkbill.createdby,bulkbill.modifiedby
                                    from bulkbill inner join referencelist location on location.id = bulkbill.locationid
                                    left outer join referencelist counter on counter.id = bulkbill.counterid
                                    left outer join referencelist returnreason on returnreason.id = bulkbill.returnreasonid
                                    left outer join users on users.id = bulkbill.createdby
                                    left outer join employee on employeeid = employee.id 
                                    left outer join customer on customer.id = bulkbill.customerid
                                    left outer join referencelist customercity on customercity.id = customer.cityid
                                    where bulkbill.isactive = true and bulkbill.billdate>=@fromdate and bulkbill.billdate<@todate
                                    and case when @locationid=0 then bulkbill.locationid <> 0 else bulkbill.locationid = @locationid end
                                    and case when @companyid=0 then bulkbill.companyid >= 0 else bulkbill.companyid = @companyid end 
                                    order by bulkbill.id";

