                            obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                            obill.customer = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            obill.productname = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                            obill.sizename = reader["customercityname"] == DBNull.Value ? "" : reader["customercityname"].ToString();
                            obill.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                            obill.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.returnreason = reader["retreason"] == DBNull.Value ? "" : reader["retreason"].ToString();
                            obill.remarks = reader["remarks"] == DBNull.Value ? "" : reader["remarks"].ToString();
                            obill.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);
                            obill.taxable = Math.Round((obill.amount + (obill.rounding * -1)) - obill.saletax, 2);
                            if (obill.isinterstatesale)
                            {
                                obill.billedqty = obill.saletax;
                            }
                            else
                            {
                                obill.journalqty = Math.Round((obill.saletax / 2), 2);
                                obill.balanceqty = Math.Round((obill.saletax / 2), 2);
                            }

                            if (_reportcreteria.mode == "4")
                            {
                                DateTime createdon = reader["createdon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["createdon"]);
                                DateTime modifiedon = reader["modifiedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["modifiedon"]);

                                if (createdon.ToString("dd/MM/yyyy hh:mm") != modifiedon.ToString("dd/MM/yyyy hh:mm"))
                                    obill.modifiedemployeename = reader["memployeename"] == DBNull.Value ? "" : reader["memployeename"].ToString();

