                                obill.discount = reader["summarydiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["summarydiscount"]);
                                obill.schemediscount = reader["summaryschemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["summaryschemediscount"]);
                                obill.discount = obill.discount - obill.schemediscount;
                                obill.istransfer = reader["istransfer"] == DBNull.Value ? false : Convert.ToBoolean(reader["istransfer"]);
                                obill.isexport = reader["isexport"] == DBNull.Value ? false : Convert.ToBoolean(reader["isexport"]);
                                obill.salerefname = reader["salerefname"] == DBNull.Value ? "" : reader["salerefname"].ToString();

                                obill.addlndiscount = obill.addlndiscount - obill.loyaltydiscount;

                                var total = obill.amount + obill.rounding + obill.discount + obill.addlndiscount + obill.schemediscount + obill.loyaltydiscount;
                                obill.total = total;
                                if (total != 0 && obill.discount != 0)
                                    obill.discountpercentage = Math.Round(obill.discount / total * 100, 2);
                                if (total != 0 && obill.addlndiscount != 0)
                                    obill.addlndiscountpercentage = Math.Round(obill.addlndiscount / total * 100, 2);
                                if (total != 0 && obill.schemediscount != 0)
                                    obill.schemediscountpercentage = Math.Round(obill.schemediscount / total * 100, 2);
                                if (total != 0 && obill.loyaltydiscount != 0)
                                    obill.loyaltydiscountpercentage = Math.Round(obill.loyaltydiscount / total * 100, 2);

                                string code = reader["customerstatecode"] == DBNull.Value ? "" : reader["customerstatecode"].ToString();
                                if (string.IsNullOrEmpty(code))
                                {
                                    code = reader["companystatecode"] == DBNull.Value ? "" : reader["companystatecode"].ToString();
                                    obill.placeofsupply = code + "-" + (reader["companystatename"] == DBNull.Value ? "" : reader["companystatename"].ToString());
                                    //obill.placeofsupply = "33-Tamil Nadu";
                                }
                                else
                                    obill.placeofsupply = code + "-" + (reader["customerstatename"] == DBNull.Value ? "" : reader["customerstatename"].ToString());
                            }
                            if (_reportcreteria.mode == "11")
                            {
                                obill.loyaltydiscount = reader["spentreward"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["spentreward"]);
                                obill.addlndiscount = reader["summaryadditionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["summaryadditionaldiscount"]);
                                obill.discount = reader["summarydiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["summarydiscount"]);
                                obill.schemediscount = reader["summaryschemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["summaryschemediscount"]);
                                obill.modifiedemployeename = reader["modifiedemployeename"] == DBNull.Value ? "" : reader["modifiedemployeename"].ToString();
                                obill.discount = obill.discount - obill.schemediscount;
                                if (obill.employeename == obill.modifiedemployeename)
                                    obill.modifiedemployeename = "";

                                obill.addlndiscount = obill.addlndiscount - obill.loyaltydiscount;

                                var total = obill.amount + obill.rounding + obill.discount + obill.addlndiscount + obill.schemediscount + obill.loyaltydiscount;
                                if (total != 0 && obill.discount != 0)
                                    obill.discountpercentage = Math.Round(obill.discount / total * 100, 2);
                                if (total != 0 && obill.addlndiscount != 0)
                                    obill.addlndiscountpercentage = Math.Round(obill.addlndiscount / total * 100, 2);
                                if (total != 0 && obill.schemediscount != 0)
                                    obill.schemediscountpercentage = Math.Round(obill.schemediscount / total * 100, 2);
                                if (total != 0 && obill.loyaltydiscount != 0)
                                    obill.loyaltydiscountpercentage = Math.Round(obill.loyaltydiscount / total * 100, 2);
                            }
                        }
                        else if (_reportcreteria.mode == "5")
                        {
                            obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                            obill.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                            obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            obill.serialno = reader["serialno"] == DBNull.Value ? "" : reader["serialno"].ToString();
                            obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.taxable = Math.Round(obill.amount - obill.saletax, 2);

                            obill.rate = reader["total"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["total"]);
                            obill.itemname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                            obill.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                            obill.productid = reader["productid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["productid"]);
                            obill.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                            obill.brandid = reader["brandid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["brandid"]);
                            obill.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                            obill.patternid = reader["patternid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["patternid"]);
                            obill.patternname = reader["patternname"] == DBNull.Value ? "" : reader["patternname"].ToString();
                            obill.styleid = reader["styleid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["styleid"]);
                            obill.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                            obill.sizeid = reader["sizeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["sizeid"]);
                            obill.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
                            obill.materialid = reader["materialid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["materialid"]);
                            obill.materialname = reader["materialname"] == DBNull.Value ? "" : reader["materialname"].ToString();
                            obill.typeid = reader["typeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["typeid"]);
                            obill.typename = reader["typename"] == DBNull.Value ? "" : reader["typename"].ToString();
                            obill.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                            obill.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                            //obill.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);

                        }
                        else if (_reportcreteria.mode == "6")
                        {
                            obill.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                            obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                            obill.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                            obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                            obill.customer = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            obill.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);
                            obill.taxable = Math.Round(obill.amount - obill.saletax, 2);
                            if (_reportcreteria.showsalesummary)
                                obill.serialno = reader["deliveryno"] == DBNull.Value ? "" : reader["deliveryno"].ToString();
                        }
                        else if (_reportcreteria.mode == "10")
                        {
                            obill.location = reader["companyname"] == DBNull.Value ? "" : reader["companyname"].ToString();
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);
                            obill.taxable = Math.Round(obill.amount - obill.saletax, 2);
                        }
                        else
                        {
                            if (!_reportcreteria.summary)
                            {
                                obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                                obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            }
                            if (_reportcreteria.unsettled && !_reportcreteria.summary)
                            {
                                obill.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                                obill.createdon = reader["createdon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["createdon"]);
                                obill.employeecode = reader["employeecode"] == DBNull.Value ? "" : reader["employeecode"].ToString();
                            }
                            //obill.billtype = reader["billtype"] == DBNull.Value ? Bill.BillTypes.Cash : (Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                            obill.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                            obill.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                            obill.taxable = Math.Round(obill.amount - obill.saletax, 2);
                            if (_reportcreteria.showdetail && !_reportcreteria.summary)
                            {
                                obill.rate = reader["total"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["total"]);
                                obill.itemname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                                obill.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                                obill.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                                obill.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                                obill.patternname = reader["patternname"] == DBNull.Value ? "" : reader["patternname"].ToString();
                                obill.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                                obill.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
                                obill.materialname = reader["materialname"] == DBNull.Value ? "" : reader["materialname"].ToString();
                                obill.typename = reader["typename"] == DBNull.Value ? "" : reader["typename"].ToString();
                                obill.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                                obill.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);
                            }
                        }
                        lst.Add(obill);
                    }
                }

                if (_reportcreteria.mode == "12" && _reportcreteria.billtype != 10)
                {
                    if (_reportcreteria.isb2b == false && (_reportcreteria.billtype == 0 || _reportcreteria.billtype == 1))
                    {
                        if (_reportcreteria.billtype == 0)
                            command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesBillTaxwise, "and bill.billtype!=9")), conn);
                        else
                            command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesBillTaxwise, "and bill.billtype=" + _reportcreteria.billtype.ToString())), conn);
                    }
                    else if (_reportcreteria.billtype == 8)
                        command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesBillTaxwise, "and isreturn=true ")), conn);
                    else if (_reportcreteria.billtype == 9)
                        command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesBillTaxwise, "and isreturn=false and iscancel=true ")), conn);
                    else
                        command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesBillTaxwise, "")), conn);

                    command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                    command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                    command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                    command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                    command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            //bill.id,taxpercentage,sum(billitems.receivable) receivable,sum(billitems.tax) tax
                            long id = reader["id"] != DBNull.Value ? Convert.ToInt64(reader["id"]) : 0;
                            if (lst.Exists(e => e.id == id))
                            {
                                decimal taxpercentage = reader["taxpercentage"] != DBNull.Value ? Convert.ToDecimal(reader["taxpercentage"]) : 0;
                                decimal receivable = reader["receivable"] != DBNull.Value ? Convert.ToDecimal(reader["receivable"]) : 0;
                                decimal tax = reader["tax"] != DBNull.Value ? Convert.ToDecimal(reader["tax"]) : 0;
                                bool isinterstatesale = reader["isinterstatesale"] != DBNull.Value ? Convert.ToBoolean(reader["isinterstatesale"]) : false;
                                var rptitm = lst.Find(e => e.id == id);
                                if (rptitm.taxsplits == null) rptitm.taxsplits = new List<RetailReport.TaxSplit>();
                                rptitm.taxsplits.Add(new RetailReport.TaxSplit()
                                {
                                    percentage = taxpercentage,
                                    tax = tax,
                                    taxable = receivable - tax,
                                    igst = isinterstatesale
                                });
                            }
                        }
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public List<RetailReport> SearchSalesMargin(SaleRetailCreteria _reportcreteria)
        {
            List<RetailReport> lst = new List<RetailReport>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;
                DateTime today = _reportcreteria.fromdate.Date;
                DateTime nextdate = _reportcreteria.todate.Date.AddDays(1);

                command = GetCommand(GetSQL4B2B("", SQL_SalesMargin), conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        RetailReport obill = new RetailReport();
                        obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        obill.rate = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                        obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        obill.amount = reader["sellingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sellingprice"]);
                        obill.taxable = Math.Round(obill.amount - obill.saletax, 2);
                        obill.total = Math.Round(obill.taxable - obill.rate, 2);
                        if (obill.taxable > 0 && obill.rate > 0)
                            obill.addlndiscount = Math.Round(((obill.taxable / obill.rate) * 100) - 100, 2);
                        obill.rounding = obill.amount + obill.discount;
                        lst.Add(obill);
                    }
                }

                command.CommandText = @"    select bill.billdate::date, location.name as location, count(bill.id) billcount from bill 
    inner join referencelist location on location.id = bill.locationid 
    where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate
    and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
    group by bill.billdate::date, location.name";

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        var billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        var location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        var billcount = reader["billcount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billcount"]);

                        if (lst.Exists(e => e.billdate == billdate && e.location == location))
                        {
                            RetailReport item = lst.Find(e => e.billdate == billdate && e.location == location);
                            item.billcount = Convert.ToInt32(billcount);
                        }
                    }
                }

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }

            return lst;
        }
