                        ostock.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        ostock.iqty = reader["iqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["iqty"]);
                        ostock.whqty = reader["stock"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stock"]);
                        ostock.itemname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                        ostock.price = reader["price"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["price"]);
                        ostock.buyingprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                        ostock.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        ostock.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        ostock.hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                        ostock.createdon = reader["createdon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["createdon"]);
                        ostock.glncode = reader["serialno"] == DBNull.Value ? "" : reader["serialno"].ToString();
                        ostock.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                        ostock.invoiceno = reader["displayinvoiceno"] == DBNull.Value ? "" : reader["displayinvoiceno"].ToString();
                        ostock.invoicedate = reader["displayinvoicedate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["displayinvoicedate"]);

                        lst.Add(ostock);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public List<Stockmarkerdetail> StockMarker(StockReportCreteria _reportcreteria)
        {
            List<Stockmarkerdetail> lst = new List<Stockmarkerdetail>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                QueryBuilder qb = new QueryBuilder();
                qb.CurrentQuery = SQL_StockMarker;
                qb.AddParameter("stockmarker.isactive", true, "=");

                if (_reportcreteria.multicompany && _reportcreteria.companyid > 0)
                    qb.AddParameter("stock.companyid", _reportcreteria.companyid, "=");

                if (_reportcreteria.markerid > 0)
                    qb.AddParameter("stockmarker.markerid", _reportcreteria.markerid, "=");

                if (_reportcreteria.locationid > 0)
                    qb.AddParameter("stockmarker.locationid", _reportcreteria.locationid, "=");
                command = qb.GetCommand(conn);

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        Stockmarkerdetail ostockmarker = new Stockmarkerdetail();
                        ostockmarker.isactive = reader["isactive"] == DBNull.Value ? false : Convert.ToBoolean(reader["isactive"]);
                        ostockmarker.createdby = reader["createdby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["createdby"]);
                        ostockmarker.modifiedby = reader["modifiedby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["modifiedby"]);
                        ostockmarker.version = reader["version"] == DBNull.Value ? 0 : Convert.ToInt32(reader["version"]);
                        ostockmarker.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                        ostockmarker.createdon = reader["createdon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["createdon"]);
                        ostockmarker.modifiedon = reader["modifiedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["modifiedon"]);
                        ostockmarker.stockid = reader["stockid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["stockid"]);
                        ostockmarker.markerid = reader["markerid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["markerid"]);
                        ostockmarker.stockqty = reader["stockqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockqty"]);
                        ostockmarker.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        ostockmarker.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        ostockmarker.salablegoodsid = reader["salablegoodsid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["salablegoodsid"]);
                        ostockmarker.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        ostockmarker.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                        ostockmarker.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                        ostockmarker.patternname = reader["patternname"] == DBNull.Value ? "" : reader["patternname"].ToString();
                        ostockmarker.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                        ostockmarker.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                        ostockmarker.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
