        public List<Pricechangehistory> PriceChangerHistory(RetailReportCreteria _reportcreteria)
        {
            List<Pricechangehistory> lst = new List<Pricechangehistory>();
            if (_reportcreteria.locationid == 0)
            {
                lst.AddRange(PriceChanger(_reportcreteria));
