        public List<Pricechangehistory> PriceChanger(RetailReportCreteria _reportcreteria)
        {
            bool iswarehouse = false;
            if (_reportcreteria.locationid > 0)
            {
                ReferencelistDataService referencelistDataService = new ReferencelistDataService();
                var locationinfo = referencelistDataService.Search(new ReferencelistCreteria()
                {
                    id = _reportcreteria.locationid
                });
                if (locationinfo.Count > 0 && locationinfo[0].additionalinfo != null && locationinfo[0].additionalinfo.iswarehouse)
                {
                    iswarehouse = true;
                    _reportcreteria.locationid = 0;
                }
            }
            List<Pricechangehistory> lst = new List<Pricechangehistory>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;
                QueryBuilder qb = new QueryBuilder();

                qb.CurrentQuery = iswarehouse || _reportcreteria.locationid == -9 ? SQL_PriceChangerStock : SQL_PriceChanger;
                if (_reportcreteria.fromdate != DateTime.MinValue && _reportcreteria.todate != DateTime.MinValue)
                {
                    qb.AddParameter("pricechange.createdon", "fromdate", _reportcreteria.fromdate.Date, ">=");
                    qb.AddParameter("pricechange.createdon", "todate", _reportcreteria.todate.AddDays(1).Date, "<");
                }
                if (iswarehouse || _reportcreteria.locationid == -9)
                {
                    if (!string.IsNullOrEmpty(_reportcreteria.barcode))
                        qb.AddParameter("stock.barcode", _reportcreteria.barcode, "=");
                    qb.AddParameter("pricechange.iswarehouse", true, "=");

                    if (_reportcreteria.barcodes != null && _reportcreteria.barcodes.Count > 0)
                    {
                        if (_reportcreteria.barcodes.Count > 1000)
                            throw new Exception("Please refine your search criteria - too many Barcode seleted.");

                        qb.AddInParamer("stock.barcode", string.Join(",", _reportcreteria.barcodes.ConvertAll(e => "'" + WebAPI.Data.Utility.SafeSQL(e) + "'")));
                    }
                }
                else
                {
                    qb.AddParameter("pricechange.iswarehouse", false, "=");
                    if (_reportcreteria.locationid > 0)
                        qb.AddParameter("salablegoods.locationid", _reportcreteria.locationid, "=");
                    if (_reportcreteria.companyid > 0)
                        qb.AddParameter("salablegoods.companyid", _reportcreteria.companyid, "=");
                    if (!string.IsNullOrEmpty(_reportcreteria.barcode))
                        qb.AddParameter("salablegoods.barcode", _reportcreteria.barcode, "=");

                    if (_reportcreteria.barcodes != null && _reportcreteria.barcodes.Count > 0)
                    {
                        if (_reportcreteria.barcodes.Count > 1000)
                            throw new Exception("Please refine your search criteria - too many Barcode seleted.");

                        qb.AddInParamer("salablegoods.barcode", string.Join(",", _reportcreteria.barcodes.ConvertAll(e => "'" + WebAPI.Data.Utility.SafeSQL(e) + "'")));
                    }
                }
                qb.SortField = "changedon";
                command = qb.GetCommand(conn);

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        Pricechangehistory oitem = new Pricechangehistory();

                        oitem.reason = reader["reason"] == DBNull.Value ? "" : reader["reason"].ToString();
                        oitem.createdon = reader["changedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["changedon"]);
                        oitem.empname = reader["empname"] == DBNull.Value ? "" : reader["empname"].ToString();
                        oitem.printingname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                        oitem.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        oitem.stockqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.nprice = reader["newprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["newprice"]);
                        oitem.oprice = reader["oldprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["oldprice"]);
                        oitem.ndiscount = reader["newdiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["newdiscount"]);
                        oitem.odiscount = reader["olddiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["olddiscount"]);
                        oitem.ndealerprice = reader["newdealerprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["newdealerprice"]);
                        oitem.odealerprice = reader["olddealerprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["olddealerprice"]);
                        oitem.changevalue = (oitem.nprice - oitem.ndiscount) - (oitem.oprice - oitem.odiscount);
                        oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        oitem.locationname = reader["locationname"] == DBNull.Value ? "" : reader["locationname"].ToString();
                        oitem.buyingprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                        oitem.sectionname = reader["sectionname"] == DBNull.Value ? "" : reader["sectionname"].ToString();

                        oitem.sellingmode = reader["sellingmode"] == DBNull.Value ? 0 : Convert.ToInt32(reader["sellingmode"]);
                        oitem.stockid = reader["stockid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["stockid"]);

                        oitem.totalcost = oitem.stockqty * oitem.buyingprice;
                        oitem.totalchangevalue = oitem.stockqty * ((oitem.nprice - oitem.ndiscount) - oitem.buyingprice);

                        if (iswarehouse)
                            oitem.locationname += "(WAREHOUSE)";
                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

