        public List<Splitbarcodehistory> SearchSplitDetails(SplitbarcodehistoryCreteria _splitbarcodehistory)
        {
            const string SQL_SearchSplit = @"select splitbarcodehistory.id, splitqty, noofqtyeachbarcode, 
                noofnewbarcode, barcodelist, splitbarcodehistory.barcode oldbarcode, replace(cast(itemlist as character varying(20)), '""', '') newbarcode,
                salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty) stockqty, 
                employee.name createdbyemployee, splitbarcodehistory.modifiedon, splitbarcodehistory.createdon
                from splitbarcodehistory INNER JOIN LATERAL json_array_elements (case when splitbarcodehistory.barcodelist is null or splitbarcodehistory.barcodelist::text ='null' then '[]'::json else splitbarcodehistory.barcodelist :: json end) itemlist ON true
                left outer join salablegoods on salablegoods.barcode = replace(cast(itemlist as character varying(20)), '""', '')
                left outer join users on users.id = splitbarcodehistory.createdby
                left outer join employee on employee.id = users.employeeid
                where splitbarcodehistory.isactive=True And splitbarcodehistory.barcode != replace(cast(itemlist as character varying(20)), '""', '')
                ";


            List<Splitbarcodehistory> lst = new List<Splitbarcodehistory>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                QueryBuilder qb = new QueryBuilder();
                qb.CurrentQuery = SQL_SearchSplit;
                if (_splitbarcodehistory.companyid > 0)
                    qb.AddParameter("splitbarcodehistory.companyid", _splitbarcodehistory.companyid, "=");
                if (_splitbarcodehistory.locationid > 0)
                    qb.AddParameter("splitbarcodehistory.locationid", _splitbarcodehistory.locationid, "=");
                if (_splitbarcodehistory.fromdate.Year > 1900)
                    qb.AddParameter("splitbarcodehistory.createdon", "fromdate", _splitbarcodehistory.fromdate.Date, ">=");
                if (_splitbarcodehistory.todate.Year > 1900)
                    qb.AddParameter("splitbarcodehistory.createdon", "todate", _splitbarcodehistory.todate.Date.AddDays(1), "<");
                qb.SortField = "Splitbarcodehistory.id";

                command = qb.GetCommand(conn);

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        Splitbarcodehistory oitem = new Splitbarcodehistory();
                        oitem.modifiedon = reader["modifiedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["modifiedon"]);
                        oitem.createdon = reader["createdon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["createdon"]);
                        oitem.createdemployee = reader["createdbyemployee"] == DBNull.Value ? "" : reader["createdbyemployee"].ToString();

                        oitem.barcode = reader["oldbarcode"] == DBNull.Value ? "" : reader["oldbarcode"].ToString();
                        oitem.noofqtyeachbarcode = reader["noofqtyeachbarcode"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["noofqtyeachbarcode"]);
                        oitem.newbarcode = reader["newbarcode"] == DBNull.Value ? "" : reader["newbarcode"].ToString();
                        oitem.stockqty = reader["stockqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockqty"]);
                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _splitbarcodehistory);
            }
            return lst;
        }

