        public List<SettlementReport> SearchSettlementByCompany(RetailReportCreteria _reportcreteria)
        {
            var result = SearchSaleVsSettlement(_reportcreteria, true);
            if (_reportcreteria.companyid > 0)
                result.RemoveAll(e => e.companyid != _reportcreteria.companyid);

            if (_reportcreteria.counterid > 0)
                result.RemoveAll(e => e.counterid != _reportcreteria.counterid);

            List<SettlementReport> response = new List<SettlementReport>();
            foreach (var item in result.GroupBy(e => new { e.counter, e.employeename, e.location }))
            {
                response.Add(new SettlementReport()
                {
                    paid_cash = item.Sum(e => e.cash),
                    paid_card = item.Sum(e => e.card),
                    paid_upi = item.Sum(e => e.upi),
                    paid_credit = item.Sum(e => e.paid_credit),
                    paid_voucher = item.Sum(e => e.paid_voucher),
                    adjustment_paid = item.Sum(e => e.adjustment_paid),
                    return_cash = item.Sum(e => e.return_cash),
                    discount = item.Sum(e => e.discount),
                    location = item.Key.location,
                    counter = item.Key.counter,
                    employeename = item.Key.employeename
                });
            }
            foreach (var oitem in response)
            {
                oitem.totalsale = oitem.paid_cash + oitem.paid_card + oitem.paid_upi + oitem.paid_credit + oitem.paid_voucher - oitem.return_cash;
            }
            return response;
        }

        public List<SettlementReport> SearchSettlementForReconcile(RetailReportCreteria _reportcreteria)
        {
            const string query = @"with billsettle as 
(select billsettlementmaster.id, billsettlementmaster.receivable,billsettlementmaster.paidamount,paid_upi, paid_card,paid_credit, 
billsettlementmaster.locationid, billsettlementmaster.counterid , cast(paymentinfo->>'card_bankid' as bigint) bankid, 
cast(paymentinfo->>'upiproviderid' as bigint) upiproviderid
from billsettlementmaster 
left outer join users on users.id = billsettlementmaster.createdby
where billsettlementmaster.isactive=true and paid_card>0
and billsettlementmaster.settlementon>=@fromdate 
and billsettlementmaster.settlementon<@todate
and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end
)
select billsettle.bankid, bank.name as bankname, sum(paid_card) card from billsettle
left outer join referencelist bank on bank.id = billsettle.bankid
group by billsettle.bankid, bank.name;

-- Voucher Received
select schemelist->>'code' code,cast(schemelist->>'amount' as numeric) amount
from billsettlementmaster 
left outer join users on users.id = billsettlementmaster.createdby
LEFT JOIN LATERAL json_array_elements (paymentinfo->'voucherinformation') schemelist ON true
where billsettlementmaster.isactive=true
AND (cast(paymentinfo->>'voucher_paid' as numeric))>0
and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end;

-- Sales and Sales Return value respective with cashier
--select sum(case when billsettlement.billamount>0 then billsettlement.billamount else 0 end) sales,
--sum(case when billsettlement.billamount>0 then 0 else billsettlement.billamount end) salesreturn
--from billsettlementmaster
--inner join billsettlement on billsettlement.billsettlementmasterid = billsettlementmaster.id
--left outer join users on users.id = billsettlementmaster.createdby
--where billsettlementmaster.isactive=true and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
--and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
--and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
--and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
--and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end;

select sum(case when billitems.receivable>0 then billitems.receivable else 0 end) sales,
sum(case when billitems.receivable>0 then 0 else billitems.receivable end) salesreturn
from billsettlementmaster
inner join billsettlement on billsettlement.billsettlementmasterid = billsettlementmaster.id
inner join bill on bill.id = billsettlement.billid and bill.billtype != 9
inner join billitems on billitems.billid = bill.id and billitems.isactive = true 
left outer join users on users.id = billsettlementmaster.createdby
where billsettlementmaster.isactive=true and bill.isactive=true and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end;

