--sum(cast(paymentinfo->>'cash_refund' as numeric)) cash_refund,
--sum(cast(paymentinfo->>'cash_paid' as numeric)) cash_paid,
--sum(cast(paymentinfo->>'cash_return' as numeric)) cash_return,
--sum(cast(paymentinfo->>'adjustment_paid' as numeric)) adjustment_paid
--from billsettlementmaster
--left outer join users on users.id = billsettlementmaster.createdby
--where billsettlementmaster.isactive=true and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
--and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
--and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
--and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
--and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end;

-- Cash Return/Refund done by the cashier
select billsettlementmaster.id,billsettlementmaster.code code,
paid_voucher,
case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'cash_return' as numeric) else 0 end amount,
case when paid_voucher>0 then cast(paymentinfo->> 'cash_return' as numeric)  else 0 end voucheradjustedcashreturn
from billsettlementmaster
left outer join users on users.id = billsettlementmaster.createdby
where billsettlementmaster.isactive=true and (billsettlementmaster.paidamount<0 OR paid_voucher>0) and cast(paymentinfo->>'cash_return' as numeric) > 0
and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end;

-- Credit Sales done in Sales POS screen 
select
cast(paymentinfo->>'credit_paid' as numeric) amount, customer.name
from billsettlementmaster
left outer join customer on customer.id = billsettlementmaster.customerid
left outer join users on users.id = billsettlementmaster.createdby
where billsettlementmaster.isactive=true and cast(paymentinfo->>'credit_paid' as numeric)>0
and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end;

-- Customer Credit Note
select billsettlementmaster.code,vouchervalue amount from coupons 
inner join billsettlementmaster on billsettlementmaster.id = coupons.billsettlementmasterid
where coupons.isactive=true and entrytype=1 and coupons.createdon>=@fromdate and coupons.createdon<@todate 
and billsettlementmasterid>0 and coupons.counterid = @counterid and issuedby=@cashierid;

-- Gift Voucher Issue CRM
select coupons.name, coupons.seqcode code,vouchervalue amount from coupons 
where coupons.isactive=true and entrytype=1 and coupons.createdon>=@fromdate and coupons.createdon<@todate 
and billsettlementmasterid=0 and coupons.counterid = @counterid and issuedby=@cashierid;

select ledger.displayname,voucheritems.amount from voucher
inner join voucheritems on voucheritems.voucherid = voucher.id
inner join ledger on ledger.id = voucheritems.ledgerid
where voucher.vouchertype = 13 and voucherdate>=@fromdate and voucherdate<@todate
and cast(voucher.attributes->>'counterid' as numeric)=@counterid and voucheritems.isactive=true;

select ledger.displayname,voucheritems.amount from voucher
inner join voucheritems on voucheritems.voucherid = voucher.id
inner join ledger on ledger.id = voucheritems.ledgerid
where voucher.sourcetype=1 and voucherdate>=@fromdate and voucherdate<@todate
and cast(voucher.attributes->>'counterid' as numeric)=@counterid and voucheritems.isactive=true;
 
-- Credit Customer Payment through Finance
select customer.name,customerpayment.amount,paymentinfo from customerpayment
inner join customer on customer.id = customerpayment.customerid
where customerpayment.isactive=true and customerpayment.counterid = @counterid and customerpayment.locationid = @locationid
and paidon>=@fromdate and paidon<@todate;

with billsettleupi as 
(
select billsettlementmaster.id, billsettlementmaster.receivable,
billsettlementmaster.paidamount,paid_upi, paid_card,paid_credit, 
billsettlementmaster.locationid, billsettlementmaster.counterid , 
cast(paymentinfo->>'card_bankid' as bigint) bankid, 
cast(paymentinfo->>'upiproviderid' as bigint) upiproviderid
from billsettlementmaster 
left outer join users on users.id = billsettlementmaster.createdby
where billsettlementmaster.isactive=true 
and billsettlementmaster.settlementon>=@fromdate 
and billsettlementmaster.settlementon<@todate
and cast(paymentinfo->>'upi_paid' as numeric)>0
and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
and case when @counterid=0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end
)

select billsettleupi.upiproviderid, bank.name as bankname, sum(paid_upi) upi from billsettleupi
left outer join referencelist bank on bank.id = billsettleupi.upiproviderid
group by billsettleupi.upiproviderid, bank.name;

Select cast(paymentlist->>'mode' as numeric) as mode, sum(cast(paymentlist->>'amount' as numeric)) paid
from customerorder 
INNER JOIN LATERAL json_array_elements (customerorder.paymentinfo :: json) paymentlist ON true
--left outer join users on users.id = customerorder.modifiedby
where customerorder.isactive=true and customerorder.status != 3
and cast(paymentlist->>'actionon' as timestamp without time zone)>=@fromdate
and cast(paymentlist->>'actionon' as timestamp without time zone)<@todate
and  cast(paymentlist->>'locationid' as bigint) = @locationid
and cast(paymentlist->>'counterid' as bigint) = @counterid
and cast(paymentlist->>'receivedby' as bigint) = @cashierid
--and case when @cashierid=0 then (users.employeeid <> 0 or users.employeeid=0 or users.employeeid is null) else users.employeeid = @cashierid end
group by cast(paymentlist->>'mode' as numeric)
";

            int system_custcreditnoteabove = Services.ConfigManager.Instance(Context.OrganizationID).Config.system_custcreditnoteabove;
            List<SettlementReport> lst = SearchSettlement(_reportcreteria);
            if (lst != null && lst.Count == 1)
            {
                CashDataService cashDataService = new CashDataService() { Context = this.Context };
                var cashlist = cashDataService.Search(new CashCreteria()
                {
                    id = _reportcreteria.cashid
                });
                if (cashlist.Count == 1 && _reportcreteria.cashid > 0)
                    lst[0].cashclosing = cashlist[0];

                lst[0].lstcarddetails = new List<SettlementReport.CardPaymentDetails>();
                lst[0].lstupidetails = new List<SettlementReport.CardPaymentDetails>();
                lst[0].lstexpensedetails = new List<SettlementReport.CounterExpense>();
                lst[0].lstcreditcollection = new List<SettlementReport.CreditCollection>();

                DateTime today = _reportcreteria.fromdate.Date;
                DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
                NpgsqlConnection conn = CreateConnection();
                try
                {
                    conn.Open();

                    NpgsqlCommand command = null;
                    command = GetCommand(query, conn);
                    command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                    command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                    command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                    command.Parameters.Add("cashierid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                    command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                    command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            SettlementReport.CardPaymentDetails oitem = new SettlementReport.CardPaymentDetails();
                            oitem.amount = reader["card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["card"]);
                            oitem.bankid = reader["bankid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["bankid"]);
                            oitem.bankname = reader["bankname"] == DBNull.Value ? "" : reader["bankname"].ToString();
                            lst[0].lstcarddetails.Add(oitem);
                        }

                        if (reader.NextResult())
                        {
                            lst[0].creditnotereceived_list = new List<SettlementReport.CreditNote>();
                            while (reader.Read())
                            {
                                lst[0].creditnotereceived += reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                lst[0].creditnotereceived_list.Add(new SettlementReport.CreditNote()
                                {
                                    code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString(),
                                    amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"])
                                });
                            }
                        }

                        if (reader.NextResult())
                        {
                            if (reader.Read())
                            {
                                lst[0].salesvalue = reader["sales"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["sales"]);
                                lst[0].salesreturnvalue = Math.Abs(reader["salesreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salesreturn"]));
                            }
                        }

                        //if (reader.NextResult())
                        //{
                        //    if (reader.Read())
                        //    {
                        //        lst[0].discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        //        lst[0].refund_cash = reader["cash_refund"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash_refund"]);
                        //        lst[0].paid_cash = reader["cash_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash_paid"]);
                        //        lst[0].return_cash = reader["cash_return"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cash_return"]);
                        //        lst[0].adjustment_paid = reader["adjustment_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["adjustment_paid"]);
                        //    }
                        //}


                        if (reader.NextResult())
                        {
                            lst[0].refund_cash_list = new List<SettlementReport.CreditNote>();
                            while (reader.Read())
                            {
                                long id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                                decimal refundamount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                decimal voucheradjreturn = reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"]);
                                decimal paid_voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);
                                if (refundamount > 0 || voucheradjreturn > 0)
                                {
                                    if (lst[0].refund_cash_list.Exists(x => x.id == id))
                                        lst[0].refund_cash_list.Find(x => x.id == id).code += "," +
                                             (reader["code"] == DBNull.Value ? "" : reader["code"].ToString());
                                    else
                                    {
                                        if (system_custcreditnoteabove > 0 && voucheradjreturn > 0)
                                        {
                                            if (refundamount == 0 && paid_voucher > 0)
                                                refundamount = voucheradjreturn;
                                        }

                                        lst[0].refund_cash_list.Add(new SettlementReport.CreditNote()
                                        {
                                            id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]),
                                            code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString(),
                                            amount = refundamount
                                        });
                                    }
                                }
                            }
                        }

                        if (reader.NextResult())
                        {
                            lst[0].credit_list = new List<SettlementReport.CounterExpense>();
                            while (reader.Read())
                            {
                                lst[0].credit_list.Add(new SettlementReport.CounterExpense()
                                {
                                    name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString(),
                                    amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"])
                                });
                            }
                        }
                        // Customer Credit Note
                        if (reader.NextResult())
                        {
                            lst[0].creditnoteissued_list = new List<SettlementReport.CreditNote>();
                            while (reader.Read())
                            {
                                lst[0].creditnoteissued += reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                lst[0].creditnoteissued_list.Add(new SettlementReport.CreditNote()
                                {
                                    code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString(),
                                    amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]),
                                });
                            }
                        }

                        // Gift Voucher Issue (CRM)
                        if (reader.NextResult())
                        {
                            lst[0].giftvoucherissued_list = new List<SettlementReport.CreditNote>();
                            lst[0].customerorderadvance_list = new List<SettlementReport.CreditNote>();
                            while (reader.Read())
                            {
                                string name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                                if (name.IndexOf("CUSTOMER ADVANCE") > 0)
                                {
                                    lst[0].customerorderadvance += reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                    lst[0].customerorderadvance_list.Add(new SettlementReport.CreditNote()
                                    {
                                        code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString(),
                                        amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]),
                                    });
                                }
                                else
                                {
                                    lst[0].giftvoucherissued += reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                    lst[0].giftvoucherissued_list.Add(new SettlementReport.CreditNote()
                                    {
                                        code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString(),
                                        amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]),
                                    });
                                }
                            }
                        }


                        //petty cash on voucher
                        if (reader.NextResult())
                        {
                            while (reader.Read())
                            {
                                SettlementReport.CounterExpense oitem = new SettlementReport.CounterExpense();
                                oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                oitem.name = reader["displayname"] == DBNull.Value ? "" : reader["displayname"].ToString();
                                lst[0].lstexpensedetails.Add(oitem);
                            }
                        }

                        //petty cash screen
                        if (reader.NextResult())
                        {
                            while (reader.Read())
                            {
                                SettlementReport.CounterExpense oitem = new SettlementReport.CounterExpense();
                                oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                oitem.name = reader["displayname"] == DBNull.Value ? "" : reader["displayname"].ToString();
                                lst[0].lstexpensedetails.Add(oitem);
                            }
                        }

                        if (reader.NextResult())
                        {
                            while (reader.Read())
                            {
                                SettlementReport.CreditCollection oitem = new SettlementReport.CreditCollection();
                                oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                                oitem.name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                                oitem.paymentinfo_json = reader["paymentinfo"] == DBNull.Value ? "" : reader["paymentinfo"].ToString();
                                lst[0].lstcreditcollection.Add(oitem);
                            }
                        }

                        if (reader.NextResult())
                        {
                            while (reader.Read())
                            {
                                SettlementReport.CardPaymentDetails oitem = new SettlementReport.CardPaymentDetails();
                                oitem.amount = reader["upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["upi"]);
                                oitem.bankid = reader["upiproviderid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["upiproviderid"]);
                                oitem.bankname = reader["bankname"] == DBNull.Value ? "DEFAULT" : reader["bankname"].ToString();
                                lst[0].lstupidetails.Add(oitem);
                            }
                        }
                        if (reader.NextResult())
                        {
                            while (reader.Read())
                            {
                                decimal advancepaid = reader["paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid"]);
                                int mode = reader["mode"] == DBNull.Value ? 0 : Convert.ToInt32(reader["mode"]);

                                if (mode == 3)
                                    lst[0].paid_cash += advancepaid;
                                else if (mode == 5)
                                    lst[0].paid_upi += advancepaid;
                                else
                                    lst[0].paid_card += advancepaid;

                                lst[0].advancepaid += advancepaid;
                            }
                        }
                    }

                    conn.Close();
                }
                catch (Exception exp)
                {
                    if (conn != null) conn.Close();
                    WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);

                }
            }
            return lst;
        }

        public List<SettlementReport> SearchSettlement(RetailReportCreteria _reportcreteria)
        {
            if (Context.HasPermission(PermissionSet.hidecashcollection, InfyPOS.Common.Action.View))
            {
                if (_reportcreteria.fromdate.Date < DateTimeNow.Date.AddDays(-2))
                {
                    throw new Exception("Don't have permission to view collection report");
                }
            }

            if (_reportcreteria.companyid > 0 && _reportcreteria.multicompany)
            {
                return SearchSettlementByCompany(_reportcreteria);
            }

            int system_custcreditnoteabove = Services.ConfigManager.Instance(Context.OrganizationID).Config.system_custcreditnoteabove;
            List<SettlementReport> lst = new List<SettlementReport>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                if (_reportcreteria.showdetail)
                    command = GetCommand(SQL_BankwiseSettlement, conn);
                else if (_reportcreteria.showsalesummary)
                    command = GetCommand(SQL_DaywiseSettlement, conn);
                else if (_reportcreteria.showmarker)
                    command = GetCommand(SQL_CashierwiseSettlement, conn);
                //else if (_reportcreteria.locationid == 0)
                //    command = GetCommand(SQL_SettlementSummary, conn);
                else
                    command = GetCommand(SQL_Settlement, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("cashierid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SettlementReport oitem = new SettlementReport();
                        oitem.paid_cash = reader["cashpaid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashpaid"]);
                        oitem.paid_card = reader["card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["card"]);
                        oitem.paid_upi = reader["upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["upi"]);
                        oitem.paid_credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                        oitem.paid_voucher = reader["voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucher"]);

                        oitem.adjustment_paid = reader["adjustment"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["adjustment"]);
                        oitem.return_cash = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        oitem.creditnote_refund = reader["creditnoterefund"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["creditnoterefund"]);
                        oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();

                        if (system_custcreditnoteabove > 0
                            && (reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"])) > 0)
                        {
                            oitem.return_cash += reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"]);
                        }

                        if (_reportcreteria.showdetail || _reportcreteria.showmarker || !_reportcreteria.showsalesummary)
                        {
                            oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                            oitem.cashierid = reader["cashierid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["cashierid"]);
                            oitem.receiptdate = reader["settlementon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["settlementon"]);

                            oitem.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        }
                        if ((_reportcreteria.showdetail || !_reportcreteria.showsalesummary) && !_reportcreteria.showmarker)
                        {
                            oitem.counterid = reader["counterid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["counterid"]);
                            oitem.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        }

                        if (_reportcreteria.showdetail)
                        {
                            oitem.bankid = reader["bankid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["bankid"]);
                            if (oitem.bankid == 0)
                                oitem.bankid = reader["upiproviderid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["upiproviderid"]);
                        }
                        if (_reportcreteria.showsalesummary && !_reportcreteria.showdetail)
                            oitem.receiptdate = reader["settlementon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["settlementon"]);

                        oitem.totalsale = oitem.paid_cash + oitem.paid_card + oitem.paid_upi + oitem.paid_credit + oitem.paid_voucher + oitem.adjustment_paid + oitem.discount - (oitem.return_cash + oitem.creditnote_refund);
                        oitem.totalcollection = oitem.paid_cash + oitem.paid_card + oitem.paid_upi + oitem.paid_credit + oitem.paid_voucher - (oitem.return_cash + oitem.creditnote_refund);
                        lst.Add(oitem);
                    }
                }

                if (!_reportcreteria.showdetail && !_reportcreteria.showsalesummary && lst.Count > 0)
                {
                    CashDataService CashData = new CashDataService() { Context = this.Context };
                    List<Cash> lstcashinfo = CashData.Search(new CashCreteria() { locationid = _reportcreteria.locationid, paidon = _reportcreteria.fromdate });

                    foreach (SettlementReport item in lst)
                    {
                        if (lstcashinfo.Exists(e => e.locationid == item.locationid && e.counterid == item.counterid
                        && e.cashierid == item.cashierid && e.paidon.Date == item.receiptdate.Date))
                        {
                            var cashitem = lstcashinfo.Find(e => e.locationid == item.locationid && e.counterid == item.counterid
                            && e.cashierid == item.cashierid && e.paidon.Date == item.receiptdate.Date);
                            item.openingcash = cashitem.openingamount;
                            item.closingcash = cashitem.closingamount;
                            item.cashdifference = item.closingcash - (item.openingcash + item.paid_cash - item.return_cash);
                        }
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public List<SaleVsSettlement> SearchSaleVsSettlement(RetailReportCreteria _reportcreteria, bool onlysettlement)
        {
            List<SaleVsSettlement> lst = new List<SaleVsSettlement>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            int system_custcreditnoteabove = Services.ConfigManager.Instance(Context.OrganizationID).Config.system_custcreditnoteabove;

            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                string query = SQL_SaleVsSettlement;
                if (_reportcreteria.locationid == 0)
                    query = query.Replace("and bill.locationid = @locationid", "");
                if (onlysettlement)
                    query = query.Replace("(bill.billdate>=@fromdate and bill.billdate<@todate) or ", "");
                NpgsqlCommand command = null;
                command = GetCommand(query, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SaleVsSettlement oitem = new SaleVsSettlement();
                        oitem.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        oitem.counterid = reader["counterid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["counterid"]);
                        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        oitem.billamount = reader["billamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billamount"]);
                        oitem.billdiscount = reader["billdiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billdiscount"]);
                        oitem.settlementno = reader["code"] == DBNull.Value ? "" : reader["code"].ToString();
                        oitem.settlementdate = reader["receiptdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receiptdate"]);
                        oitem.paid = reader["paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid"]);
                        oitem.cash = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]);
                        oitem.card = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]);
                        oitem.upi = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]);
                        oitem.paid_credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                        oitem.paid_voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);
                        oitem.adjustment_paid = reader["adjustment"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["adjustment"]);
                        oitem.return_cash = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        oitem.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        oitem.customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        oitem.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                        oitem.grossvalue = oitem.billamount + oitem.billdiscount + oitem.discount;
                        if (oitem.billdate.Date == oitem.settlementdate.Date)
                            oitem.issameday = true;

                        if (system_custcreditnoteabove > 0
                            && (reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"])) > 0)
                        {
                            if (oitem.return_cash == 0 && oitem.paid_voucher > 0)
                                oitem.return_cash = reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"]);
                        }

                        lst.Add(oitem);
                    }
                }

                var adjustedList = new SortedDictionary<string, SaleVsSettlement>();
                foreach (var items in lst.GroupBy(e => e.settlementno))
                {
                    if (items.Count() > 1)
                    {
                        var citem = Newtonsoft.Json.JsonConvert.DeserializeObject<SaleVsSettlement>(Newtonsoft.Json.JsonConvert.SerializeObject(items.First()));
                        adjustedList.Add(citem.settlementno, citem);
                        foreach (var nitem in items.Where(e => e.billamount == 0).ToList())
                        {
                            nitem.cash = 0;
                            nitem.return_cash = 0;
                            nitem.card = 0;
                            nitem.paid_credit = 0;
                            nitem.adjustment_paid = 0;
                            nitem.discount = 0;
                            nitem.paid = 0;
                            nitem.paid_voucher = 0;
                            nitem.upi = 0;
                        }

                        foreach (var nitem in items.Where(e => e.billamount < 0).ToList())
                        {
                            nitem.cash = 0;
                            nitem.return_cash = 0;
                            nitem.card = 0;
                            nitem.paid_credit = 0;
                            nitem.adjustment_paid = 0;
                            nitem.discount = 0;
                            nitem.paid = 0;
                            nitem.paid_voucher = 0;
                            nitem.upi = 0;

                            var balance = nitem.billamount * -1;


                            if (balance > 0 && citem.return_cash > 0)
                            {
                                if (citem.return_cash >= balance)
                                {
                                    nitem.return_cash = balance;
                                    balance = 0;
                                }
                                else
                                {
                                    nitem.return_cash = balance;
                                    balance = 0;
                                }
                            }


                            if (citem.cash > 0 && balance > 0)
                            {
                                if (citem.cash >= balance)
                                {
                                    nitem.cash = balance * -1;
                                    balance = 0;
                                }
                                else
                                {
                                    nitem.cash = citem.cash * -1;
                                    balance -= citem.cash;
                                }
                            }

                            if (balance > 0 && citem.paid_credit > 0)
                            {
                                if (citem.paid_credit >= balance)
                                {
                                    nitem.paid_credit = balance * -1;
                                    balance = 0;
                                }
                                else
                                {
                                    nitem.paid_credit = citem.paid_credit * -1;
                                    balance -= citem.paid_credit;
                                }
                            }




                            if (balance != 0)
                            {
                                nitem.cash += (balance * -1);
                                nitem.iscancelled = true;
                            }

                            nitem.paid = nitem.billamount;
                        }

                        foreach (var oitem in items.Where(e => e.billamount > 0))
                        {
                            oitem.cash = 0;
                            oitem.return_cash = 0;
                            oitem.card = 0;
                            oitem.paid_credit = 0;
                            oitem.adjustment_paid = 0;
                            oitem.discount = 0;
                            oitem.paid = 0;
                            oitem.paid_voucher = 0;
                            oitem.upi = 0;

                            if (citem.cash > 0)
                            {
                                if (oitem.billamount <= citem.cash)
                                {
                                    oitem.cash = oitem.billamount;
                                    citem.cash -= oitem.billamount;
                                    oitem.paid = oitem.billamount;
                                }
                                else
                                {
                                    oitem.cash = citem.cash;
                                    citem.cash = 0;
                                    oitem.paid = oitem.cash;
                                }
                            }

                            if (citem.card > 0)
                            {
                                if ((oitem.billamount - oitem.paid) <= citem.card)
                                {
                                    oitem.card = (oitem.billamount - oitem.paid);
                                    citem.card -= (oitem.billamount - oitem.paid);
                                    oitem.paid += (oitem.billamount - oitem.paid);
                                }
                                else
                                {
                                    oitem.card = citem.card;
                                    citem.card = 0;
                                    oitem.paid += oitem.card;
                                }
                            }

                            if (citem.upi > 0)
                            {
                                if ((oitem.billamount - oitem.paid) <= citem.upi)
                                {
                                    oitem.upi = (oitem.billamount - oitem.paid);
                                    citem.upi -= (oitem.billamount - oitem.paid);
                                    oitem.paid += (oitem.billamount - oitem.paid);
                                }
                                else
                                {
                                    oitem.upi = citem.upi;
                                    citem.upi = 0;
                                    oitem.paid += oitem.upi;
                                }
                            }

                            if (citem.paid_voucher > 0)
                            {
                                if ((oitem.billamount - oitem.paid) <= citem.paid_voucher)
                                {
                                    oitem.paid_voucher = (oitem.billamount - oitem.paid);
                                    citem.paid_voucher -= (oitem.billamount - oitem.paid);
                                    oitem.paid += (oitem.billamount - oitem.paid);
                                }
                                else
                                {
                                    oitem.paid_voucher = citem.paid_voucher;
                                    citem.paid_voucher = 0;
                                    oitem.paid += oitem.paid_voucher;
                                }
                            }

                            if (citem.paid_credit > 0)
                            {
                                if ((oitem.billamount - oitem.paid) <= citem.paid_credit)
                                {
                                    oitem.paid_credit = (oitem.billamount - oitem.paid);
                                    citem.paid_credit -= (oitem.billamount - oitem.paid);
                                    oitem.paid += (oitem.billamount - oitem.paid);
                                }
                                else
                                {
                                    oitem.paid_credit = citem.paid_credit;
                                    citem.paid_credit = 0;
                                    oitem.paid += oitem.paid_credit;
                                }
                            }

                            if ((oitem.billamount - oitem.paid) > 0)
                            {
                                if (citem.discount > 0)
                                {
                                    if ((oitem.billamount - oitem.paid) <= citem.discount)
                                    {
                                        oitem.discount = (oitem.billamount - oitem.paid);
                                        citem.discount -= (oitem.billamount - oitem.paid);
                                        oitem.paid += (oitem.billamount - oitem.paid);
                                    }
                                    else
                                    {
                                        oitem.discount = citem.discount;
                                        citem.discount = 0;
                                        oitem.paid += oitem.discount;
                                    }
                                }
                            }

                            if ((oitem.billamount - oitem.paid) > 0)
                            {
                                if (citem.adjustment_paid > 0)
                                {
                                    if ((oitem.billamount - oitem.paid) <= citem.adjustment_paid)
                                    {
                                        oitem.adjustment_paid = (oitem.billamount - oitem.paid);
                                        citem.adjustment_paid -= (oitem.billamount - oitem.paid);
                                        oitem.paid += (oitem.billamount - oitem.paid);
                                    }
                                    else
                                    {
                                        oitem.adjustment_paid = citem.adjustment_paid;
                                        citem.adjustment_paid = 0;
                                        oitem.paid += oitem.adjustment_paid;
                                    }
                                }
                            }

                            if ((oitem.billamount - oitem.paid) != 0)
                            {
                                oitem.cash += (oitem.billamount - oitem.paid);
                                oitem.paid += (oitem.billamount - oitem.paid);
                                oitem.iscancelled = true;
                            }

                        }
                    }
                }



                //command = GetCommand(SQL_CancelledBills, conn);
                //command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                //command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                //command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                //command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                //using (System.Data.IDataReader reader = command.ExecuteReader())
                //{
                //    while (reader.Read())
                //    {
                //        SaleVsSettlement oitem = new SaleVsSettlement();
                //        oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                //        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                //        oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                //        oitem.billamount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                //        oitem.settlementno = reader["returnbillno"] == DBNull.Value ? "" : reader["returnbillno"].ToString();
                //        oitem.settlementdate = reader["returnbilldate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["returnbilldate"]);
                //        oitem.paid = reader["returnreceivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["returnreceivable"]);

                //        if (oitem.billdate.Date == oitem.settlementdate.Date)
                //            oitem.issameday = true;
                //        oitem.iscancelled = true;
                //        lst.Add(oitem);
                //    }
                //}

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }

            if (_reportcreteria.companyid > 0)
            {
                lst.RemoveAll(e => e.companyid != _reportcreteria.companyid);
            }
            return lst.OrderBy(e => e.settlementdate).ToList();
        }
        public List<SettlementReport> SearchSettlementDetail(RetailReportCreteria _reportcreteria)
        {
            string SQL_Settlementbycode = @"select billsettlementmaster.id, billsettlementmaster.code, billsettlementmaster.settlementon,
        billsettlementmaster.receivable,billsettlementmaster.paidamount, billsettlementmaster.createdby,
        paid_cash, paid_card, paid_upi, paid_credit, paid_voucher, 
        case when billsettlementmaster.paidamount < 0 then cast(paymentinfo->> 'cash_return' as numeric) else 0 end cashreturn,
        cast(paymentinfo->> 'cash_return' as numeric) voucheradjustedcashreturn,
        cast(paymentinfo->> 'adjustment_paid' as numeric) adjustment_paid, 
        cast(paymentinfo->> 'discount_paid' as numeric) discount_paid, 
        cast(paymentinfo->> 'card_no' as varchar) as card_no,
        cast(paymentinfo->> 'discount_adjusted' as numeric) discount_adjusted, 
        cast(paymentinfo->> 'card_typeid' as bigint) as card_typeid,
        cast(paymentinfo->>'card_bankid' as bigint) bankid,
        cast(paymentinfo->>'upiproviderid' as bigint) upiproviderid, 
        paymentinfo->>'discount_info' discount_info, employee.name as employeename,
        location.name as location, counter.name as counter, disapprovedby.name as discountapprovedby from billsettlementmaster
        inner join referencelist location on location.id = billsettlementmaster.locationid
        inner join referencelist counter on counter.id = billsettlementmaster.counterid
        left outer join employee on employee.id = billsettlementmaster.cashierid
		left outer join employee disapprovedby on disapprovedby.id = cast(paymentinfo->>'discount_approvedBy' as bigint) 
        where billsettlementmaster.isactive=true and billsettlementmaster.code=@setno";

            string SQL_Settlementbylocation = @"select billsettlementmaster.id, billsettlementmaster.code, billsettlementmaster.settlementon,
        billsettlementmaster.receivable,billsettlementmaster.paidamount, billsettlementmaster.createdby,
        paid_cash, paid_card,paid_upi, paid_credit, paid_voucher, 
        case when billsettlementmaster.paidamount < 0 then cast(paymentinfo->> 'cash_return' as numeric) else 0 end cashreturn,
        cast(paymentinfo->> 'cash_return' as numeric) voucheradjustedcashreturn,
        cast(paymentinfo->> 'adjustment_paid' as numeric) adjustment_paid, 
        cast(paymentinfo->> 'discount_paid' as numeric) discount_paid, 
        cast(paymentinfo->> 'card_no' as varchar) as card_no,
        cast(paymentinfo->> 'discount_adjusted' as numeric) discount_adjusted, 
        cast(paymentinfo->> 'card_typeid' as bigint) as card_typeid,
        cast(paymentinfo->>'card_bankid' as bigint) bankid,
        cast(paymentinfo->>'upiproviderid' as bigint) upiproviderid, 
        paymentinfo->>'discount_info' discount_info, employee.name as employeename,
        location.name as location, counter.name as counter, disapprovedby.name as discountapprovedby from billsettlementmaster
        inner join referencelist location on location.id = billsettlementmaster.locationid
        inner join referencelist counter on counter.id = billsettlementmaster.counterid
        left outer join employee on employee.id = billsettlementmaster.cashierid
		left outer join employee disapprovedby on disapprovedby.id = cast(paymentinfo->>'discount_approvedBy' as bigint) 
        where billsettlementmaster.isactive=true and billsettlementmaster.settlementon >= @fromdate and billsettlementmaster.settlementon < @todate
        and case when @locationid = 0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
        and case when @counterid = 0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
        and case when @companyid = 0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end";

            string SQL_SettlementbyCashier = @"select billsettlementmaster.id, billsettlementmaster.code,employee.name as employeename,
        billsettlementmaster.receivable,billsettlementmaster.paidamount, billsettlementmaster.createdby, billsettlementmaster.settlementon,
        paid_cash, paid_card,paid_upi, paid_credit, paid_voucher, 
        case when billsettlementmaster.paidamount < 0 then cast(paymentinfo->> 'cash_return' as numeric) else 0 end cashreturn,
        cast(paymentinfo->> 'cash_return' as numeric) voucheradjustedcashreturn,
        cast(paymentinfo->> 'adjustment_paid' as numeric) adjustment_paid, 
        cast(paymentinfo->> 'discount_paid' as numeric) discount_paid, 
        cast(paymentinfo->> 'card_no' as varchar) as card_no,
        cast(paymentinfo->> 'discount_adjusted' as numeric) discount_adjusted, 
        cast(paymentinfo->> 'card_typeid' as bigint) as card_typeid,
        cast(paymentinfo->>'card_bankid' as bigint) bankid,
        cast(paymentinfo->>'upiproviderid' as bigint) upiproviderid,
        paymentinfo->>'discount_info' discount_info, location.name as location, counter.name as counter, 
        disapprovedby.name as discountapprovedby from billsettlementmaster
        inner join referencelist location on location.id = billsettlementmaster.locationid
        inner join referencelist counter on counter.id = billsettlementmaster.counterid
	    inner join employee on employee.id = billsettlementmaster.cashierid
		left outer join employee disapprovedby on disapprovedby.id = cast(paymentinfo->>'discount_approvedBy' as bigint) 
        where billsettlementmaster.isactive=true and billsettlementmaster.cashierid=@cashierid and billsettlementmaster.settlementon >= @fromdate and billsettlementmaster.settlementon < @todate
        and case when @locationid = 0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
        and case when @counterid = 0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
        and case when @companyid = 0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end";

            long chequerefid = 0;
            int system_custcreditnoteabove = Services.ConfigManager.Instance(Context.OrganizationID).Config.system_custcreditnoteabove;
            ReferencelistDataService referencelistDataService = new ReferencelistDataService() { Context = this.Context };
            List<ReferenceItem> upilist = referencelistDataService.SearchListWithParent(new ReferencelistCreteria()
            {
                types = "UPIPROVIDER".Split(',').ToList()
            });
            if (upilist != null && upilist.Count > 0)
            {
                if (upilist.Exists(e => e.name.ToUpper() == "CHEQUE"))
                    chequerefid = upilist.Find(x => x.name.ToUpper() == "CHEQUE").id;
            }
            List<SettlementReport> lst = new List<SettlementReport>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;

                if (string.IsNullOrEmpty(_reportcreteria.setno) && (_reportcreteria.cashierid == 0))
                    command = GetCommand(SQL_Settlementbylocation, conn);
                else if (_reportcreteria.cashierid != 0)
                    command = GetCommand(SQL_SettlementbyCashier, conn);
                else
                    command = GetCommand(SQL_Settlementbycode, conn);

                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("cashierid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.cashierid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("setno", NpgsqlTypes.NpgsqlDbType.Varchar).Value = _reportcreteria.setno;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SettlementReport oitem = new SettlementReport();
                        oitem.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                        oitem.receiptno = reader["code"] == DBNull.Value ? "" : reader["code"].ToString();
                        oitem.receiptdate = reader["settlementon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["settlementon"]);
                        oitem.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        oitem.paidamount = reader["paidamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paidamount"]);
                        oitem.paid_cash = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]);
                        oitem.paid_card = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]);
                        oitem.paid_upi = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]);
                        oitem.paid_credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                        oitem.paid_voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);
                        oitem.adjustment_paid = reader["adjustment_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["adjustment_paid"]);
                        oitem.return_cash = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        oitem.discount = reader["discount_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount_paid"]);
                        oitem.discount_adjusted = reader["discount_adjusted"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount_adjusted"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        oitem.card_no = reader["card_no"] == DBNull.Value ? "" : reader["card_no"].ToString();
                        oitem.card_typeid = reader["card_typeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["card_typeid"]);
                        oitem.bankid = reader["bankid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["bankid"]);
                        if (oitem.bankid == 0)
                            oitem.bankid = reader["upiproviderid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["upiproviderid"]);
                        if (chequerefid > 0 && oitem.bankid == chequerefid)
                        {
                            oitem.paid_cheque = oitem.paid_upi;
                            oitem.paid_upi = 0;
                        }
                        oitem.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        oitem.discountapprovedby = reader["discountapprovedby"] == DBNull.Value ? "" : reader["discountapprovedby"].ToString();
                        oitem.billno = "";
                        oitem.discountremark = reader["discount_info"] == DBNull.Value ? "" : reader["discount_info"].ToString();

                        if (oitem.paid_cash < 0 && oitem.return_cash > 0)
                            oitem.paid_cash = 0;
                        if (oitem.discount_adjusted > 0)
                            oitem.cashierdiscountpercent = Math.Round((oitem.discount_adjusted * 100) / oitem.receivable, 2);
                        if (oitem.discount > 0)
                            oitem.discountpercent = Math.Round((oitem.discount * 100) / oitem.receivable, 2);

                        if (system_custcreditnoteabove > 0
                            && (reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"])) > 0)
                        {
                            if (oitem.return_cash == 0 && oitem.paid_voucher > 0 && oitem.paid_cash == 0)
                                oitem.return_cash = reader["voucheradjustedcashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["voucheradjustedcashreturn"]);
                        }

                        lst.Add(oitem);
                    }
                }

                if (lst.Count > 0)
                {
                    if (string.IsNullOrEmpty(_reportcreteria.setno) && (_reportcreteria.cashierid == 0))
                    {
                        command = GetCommand(@"select billno,billsettlementmaster.id from billsettlementmaster
                                            inner join billsettlement on billsettlement.billsettlementmasterid = billsettlementmaster.id
                                            where billsettlementmaster.isactive=true and billsettlementmaster.settlementon >= @fromdate and billsettlementmaster.settlementon < @todate
                                            and case when @locationid = 0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
                                            and case when @counterid = 0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
                                            and case when @companyid = 0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end", conn);
                    }
                    else if (_reportcreteria.cashierid != 0)
                    {
                        command = GetCommand(@"select billno,billsettlementmaster.id from billsettlementmaster
                                            inner join billsettlement on billsettlement.billsettlementmasterid = billsettlementmaster.id
                                            where billsettlementmaster.isactive=true and billsettlementmaster.cashierid=@cashierid and billsettlementmaster.settlementon >= @fromdate and billsettlementmaster.settlementon < @todate
                                            and case when @locationid = 0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid = @locationid end
                                            and case when @counterid = 0 then billsettlementmaster.counterid <> 0 else billsettlementmaster.counterid = @counterid end
                                            and case when @companyid = 0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end", conn);
                    }
                    else
                    {
                        command = GetCommand(@"select billno,billsettlementmaster.id from billsettlementmaster
                                                inner join billsettlement on billsettlement.billsettlementmasterid = billsettlementmaster.id
                                                where billsettlementmaster.id in (" + string.Join(",", lst.ConvertAll(e => e.id)) + ")", conn);
                    }

                    command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                    command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                    command.Parameters.Add("cashierid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.cashierid;
                    command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                    command.Parameters.Add("setno", NpgsqlTypes.NpgsqlDbType.Varchar).Value = _reportcreteria.setno;
                    command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                    command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;

                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            long id = reader.GetInt64(1);
                            var oitem = lst.Find(e => e.id == id);
                            oitem.billno += (oitem.billno.Length > 0 ? "," : "") + reader.GetString(0);
                        }
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

