        public List<InwardReport> SearchInward(RetailReportCreteria _reportcreteria)
        {
            List<InwardReport> lst = new List<InwardReport>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                QueryBuilder qb = new QueryBuilder();

                if (_reportcreteria.showdetail)
                {
                    qb.CurrentQuery = SQL_InwardItems;
                    qb.AddParameter("bundles.code", _reportcreteria.packageno, "=");
                }
                else
                    qb.CurrentQuery = SQL_Inward;

                qb.AddParameter("returngoods", false, "=");
                qb.AddParameter("status", 1, "=");
                qb.AddParameter("bundles.isactive", true, "=");
                qb.AddParameter("tolocationid", _reportcreteria.locationid, "=");
                if (_reportcreteria.fromdate != DateTime.MinValue && _reportcreteria.todate != DateTime.MinValue)
                {
                    qb.AddParameter("receivedon", "receivedonfrom", _reportcreteria.fromdate.Date, ">=");
                    qb.AddParameter("receivedon", "receivedonto", _reportcreteria.todate.AddDays(1).Date, "<");
                }
                else
                    qb.AddParameter("receivedon", DateTimeNow.Date, "=");

                qb.SortField = "packedon desc";
                command = qb.GetCommand(conn);

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        InwardReport oitem = new InwardReport();
                        oitem.code = reader["code"] == DBNull.Value ? "" : reader["code"].ToString();
                        oitem.fromlocation = reader["fromlocation"] == DBNull.Value ? "" : reader["fromlocation"].ToString();
                        oitem.tolocation = reader["tolocation"] == DBNull.Value ? "" : reader["tolocation"].ToString();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.packedon = reader["packedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["packedon"]);
                        oitem.receivedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        oitem.receivedby = reader["receivedby"] == DBNull.Value ? "" : reader["receivedby"].ToString();

                        if (_reportcreteria.showdetail)
                            oitem.items_json = reader["items"] == DBNull.Value ? "null" : reader["items"].ToString();
                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

