        public List<RetailReport> SearchRewardConsumption(RetailReportCreteria _reportcreteria)
        {
            string _SQLSpend = @"Select bill.id, bill.isinterstatesale, customer.gstno, location.name as location, 
customer.name customername, customer.mobileno, customer.loyeltyno, billno, billdate, rounding,(receivable+rounding) receivable,
tax, discount, additionaldiscount, qty, bill.billtype,
cast(bill.billattributes->> 'spentreward' as numeric) spentreward
from bill inner join referencelist location on location.id = bill.locationid
inner join customer on customer.id = bill.customerid
where bill.isactive = true and bill.billtype!=9  
and cast(bill.billattributes->> 'spentreward' as numeric) > 0
and bill.billdate>=@fromdate and bill.billdate<@todate 
and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
order by bill.id ";

            string _SQLNew = @"Select bill.id, bill.isinterstatesale, customer.gstno, location.name as location, 
customer.name customername, customer.mobileno, customer.loyeltyno, billno, billdate, rounding,(receivable+rounding) receivable,
tax, discount, additionaldiscount, qty, bill.billtype,
cast(bill.billattributes->> 'earnedreward' as numeric) spentreward
from bill inner join referencelist location on location.id = bill.locationid
inner join customer on customer.id = bill.customerid
where bill.isactive = true and bill.billtype!=9 and settled=true  
and cast(bill.billattributes->> 'earnedreward' as numeric) > 0
and bill.billdate>=@fromdate and bill.billdate<@todate 
and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
order by bill.id ";

            List<RetailReport> lst = new List<RetailReport>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();
                NpgsqlCommand command = null;
                command = GetCommand(_reportcreteria.showdetail ? _SQLNew : _SQLSpend, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        RetailReport obill = new RetailReport();
                        obill.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                        obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                        obill.customer = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        obill.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                        obill.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                        obill.remarks = reader["loyeltyno"] == DBNull.Value ? "" : reader["loyeltyno"].ToString();
                        obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                        obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        obill.taxable = reader["spentreward"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["spentreward"]);

                        obill.taxable = Math.Round(obill.taxable, 2);
                        lst.Add(obill);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public List<SalesTaxHSNSummary> SearchSalesTaxHSNSummary(RetailReportCreteria _reportcreteria)
        {
            string SQL_SalesTaxSummaryModified = @"
                        with billtaxdetail as (
                        Select bill.companyid, bill.locationid, bill.isinterstatesale, customer.gstno, customer.name customername, bill.id billid,
                        state.code statecode, state.name statename, companystate.code companystatecode, companystate.name companystatename, bill.billno, 
                        bill.billdate::date,billitems.taxpercentage, billitems.hsncode,billitems.printingname,
                        sum(billitems.receivable) receivable,
                        sum(case when bill.isinterstatesale then 0 else billitems.tax end) tax,
                        sum(case when bill.isinterstatesale then billitems.tax else 0 end) itax,sum(rounding) rounding,
                        sum(billitems.qty) qty,sum(billitems.piece) piece
                        from bill 
                        inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        inner join company on company.id = bill.companyid
					    left outer join customer on customer.id = bill.customerid							
						left outer join referencelist state on state.id = customer.stateid
                        left outer join referencelist companystate on companystate.id = company.stateid
                        where bill.isactive = true and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                        and bill.counterid=@counterid and bill.isexport=false
                        {0}
                        group by bill.companyid, bill.locationid, bill.isinterstatesale, customer.gstno, customer.name, state.code, 
                        state.name, companystate.code, companystate.name, bill.billno, bill.billdate::date,taxpercentage,bill.id,
                        billitems.hsncode,billitems.printingname
                        order by billdate,taxpercentage
                        ),
                        additionalcharge as (
                        Select bill.companyid, bill.id billid, bill.locationid, bill.billdate::date,Billadditionalcharges.taxpercentage,
                        referencelist.name printingname,additionalinfo->>'formula' hsncode,
                        sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 
                        sum(case when bill.isinterstatesale then 0 else Billadditionalcharges.tax end) tax,
                        sum(case when bill.isinterstatesale then Billadditionalcharges.tax else 0 end) itax,	
                        sum(Billadditionalcharges.amount - (Billadditionalcharges.charge+Billadditionalcharges.tax)) rounding,
                        1 qty,1 piece
                        from bill 
                        inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                        inner join referencelist on referencelist.id = additionalchargestypeid
                        where bill.isactive = true and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                        and bill.counterid=@counterid 
                        {0}
                        and Billadditionalcharges.taxpercentage>0 	and Billadditionalcharges.tax != 0
                        group by bill.companyid, bill.locationid,bill.id, bill.billdate::date,taxpercentage,
                        referencelist.name,additionalinfo->>'formula'
                        order by taxpercentage
                        ),uniquebill as
						(
							select distinct billtaxdetail.billid, billtaxdetail.isinterstatesale, billtaxdetail.gstno, 
                        billtaxdetail.customername, billtaxdetail.statecode, billtaxdetail.statename,billtaxdetail.companyid,
						billtaxdetail.companystatecode,billtaxdetail.locationid,
						billtaxdetail.companystatename, billtaxdetail.billno,
                        billtaxdetail.billdate 
                        from billtaxdetail 
						)
                        select billtaxdetail.companyid, billtaxdetail.locationid, billtaxdetail.isinterstatesale, billtaxdetail.gstno, 
	                    billtaxdetail.customername, billtaxdetail.statecode, billtaxdetail.statename, billtaxdetail.companystatecode, 
                        billtaxdetail.companystatename, billtaxdetail.billno,
	                    billtaxdetail.billdate, billtaxdetail.taxpercentage, billtaxdetail.hsncode,billtaxdetail.printingname,
	                    billtaxdetail.receivable , 
	                    billtaxdetail.tax , 
	                    billtaxdetail.itax , 
	                    billtaxdetail.rounding,billtaxdetail.qty,billtaxdetail.piece 
	                    from billtaxdetail 
						union all 
						select billtaxdetail.companyid, billtaxdetail.locationid, billtaxdetail.isinterstatesale, billtaxdetail.gstno, 
	                    billtaxdetail.customername, billtaxdetail.statecode, billtaxdetail.statename, billtaxdetail.companystatecode, 
						billtaxdetail.companystatename, billtaxdetail.billno,
	                    billtaxdetail.billdate, additionalcharge.taxpercentage, additionalcharge.hsncode,additionalcharge.printingname,
	                    case when additionalcharge.receivable is null then 0 else additionalcharge.receivable end receivable, 
	                    case when additionalcharge.tax is null then 0 else additionalcharge.tax end tax, 
	                    case when additionalcharge.itax is null then 0 else additionalcharge.itax end itax, 
	                    case when additionalcharge.rounding is null then 0 else additionalcharge.rounding end rounding,
                        additionalcharge.qty,additionalcharge.piece
	                    from uniquebill billtaxdetail
	                    inner join additionalcharge on additionalcharge.billid = billtaxdetail.billid";

            List<SalesTaxHSNSummary> lst = new List<SalesTaxHSNSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();


                string query = string.Format(SQL_SalesTaxSummaryModified, "");
                switch (_reportcreteria.mode)
                {
                    case "credit":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and bill.billtype=1 ");
                        break;
                    case "interstate":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 and bill.isinterstatesale=true ");
                        break;
                    case "local":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 and bill.isinterstatesale=false ");
                        break;
                    case "return":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 and isreturn=true ");
                        break;
                    case "cash":
                        query = string.Format(SQL_SalesTaxSummaryModified + " inner join cashsettlement on cashsettlement.billid = billtaxdetail.billid ", " and billtype!=9 ");
                        break;
                    default:
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 ");
                        break;
                }
                if (_reportcreteria.includeb2b)
                    query = query.Replace("and bill.isb2b=@isb2b", "");
                if (_reportcreteria.counterid <= 0)
                    query = query.Replace("and bill.counterid=@counterid ", "");


                NpgsqlCommand command = null;
                command = GetCommand(query, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxHSNSummary item = new SalesTaxHSNSummary();
                        item.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        item.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        item.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        item.taxamount = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.igst = reader["itax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["itax"]);
                        item.amount = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - (item.taxamount + item.igst);
                        if (item.amount == 0) continue;

                        item.printingname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                        item.hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();

                        item.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        item.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                        item.customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        item.gstno = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                        item.placeofsupply = reader["statecode"] == DBNull.Value ? "" : reader["statecode"].ToString();
                        item.area = reader["statename"] == DBNull.Value ? "" : reader["statename"].ToString();
                        if (!item.isinterstatesale && string.IsNullOrEmpty(item.gstno))
                        {
                            item.placeofsupply = reader["companystatecode"] == DBNull.Value ? "" : reader["companystatecode"].ToString();
                            item.area = reader["companystatename"] == DBNull.Value ? "" : reader["companystatename"].ToString();
                            item.placeofsupply = item.placeofsupply + "-" + item.area;
                        }
                        else if (string.IsNullOrEmpty(item.area))
                        {
                            item.placeofsupply = reader["companystatecode"] == DBNull.Value ? "" : reader["companystatecode"].ToString();
                            item.area = reader["companystatename"] == DBNull.Value ? "" : reader["companystatename"].ToString();
                            //item.placeofsupply = "33-Tamil Nadu";
                            item.placeofsupply = item.placeofsupply + "-" + item.area;
                        }
                        else
                            item.placeofsupply = item.placeofsupply + "-" + item.area;

                        //if (!_reportcreteria.showsalesummary)
                        {
                            item.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        }

                        item.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        item.cgst = item.taxamount != 0 ? Math.Round((item.taxamount / 2), 2) : 0;
                        item.sgst = item.taxamount != 0 ? Math.Round((item.taxamount / 2), 2) : 0;
                        item.taxamount += item.igst;
                        item.total = Math.Round(item.amount + item.taxamount, 0);
                        lst.Add(item);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public List<SalesTaxSummary> SearchSalesTaxSummary(RetailReportCreteria _reportcreteria)
        {
            string SQL_SalesTaxSummaryModified = @"
                        with billtaxdetail as (
                        Select bill.companyid, bill.locationid, bill.isinterstatesale, customer.gstno, customer.name customername, bill.id billid,
                        state.code statecode, state.name statename, companystate.code companystatecode, companystate.name companystatename, bill.billno, bill.billdate::date,billitems.taxpercentage, 
                        sum(billitems.receivable) receivable, 
                        sum(case when bill.isinterstatesale then 0 else billitems.tax end) tax,
                        sum(case when bill.isinterstatesale then billitems.tax else 0 end) itax,sum(rounding) rounding
                        from bill 
                        inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        inner join company on company.id = bill.companyid
					    left outer join customer on customer.id = bill.customerid							
						left outer join referencelist state on state.id = customer.stateid
                        left outer join referencelist companystate on companystate.id = company.stateid
                        where bill.isactive = true and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                        and bill.counterid=@counterid 
                        {0}
                        group by bill.companyid, bill.locationid, bill.isinterstatesale, customer.gstno, customer.name, state.code, 
                        state.name, companystate.code, companystate.name, bill.billno, bill.billdate::date,taxpercentage,bill.id
                        order by billdate,taxpercentage
                        ),
                        additionalcharge as (
                        Select bill.companyid, bill.id billid, bill.locationid, bill.billdate::date,Billadditionalcharges.taxpercentage,
                        sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 
                        sum(case when bill.isinterstatesale then 0 else Billadditionalcharges.tax end) tax,
                        sum(case when bill.isinterstatesale then Billadditionalcharges.tax else 0 end) itax,	
                        sum(Billadditionalcharges.amount - (Billadditionalcharges.charge+Billadditionalcharges.tax)) rounding
                        from bill inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                        where bill.isactive = true and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                        and bill.counterid=@counterid 
                        {0}
                        --and Billadditionalcharges.taxpercentage>0 	and Billadditionalcharges.tax != 0
                        group by bill.companyid, bill.locationid,bill.id, bill.billdate::date,taxpercentage
                        order by taxpercentage
                        ),cashsettlement as
                        (
                            select billid from billsettlementmaster 
                            inner join billsettlement on billsettlement.billsettlementmasterid = billsettlementmaster.id
                            where billsettlementmaster.isactive=true and billsettlement.isactive=true
                            and paid_cash>0 and paid_upi=0 and paid_voucher=0 and paid_card=0 and paid_credit=0
                            and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate 
                        )
                        select billtaxdetail.companyid, billtaxdetail.locationid, billtaxdetail.isinterstatesale, billtaxdetail.gstno, 
                        billtaxdetail.customername, billtaxdetail.statecode, billtaxdetail.statename, billtaxdetail.companystatecode, billtaxdetail.companystatename, billtaxdetail.billno,
                        billtaxdetail.billdate, billtaxdetail.taxpercentage, 
                        billtaxdetail.receivable + case when additionalcharge.receivable is null then 0 else additionalcharge.receivable end receivable, 
                        billtaxdetail.tax + case when additionalcharge.tax is null then 0 else additionalcharge.tax end tax, 
                        billtaxdetail.itax + case when additionalcharge.itax is null then 0 else additionalcharge.itax end itax, 
                        billtaxdetail.rounding + case when additionalcharge.rounding is null then 0 else additionalcharge.rounding end rounding
                        from billtaxdetail 
                        left outer join additionalcharge on additionalcharge.billid = billtaxdetail.billid 
                        and additionalcharge.taxpercentage = billtaxdetail.taxpercentage ";

            List<SalesTaxSummary> lst = new List<SalesTaxSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();


                string query = string.Format(SQL_SalesTaxSummaryModified, "");
                switch (_reportcreteria.mode)
                {
                    case "credit":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and bill.billtype=1 ");
                        break;
                    case "interstate":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 and bill.isinterstatesale=true ");
                        break;
                    case "local":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 and bill.isinterstatesale=false ");
                        break;
                    case "return":
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 and isreturn=true ");
                        break;
                    case "cash":
                        query = string.Format(SQL_SalesTaxSummaryModified + " inner join cashsettlement on cashsettlement.billid = billtaxdetail.billid ", " and billtype!=9 ");
                        break;
                    default:
                        query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 ");
                        break;
                }
                if (_reportcreteria.includeb2b)
                    query = query.Replace("and bill.isb2b=@isb2b", "");
                if (_reportcreteria.counterid <= 0)
                    query = query.Replace("and bill.counterid=@counterid ", "");

                if (_reportcreteria.showmarker)
                {
                    query = query.Replace("bill.isinterstatesale, customer.gstno, customer.name customername,", "");
                    query = query.Replace("state.code statecode, state.name statename, companystate.code companystatecode, companystate.name companystatename, bill.billno,", "");
                    //query = query.Replace("billitems.taxpercentage,", "");
                    //query = query.Replace("Billadditionalcharges.taxpercentage,", "");
                    //query = query.Replace("billtaxdetail.taxpercentage,", "");
                    query = query.Replace("bill.isinterstatesale, customer.gstno, customer.name, state.code, state.name, bill.billno,", "");
                    //query = query.Replace(",taxpercentage", "");
                    query = query.Replace("billtaxdetail.isinterstatesale, billtaxdetail.gstno,", "");
                    query = query.Replace("billtaxdetail.customername, billtaxdetail.statecode, billtaxdetail.statename, billtaxdetail.companystatecode, billtaxdetail.companystatename, billtaxdetail.billno,", "");
                    //query = query.Replace("order by taxpercentage", "");
                    //query = query.Replace("and additionalcharge.taxpercentage = billtaxdetail.taxpercentage", "");
                }
                else if (_reportcreteria.showsalesummary)
                {
                    query = query.Replace("bill.isinterstatesale, customer.gstno, customer.name customername,", "");
                    query = query.Replace("state.code statecode, state.name statename, companystate.code companystatecode, companystate.name companystatename, bill.billno,", "");
                    //query = query.Replace("billitems.taxpercentage,", "");
                    //query = query.Replace("Billadditionalcharges.taxpercentage,", "");
                    //query = query.Replace("billtaxdetail.taxpercentage,", "");
                    query = query.Replace("bill.isinterstatesale, customer.gstno, customer.name, state.code, state.name, companystate.code, companystate.name, bill.billno,", "");
                    //query = query.Replace(",taxpercentage", "");
                    query = query.Replace("billtaxdetail.isinterstatesale, billtaxdetail.gstno,", "");
                    query = query.Replace("billtaxdetail.customername, billtaxdetail.statecode, billtaxdetail.statename, billtaxdetail.companystatecode, billtaxdetail.companystatename, billtaxdetail.billno,", "");
                    //query = query.Replace("order by taxpercentage", "");
                    query = query.Replace("and additionalcharge.taxpercentage = billtaxdetail.taxpercentage", "");
                }
                NpgsqlCommand command = null;
                command = GetCommand(query, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxSummary item = new SalesTaxSummary();
                        item.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        item.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        item.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        item.taxamount = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.igst = reader["itax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["itax"]);
                        item.amount = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - (item.taxamount + item.igst);
                        if (item.amount == 0) continue;

                        if (!_reportcreteria.showsalesummary && !_reportcreteria.showmarker)
                        {
                            item.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            item.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                            item.customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            item.gstno = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                            item.placeofsupply = reader["statecode"] == DBNull.Value ? "" : reader["statecode"].ToString();
                            item.area = reader["statename"] == DBNull.Value ? "" : reader["statename"].ToString();
                            if (!item.isinterstatesale && string.IsNullOrEmpty(item.gstno))
                            {
                                item.placeofsupply = reader["companystatecode"] == DBNull.Value ? "" : reader["companystatecode"].ToString();
                                item.area = reader["companystatename"] == DBNull.Value ? "" : reader["companystatename"].ToString();
                                item.placeofsupply = item.placeofsupply + "-" + item.area;
                            }
                            else if (string.IsNullOrEmpty(item.area))
                            {
                                item.placeofsupply = reader["companystatecode"] == DBNull.Value ? "" : reader["companystatecode"].ToString();
                                item.area = reader["companystatename"] == DBNull.Value ? "" : reader["companystatename"].ToString();
                                //item.placeofsupply = "33-Tamil Nadu";
                                item.placeofsupply = item.placeofsupply + "-" + item.area;
                            }
                            else
                                item.placeofsupply = item.placeofsupply + "-" + item.area;
                        }
                        //if (!_reportcreteria.showsalesummary)
                        {
                            item.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        }
                        item.cgst = item.taxamount != 0 ? Math.Round((item.taxamount / 2), 2) : 0;
                        item.sgst = item.taxamount != 0 ? Math.Round((item.taxamount / 2), 2) : 0;
                        item.taxamount += item.igst;
                        item.total = Math.Round(item.amount + item.taxamount, 0);
                        lst.Add(item);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public List<SalesTaxSummary> SearchInvoicewiseSales(RetailReportCreteria _reportcreteria)
        {
            List<SalesTaxSummary> lst = new List<SalesTaxSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();
                string query = string.Format(SQL_InvoicewiseSales, "");
                switch (_reportcreteria.mode)
                {
                    case "credit":
                        query = string.Format(SQL_InvoicewiseSales, " and bill.billtype=1");
                        break;
                    case "interstate":
                        query = string.Format(SQL_InvoicewiseSales, " and bill.isinterstatesale=true ");
                        break;
                    case "local":
                        query = string.Format(SQL_InvoicewiseSales, " and bill.isinterstatesale=false ");
                        break;

                }
                NpgsqlCommand command = null;
                command = GetCommand(GetSQL4B2B("", query), conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxSummary item = new SalesTaxSummary();
                        item.billno = reader["billno"] == DBNull.Value ? "" : Convert.ToString(reader["billno"]);
                        item.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        item.customername = reader["printingname"] == DBNull.Value ? "" : Convert.ToString(reader["printingname"]);
                        item.mobileno = reader["hsncode"] == DBNull.Value ? "" : Convert.ToString(reader["hsncode"]);
                        item.area = reader["materialname"] == DBNull.Value ? "" : Convert.ToString(reader["materialname"]);

                        item.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        item.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        // Taxable
                        item.amount = reader["taxableamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxableamount"]);
                        item.taxamount = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.igst = reader["itax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["itax"]);
                        item.cgst = item.taxamount != 0 ? Math.Round((item.taxamount / 2), 2) : 0;
                        item.sgst = item.taxamount != 0 ? Math.Round((item.taxamount / 2), 2) : 0;
                        item.taxamount += item.igst;
                        item.total = reader["salevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salevalue"]);

                        if (item.amount < 0 && item.qty < 0)
                            item.rate = Math.Round((item.amount * -1) / (item.qty * -1), 2);
                        else if (item.amount > 0 && item.qty > 0)
                            item.rate = Math.Round(item.amount / item.qty, 2);

                        lst.Add(item);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

