        public SalesTaxReport SearchSalesTax(RetailReportCreteria _reportcreteria)
        {
            if (_reportcreteria.showdetail)
                return SearchSalesTaxWithBillNo(_reportcreteria);

            string SQL_SalesTaxModified = @"with billtaxdetail as (
                        Select bill.billdate::date,billitems.taxpercentage, sum(billitems.receivable) receivable, sum(billitems.tax) tax,sum(rounding) rounding
                        from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                        group by bill.billdate::date,taxpercentage
                        order by taxpercentage
                        ),
                        additionalcharge as (
                        Select bill.billdate::date,Billadditionalcharges.taxpercentage,
                        sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 
                        sum(Billadditionalcharges.tax) tax,
                        sum(Billadditionalcharges.amount - (Billadditionalcharges.charge+Billadditionalcharges.tax)) rounding
                        from bill inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                        where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                        and Billadditionalcharges.taxpercentage>0 and Billadditionalcharges.tax != 0
                        group by bill.billdate::date,taxpercentage
                        order by taxpercentage
                        )
                        select billtaxdetail.billdate, billtaxdetail.taxpercentage, 
                        billtaxdetail.receivable + case when additionalcharge.receivable is null then 0 else additionalcharge.receivable end receivable, 
                        billtaxdetail.tax + case when additionalcharge.tax is null then 0 else additionalcharge.tax end tax, 
                        billtaxdetail.rounding + case when additionalcharge.rounding is null then 0 else additionalcharge.rounding end rounding
                        from billtaxdetail left outer join additionalcharge on additionalcharge.billdate = billtaxdetail.billdate 
                        and additionalcharge.taxpercentage = billtaxdetail.taxpercentage ";

            SalesTaxReport salestaxreport = new SalesTaxReport();
            salestaxreport.taxbreakup = new List<SalesTaxReport.SaleSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                if (_reportcreteria.includeb2b)
                    SQL_SalesTaxModified = SQL_SalesTaxModified.Replace("and bill.isb2b=@isb2b", "");

                command = GetCommand(SQL_SalesTaxModified, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxReport.SaleSummary oitem = new SalesTaxReport.SaleSummary();
                        DateTime billDate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        if (salestaxreport.taxbreakup.Exists(e => e.billdate == billDate))
                            oitem = salestaxreport.taxbreakup.Find(e => e.billdate == billDate);
                        else
                        {
                            oitem.billdate = billDate;
                            oitem.items = new List<SalesTaxReport.SaleValue>();
                            salestaxreport.taxbreakup.Add(oitem);
                        }

                        SalesTaxReport.SaleValue item = new SalesTaxReport.SaleValue();
                        item.taxvalue = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.salevalue = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - item.taxvalue;
                        item.taxpercent = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        oitem.totalvalue += (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]));
                        item.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);

                        oitem.items.Add(item);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }

            salestaxreport.taxList = new List<SalesTaxReport.SaleValueSummary>();
            foreach (var item in salestaxreport.taxbreakup)
            {
                var salvalue = item.items.Sum(e => e.salevalue);
                var taxvalue = item.items.Sum(e => e.taxvalue);
                var rounding = item.items.Sum(e => e.rounding);

                item.items.Add(new SalesTaxReport.SaleValue()
                {
                    taxpercent = -1,
                    salevalue = salvalue,
                    taxvalue = taxvalue,
                    rounding = rounding
                });

                foreach (var titem in item.items.GroupBy(e => e.taxpercent))
                {
                    if (salestaxreport.taxList.Exists(e => e.taxpercent == titem.Key))
                    {
                        var tlitem = salestaxreport.taxList.Find(e => e.taxpercent == titem.Key && e.type == "VALUE");
                        tlitem.taxvalue += titem.Sum(e => e.taxvalue);
                        tlitem.salevalue += titem.Sum(e => e.salevalue);
                        tlitem = salestaxreport.taxList.Find(e => e.taxpercent == titem.Key && e.type == "TAX");
                        tlitem.taxvalue += titem.Sum(e => e.taxvalue);
                        tlitem.salevalue += titem.Sum(e => e.salevalue);
                        tlitem.rounding += titem.Sum(e => e.rounding);

                    }
                    else
                    {
                        salestaxreport.taxList.Add(new SalesTaxReport.SaleValueSummary()
                        {
                            title = (titem.Key == -1 ? "Total Value" : string.Format("{0}% Value", titem.Key)),
                            type = "VALUE",
                            taxpercent = titem.Key,
                            salevalue = titem.Sum(e => e.salevalue),
                            taxvalue = titem.Sum(e => e.taxvalue),
                            rounding = titem.Sum(e => e.rounding)

                        });
                        salestaxreport.taxList.Add(new SalesTaxReport.SaleValueSummary()
                        {
                            title = (titem.Key == -1 ? "Total Tax" : string.Format("{0}% Tax", titem.Key)),
                            type = "TAX",
                            taxpercent = titem.Key,
                            salevalue = titem.Sum(e => e.salevalue),
                            taxvalue = titem.Sum(e => e.taxvalue),
                            rounding = titem.Sum(e => e.rounding)
                        });
                        //salestaxreport.taxList.Add(new SalesTaxReport.SaleValueSummary()
                        //{
                        //    title = (titem.Key == -1 ? "Rounding" : string.Format("{0}% Value", titem.Key)),
                        //    type = "VALUE",
                        //    taxpercent = titem.Key,
                        //    salevalue = titem.Sum(e => e.salevalue),
                        //    taxvalue = titem.Sum(e => e.taxvalue),
                        //    rounding = titem.Sum(e => e.rounding)

                        //});
                    }
                }
            }

            if (salestaxreport != null && salestaxreport.taxList.Count > 0)
            {
                var summary = salestaxreport.taxList.FindAll(e => e.taxpercent == -1);
                salestaxreport.taxList = salestaxreport.taxList.OrderBy(e => e.taxpercent).ToList();
                salestaxreport.taxList.RemoveAll(e => e.taxpercent == -1);
                salestaxreport.taxList.AddRange(summary);
                salestaxreport.taxbreakup = salestaxreport.taxbreakup.OrderBy(e => e.billdate).ToList();

                salestaxreport.taxablevalue = (summary != null && summary.Count > 1 ? summary[0].salevalue : 0);
                salestaxreport.taxvalue = (summary != null && summary.Count > 1 ? summary[0].taxvalue : 0);
                salestaxreport.totalvalue = salestaxreport.taxablevalue + salestaxreport.taxvalue;
            }
            foreach (var item in salestaxreport.taxbreakup)
            {
                List<RetailReport> lst = SearchSales(new SaleRetailCreteria() { mode = "1", fromdate = item.billdate, todate = item.billdate, companyid = _reportcreteria.companyid, locationid = _reportcreteria.locationid, isb2b = _reportcreteria.isb2b });
                if (lst.Count > 0) item.rounding = lst[0].rounding;
                item.totalvalue = Math.Round(item.totalvalue + item.rounding, 2);
            }
            return salestaxreport;
        }

        public SalesTaxReport SearchSalesTaxWithBillNo(RetailReportCreteria _reportcreteria)
        {
            string SQL_SalesTaxWithBillNoModified = @"
                            with billtaxdetail as (
                            Select bill.billdate::date,bill.billno,billitems.taxpercentage, sum(billitems.receivable) receivable, 
                            sum(billitems.tax) tax,sum(rounding) rounding,bill.isinterstatesale,
							customer.gstno,referencelist.code statecode,company.tinanddate cgstno
                            from bill 
                            inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                            inner join company on company.id = bill.companyid
                            left outer join customer on customer.id = bill.customerid
							left outer join referencelist on referencelist.id = customer.stateid
                            where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                            and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                            and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                            group by bill.billdate::date,bill.billno,taxpercentage,bill.isinterstatesale,customer.gstno,referencelist.code,company.tinanddate
                            order by bill.billdate::date,bill.billno,taxpercentage
                            ),
                            additionalcharge as (
                            Select bill.billdate::date,bill.billno,Billadditionalcharges.taxpercentage,
                            sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 
                            sum(Billadditionalcharges.tax) tax,
                            sum(Billadditionalcharges.amount - (Billadditionalcharges.charge+Billadditionalcharges.tax)) rounding
                            from bill inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                            where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                            and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                            and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end
                            and Billadditionalcharges.taxpercentage>0 and Billadditionalcharges.tax != 0	
                            group by bill.billdate::date,bill.billno,taxpercentage
                            order by bill.billdate::date,bill.billno,taxpercentage
                            )
                            select billtaxdetail.billdate, billtaxdetail.billno,billtaxdetail.taxpercentage,isinterstatesale,gstno,statecode,cgstno,
                            billtaxdetail.receivable + case when additionalcharge.receivable is null then 0 else additionalcharge.receivable end receivable, 
                            billtaxdetail.tax + case when additionalcharge.tax is null then 0 else additionalcharge.tax end tax, 
                            billtaxdetail.rounding + case when additionalcharge.rounding is null then 0 else additionalcharge.rounding end rounding
                            from billtaxdetail 
                            left outer join additionalcharge on additionalcharge.billno = billtaxdetail.billno 
                            and additionalcharge.taxpercentage = billtaxdetail.taxpercentage ";

            SalesTaxReport salestaxreport = new SalesTaxReport();
            salestaxreport.taxbreakup = new List<SalesTaxReport.SaleSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                if (_reportcreteria.includeb2b)
                    SQL_SalesTaxWithBillNoModified = SQL_SalesTaxWithBillNoModified.Replace("and bill.isb2b=@isb2b", "");

                command = GetCommand(SQL_SalesTaxWithBillNoModified, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxReport.SaleSummary oitem = new SalesTaxReport.SaleSummary();
                        DateTime billDate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        string billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();

                        if (salestaxreport.taxbreakup.Exists(e => e.billdate == billDate && e.billno == billno))
                        {
                            oitem = salestaxreport.taxbreakup.Find(e => e.billdate == billDate && e.billno == billno);
                        }
                        else
                        {
                            oitem.billdate = billDate;
                            oitem.billno = billno;
                            oitem.isinterstate = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                            oitem.gstno = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                            oitem.statecode = reader["statecode"] == DBNull.Value ? "" : reader["statecode"].ToString();
                            var cgstno = reader["cgstno"] == DBNull.Value ? "" : reader["cgstno"].ToString();
                            if (!string.IsNullOrEmpty(cgstno) &&
                                cgstno.Length > 2)
                                cgstno = cgstno.Substring(0, 2);

                            if (!string.IsNullOrEmpty(oitem.gstno) &&
                                !string.IsNullOrEmpty(oitem.statecode) &&
                                oitem.statecode.Length > 2)
                            {
                                oitem.statecode = oitem.statecode.Substring(0, 2);
                            }
                            else if (string.IsNullOrEmpty(oitem.statecode) &&
                                !string.IsNullOrEmpty(cgstno))
                            {
                                oitem.statecode = cgstno;
                            }
                            oitem.items = new List<SalesTaxReport.SaleValue>();
                            salestaxreport.taxbreakup.Add(oitem);
                        }

                        SalesTaxReport.SaleValue item = new SalesTaxReport.SaleValue();
                        item.taxvalue = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.salevalue = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - item.taxvalue;
                        item.taxpercent = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        oitem.totalvalue += (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]));
                        item.rounding = reader["rounding"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rounding"]);

                        oitem.items.Add(item);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }

            salestaxreport.taxList = new List<SalesTaxReport.SaleValueSummary>();
            foreach (var item in salestaxreport.taxbreakup)
            {
                var salvalue = item.items.Sum(e => e.salevalue);
                var taxvalue = item.items.Sum(e => e.taxvalue);
                var rounding = item.items.Sum(e => e.rounding);

                item.items.Add(new SalesTaxReport.SaleValue()
                {
                    taxpercent = -1,
                    salevalue = salvalue,
                    taxvalue = taxvalue,
                    rounding = rounding
                });

                foreach (var titem in item.items.GroupBy(e => e.taxpercent))
                {
                    if (salestaxreport.taxList.Exists(e => e.taxpercent == titem.Key))
                    {
                        var tlitem = salestaxreport.taxList.Find(e => e.taxpercent == titem.Key && e.type == "VALUE");
                        tlitem.taxvalue += titem.Sum(e => e.taxvalue);
                        tlitem.salevalue += titem.Sum(e => e.salevalue);
                        tlitem = salestaxreport.taxList.Find(e => e.taxpercent == titem.Key && e.type == "TAX");
                        tlitem.taxvalue += titem.Sum(e => e.taxvalue);
                        tlitem.salevalue += titem.Sum(e => e.salevalue);
                        tlitem.rounding += titem.Sum(e => e.rounding);

                    }
                    else
                    {
                        salestaxreport.taxList.Add(new SalesTaxReport.SaleValueSummary()
                        {
                            title = (titem.Key == -1 ? "Total Value" : string.Format("{0}% Value", titem.Key)),
                            type = "VALUE",
                            taxpercent = titem.Key,
                            salevalue = titem.Sum(e => e.salevalue),
                            taxvalue = titem.Sum(e => e.taxvalue),
                            rounding = titem.Sum(e => e.rounding)

                        });
                        salestaxreport.taxList.Add(new SalesTaxReport.SaleValueSummary()
                        {
                            title = (titem.Key == -1 ? "Total Tax" : string.Format("{0}% Tax", titem.Key)),
                            type = "TAX",
                            taxpercent = titem.Key,
                            salevalue = titem.Sum(e => e.salevalue),
                            taxvalue = titem.Sum(e => e.taxvalue),
                            rounding = titem.Sum(e => e.rounding)
                        });
                    }
                }
            }

            if (salestaxreport != null && salestaxreport.taxList.Count > 0)
            {
                var summary = salestaxreport.taxList.FindAll(e => e.taxpercent == -1);
                salestaxreport.taxList = salestaxreport.taxList.OrderBy(e => e.taxpercent).ToList();
                salestaxreport.taxList.RemoveAll(e => e.taxpercent == -1);
                salestaxreport.taxList.AddRange(summary);
                salestaxreport.taxbreakup = salestaxreport.taxbreakup.OrderBy(e => e.billdate).ToList();

                salestaxreport.taxablevalue = (summary != null && summary.Count > 1 ? summary[0].salevalue : 0);
                salestaxreport.taxvalue = (summary != null && summary.Count > 1 ? summary[0].taxvalue : 0);
                salestaxreport.totalvalue = salestaxreport.taxablevalue + salestaxreport.taxvalue;
            }
            return salestaxreport;
        }

        public List<CreditHistory> SearchCreditHistory(RetailReportCreteria retailReport)
        {
            string query = @"select customer.name as customername, customer.mobileno,bill.billno, customerinvoice.receivable credit,advance
from customerinvoice
inner join customer on customer.id = customerinvoice.customerid
left outer join bill on bill.id = customerinvoice.billid
where customerinvoice.isactive = true
and transactiondate>=@fromdate And transactiondate<@todate and (bill.id is null or bill.locationid = @locationid);

select customer.name as customername, customer.mobileno,amount from customerpayment
inner join customer on customer.id = customerpayment.customerid
where paidon>=@fromdate And paidon<@todate and locationid = @locationid";

            List<CreditHistory> lst = new List<CreditHistory>();
            DateTime fromdate = retailReport.fromdate;
            DateTime todate = retailReport.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = GetCommand(query, conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = fromdate;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = todate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = retailReport.locationid;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        CreditHistory oitem = new CreditHistory();
                        oitem.name = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        oitem.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                        oitem.credit = reader["credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["credit"]);
                        oitem.paid = reader["advance"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["advance"]);
                        lst.Add(oitem);
                    }

                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            CreditHistory oitem = new CreditHistory();
                            oitem.name = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            oitem.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                            oitem.ispayment = true;
                            oitem.paid = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                            lst.Add(oitem);
                        }
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, retailReport);
            }
            return lst;
        }
        public List<CustomerPayReport> SearchCustomerPayment(RetailReportCreteria _reportcreteria)
        {
            string SQL_Customerpaymentsummary = @"select customer.name as customername, customer.gstno, customer.area, 
    customer.mobileno, sum(customerinvoice.receivable) credit,referencelist.name cityname,
    sum(customerinvoice.paid) paid,sum(customerinvoice.discount) discount
    from customerinvoice
    inner join customer on customer.id = customerinvoice.customerid
    left outer join bill on bill.id = customerinvoice.billid
    left outer join company on company.id = bill.companyid
    left outer join referencelist on referencelist.id = customer.cityid
    where customerinvoice.isactive = true and customerinvoice.type in (1,2)
    and transactiondate>=@fromdate And transactiondate<@todate 
    {0}
    {1}
    ";

            //  and case when @customerid = 0 then customerinvoice.customerid != 0 else customerinvoice.customerid = @customerid end
            //  and case when @companyid = 0 then(bill.companyid != 0 or bill.companyid is null) else bill.companyid = @companyid end
            //  and case when @locationid = 0 then(bill.locationid != 0 or bill.locationid is null) else bill.locationid = @locationid end
            //group by customer.name, customer.gstno, area, customer.mobileno,referencelist.name
            //order by customer.name

            string SQL_Customerpayment = @"select customer.name as customername, customer.gstno, area, 
    customer.mobileno, customerinvoice.receivable credit, referencelist.name cityname,
    customerinvoice.paid,customerinvoice.discount,customerinvoice.id,bill.createdby,
    customerinvoice.billno, customerinvoice.transactiondate,company.name companyname,bill.locationid
    from customerinvoice 
    inner join customer on customer.id = customerinvoice.customerid
    left outer join bill on bill.id = customerinvoice.billid
    left outer join company on company.id = bill.companyid
    left outer join referencelist on referencelist.id = customer.cityid
    where customerinvoice.isactive = true and customerinvoice.type in (1,2)
    and transactiondate>=@fromdate And transactiondate<@todate 
    {0}
    {1}
    ";

            //and case when @customerid = 0 then customerinvoice.customerid != 0 else customerinvoice.customerid = @customerid end
            //  and case when @companyid = 0 then(bill.companyid != 0 or bill.companyid is null) else bill.companyid = @companyid end
            //   and case when @locationid = 0 then(bill.locationid != 0 or bill.locationid is null) else bill.locationid = @locationid end
            // order by customer.name, customerinvoice.transactiondate

            List<CustomerPayReport> lst = new List<CustomerPayReport>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;

            if (_reportcreteria.fromdate.Date == DateTime.MinValue) today = new DateTime(2000, 01, 01);
            if (_reportcreteria.todate.Date == DateTime.MinValue) nextdate = DateTimeNow.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            QueryBuilder qb = new QueryBuilder();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                if (!string.IsNullOrEmpty(_reportcreteria.packageno))
                {
                    CustomerDataService customerdata = new CustomerDataService() { Context = this.Context };
                    List<Customer> lstcustomer = customerdata.Search(new CustomerCreteria() { mobileno = _reportcreteria.packageno });
                    if (lstcustomer.Count > 0)
                        _reportcreteria.customerid = lstcustomer[0].id;
                    else
                        _reportcreteria.customerid = -1;
                }

                if (_reportcreteria.showdetail)
                {
                    if (_reportcreteria.showsalesummary)
                        SQL_Customerpayment = string.Format(SQL_Customerpayment, " and (customerinvoice.receivable - (customerinvoice.paid+customerinvoice.discount)) != 0 ", "");
                    else
                        SQL_Customerpayment = string.Format(SQL_Customerpayment, " ", " and customerinvoice.transactiondate>=@fromdate and customerinvoice.transactiondate<@todate ");

                    qb.CurrentQuery = SQL_Customerpayment;
                    if (_reportcreteria.customerid > 0)
                        qb.AddParameter("customerinvoice.customerid", _reportcreteria.customerid, "=");
                    if (_reportcreteria.companyid > 0)
                        qb.AddParameter("customerinvoice.companyid", _reportcreteria.companyid, "=");
                    if (_reportcreteria.locationid > 0)
                        qb.AddParameter("bill.locationid", _reportcreteria.locationid, "=");
                    qb.SortField = "customer.name, customerinvoice.transactiondate";

                    command = qb.GetCommand(conn);

                }
                else
                {
                    if (_reportcreteria.showsalesummary)
                        SQL_Customerpaymentsummary = string.Format(SQL_Customerpaymentsummary, " and (customerinvoice.receivable - (customerinvoice.paid+customerinvoice.discount)) != 0 ", " ");
                    else
                        SQL_Customerpaymentsummary = string.Format(SQL_Customerpaymentsummary, " ", " and customerinvoice.transactiondate>=@fromdate and customerinvoice.transactiondate<@todate ");

                    qb.CurrentQuery = SQL_Customerpaymentsummary;
                    if (_reportcreteria.customerid > 0)
                        qb.AddParameter("customerinvoice.customerid", _reportcreteria.customerid, "=");
                    if (_reportcreteria.companyid > 0)
                        qb.AddParameter("customerinvoice.companyid", _reportcreteria.companyid, "=");
                    if (_reportcreteria.locationid > 0)
                        qb.AddParameter("bill.locationid", _reportcreteria.locationid, "=");

                    qb.GroupBY = "customer.name, customer.gstno, area, customer.mobileno,referencelist.name";
                    qb.SortField = "customer.name";

                    command = qb.GetCommand(conn);
                }
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        CustomerPayReport oitem = new CustomerPayReport();
                        oitem.customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        if (_reportcreteria.showdetail)
                            oitem.companyname = reader["companyname"] == DBNull.Value ? "" : reader["companyname"].ToString();
                        oitem.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                        oitem.area = reader["area"] == DBNull.Value ? "" : reader["area"].ToString();
                        oitem.gstno = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                        oitem.city = reader["cityname"] == DBNull.Value ? "" : reader["cityname"].ToString();
                        oitem.credit = reader["credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["credit"]);
                        oitem.paid = reader["paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid"]);
                        oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        oitem.balance = oitem.credit - (oitem.paid + oitem.discount);
                        if (_reportcreteria.showdetail)
                        {
                            oitem.createduserid = reader["createdby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["createdby"]);
                            oitem.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                            oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                            oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            oitem.transactiondate = reader["transactiondate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["transactiondate"]);
                        }
                        if (_reportcreteria.showsalesummary)
                        {
                            if (oitem.balance > 0)
                                lst.Add(oitem);
                        }
                        else
                            lst.Add(oitem);
                    }
                }
                conn.Close();

                if (_reportcreteria.showdetail)
                {
                    EmployeeDataService usersDataService = new EmployeeDataService() { Context = this.Context };
                    var usernames = usersDataService.GetUserName(lst.ConvertAll(x => x.createduserid).Distinct().ToList());
                    lst.ForEach(x =>
                    {
                        if (usernames.Exists(y => y.id == x.createduserid))
                        {
                            x.createdby = usernames.Find(y => y.id == x.createduserid).name;
                        }
                    });
                }
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public SalesmanReceipt SearchSalesmanReceipt(RetailReportCreteria _reportcreteria)
        {
            string SQL_Salesmansummary = @"Select employeecode, sum(billitems.receivable) amount 
from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
left outer join employee on salesmanid = employee.id
where bill.isactive = true and billtype!=9 and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
group by employeecode
order by employeecode";
            string SQL_Salesmanbillsummary = @"Select employeecode, bill.billno, sum(billitems.receivable) amount 
from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
left outer join employee on salesmanid = employee.id
where bill.isactive = true and billtype!=9 and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
group by employeecode, bill.billno
order by bill.billno, employeecode";
            string SQL_countersummary = @"Select counter.name as counter, sum(bill.receivable+bill.rounding) amount
from bill left outer join referencelist counter on counter.id = bill.counterid
where bill.isactive = true and billtype!=9 and bill.billdate>=@fromdate and bill.billdate<@todate
and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
group by counter.name
order by counter";

            SalesmanReceipt salesmanreceipt = new SalesmanReceipt();
            List<SalesmanReceipt.Salesman> lstsalesman = new List<SalesmanReceipt.Salesman>();
            List<SalesmanReceipt.Salesman> lstsalesbill = new List<SalesmanReceipt.Salesman>();
            List<SalesmanReceipt.Salesman> lstcounter = new List<SalesmanReceipt.Salesman>();

            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(SQL_Salesmansummary, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("salesmanid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReceipt.Salesman oitem = new SalesmanReceipt.Salesman();
                        oitem.sno = lstsalesman.Count + 1;
                        oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        oitem.empno = reader["employeecode"] == DBNull.Value ? "" : reader["employeecode"].ToString();
                        lstsalesman.Add(oitem);
                    }
                }

                command = GetCommand(SQL_Salesmanbillsummary, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("salesmanid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReceipt.Salesman oitem = new SalesmanReceipt.Salesman();
                        oitem.sno = lstsalesbill.Count + 1;
                        oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        oitem.empno = reader["employeecode"] == DBNull.Value ? "" : reader["employeecode"].ToString();
                        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        lstsalesbill.Add(oitem);
                    }
                }
                command = GetCommand(SQL_countersummary, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("salesmanid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReceipt.Salesman oitem = new SalesmanReceipt.Salesman();
                        oitem.sno = lstcounter.Count + 1;
                        oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        oitem.empno = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        lstcounter.Add(oitem);
                    }
                }

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            salesmanreceipt.lstbillsummary = lstsalesbill;
            salesmanreceipt.lstsalesman = lstsalesman;
            salesmanreceipt.lstcountersummary = lstcounter;
            return salesmanreceipt;
        }
        public List<SalesmanReport> SearchSalesman(RetailReportCreteria _reportcreteria)
        {
            List<SalesmanReport> lst = new List<SalesmanReport>();
            SortedDictionary<long, List<string>> markers = new SortedDictionary<long, List<string>>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            bool isbillcount = false;
            try
            {
                conn.Open();

                NpgsqlCommand command = null;

                if (_reportcreteria.showmarker)
                {
                    command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesmanMarker, _reportcreteria.showsalesummary ? "and billitems.receivable < 0 " : "")), conn);
                }
                else if (_reportcreteria.hidebusinesstrend)
                {
                    command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesmanDatewise, _reportcreteria.showsalesummary ? "and billitems.receivable < 0 " : "")), conn);
                }
                else if (_reportcreteria.integration)
                {
                    command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesmanBillwise, _reportcreteria.showsalesummary ? "and billitems.receivable < 0 " : "")), conn);
                }
                else
                {
                    if (_reportcreteria.showdetail)
                        command = GetCommand(GetSQL4B2B("", string.Format(SQL_SalesmanSection, _reportcreteria.showsalesummary ? "and billitems.receivable < 0 " : "")), conn);
                    else
                    {
                        isbillcount = true;
                        command = GetCommand(GetSQL4B2B("", string.Format(SQL_Salesman, _reportcreteria.showsalesummary ? "and billitems.receivable < 0 " : "")), conn);
                    }
                }
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("salesmanid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReport oitem = new SalesmanReport();
                        oitem.markername = "";
                        if (_reportcreteria.hidebusinesstrend)
                            oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);

                        if (!Context.HasPermission(PermissionSet.showsellingvalue, InfyPOS.Common.Action.View))
                        {
                            oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                            oitem.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            oitem.taxableamount = Math.Round(oitem.amount - oitem.tax, 2);
                        }
                        oitem.section = reader["section"] == DBNull.Value ? "" : reader["section"].ToString();

                        if (_reportcreteria.showdetail)
                        {
                            oitem.costprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                            oitem.icostprice = reader["ibuyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["ibuyingprice"]);
                        }

                        if (isbillcount)
                            oitem.billcount = reader["billcount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billcount"]);
                        if (!_reportcreteria.showdetail || _reportcreteria.showmarker)
                        {
                            oitem.employeecode = reader["employeecode"] == DBNull.Value ? "" : reader["employeecode"].ToString();
                            oitem.employeename = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                            oitem.floor = reader["floor"] == DBNull.Value ? "" : reader["floor"].ToString();
                        }
                        if (_reportcreteria.showmarker)
                        {
                            oitem.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                            oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            oitem.costprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                            oitem.icostprice = reader["ibuyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["ibuyingprice"]);
                        }
                        if (_reportcreteria.integration)
                        {
                            oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);

                            // This field being used to Gross Sale value
                            oitem.additionaldiscount = oitem.amount + oitem.discount;
                        }
                        lst.Add(oitem);
                    }

                    if (_reportcreteria.showmarker && reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            string barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                            long markerid = reader["markerid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["markerid"]);
                            if (!markers.ContainsKey(markerid))
                            {
                                markers.Add(markerid, new List<string>());
                            }
                            markers[markerid].Add(barcode);
                        }
                    }
                }


                conn.Close();

                if (_reportcreteria.showmarker && markers.Count > 0)
                {
                    ReferencelistDataService referencelistDataService = new ReferencelistDataService() { Context = this.Context };
                    List<Referencelist> config = referencelistDataService.Search(new Models.ReferencelistCreteria()
                    {
                        type = "MARKER",
                        inactive = true

                    });
                    if (config.Exists(e => e.additionalinfo != null && e.additionalinfo.rewardpoint > 0))
                    {
                        var configrates = config.FindAll(e => e.additionalinfo != null && e.additionalinfo.rewardpoint > 0).ConvertAll(e => new { name = e.name, id = e.id, rewardpoint = e.additionalinfo.rewardpoint });
                        markers.ToList().ForEach(x =>
                        {
                            var mconfig = config.Find(y => y.id == x.Key);
                            var lstbarcodes = lst.FindAll(y => x.Value.Contains(y.barcode));
                            var iconfig = configrates.Find(e => e.id == x.Key);
                            lstbarcodes.ForEach(y =>
                            {
                                y.markername = mconfig.name;
                                if (iconfig != null)
                                {
                                    if (iconfig.name.Contains("%"))
                                    {
                                        y.incentive = Math.Round(y.amount * iconfig.rewardpoint / 100);
                                    }
                                    else
                                    {
                                        y.incentive = Math.Round(y.qty * iconfig.rewardpoint);
                                    }
                                }
                            });
                        });
                    }
                    if (_reportcreteria.showmarkerincentive)
                    {
                        List<SalesmanReport> lstsummary = new List<SalesmanReport>();
                        lst.RemoveAll(x => x.incentive == 0);
                        foreach (var sitem in lst.GroupBy(x => new { x.employeecode, x.employeename, x.section, x.floor, x.markername }))
                        {
                            lstsummary.Add(new SalesmanReport()
                            {
                                employeecode = sitem.Key.employeecode,
                                employeename = sitem.Key.employeename,
                                section = sitem.Key.section,
                                floor = sitem.Key.floor,
                                markername = sitem.Key.markername,
                                incentive = sitem.Sum(x => x.incentive),
                                qty = sitem.Sum(x => x.qty),
                                amount = sitem.Sum(x => x.amount)
                            });
                        }
                        lst = lstsummary;
                    }
                    else if (_reportcreteria.showmarker)
                    {
                        lst.RemoveAll(x => string.IsNullOrEmpty(x.markername));
                    }
                }
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public List<SalesmanReport> SearchSalesmanDetailSales(RetailReportCreteria _reportcreteria)
        {
            string SQL_Barcodewise = @"with newstockmarker as (
Select min(id) id, salablegoodsid 
from stockmarker where isactive=true
group by  salablegoodsid 
)

    Select marker.name markername,promotions.name as schemename,employeecode, employee.name, products.salescounterid, floor.name floor, section.name section,billitems.id as billitemid, billitems.barcode, bill.billdate, bill.billno, 
    brand.name brandname, products.name productname, size.name sizename, style.name stylename, lrinvoice.invoicedate,
    cast(billitems.attributes->> 'islastbit' as boolean) islastbit, cast(billitems.attributes->> 'lastbitqty' as numeric) lastbitqty,
    sum(billitems.qty) qty,
    sum(billitems.receivable-billitems.tax) taxableamount,billitems.tax, billitems.price, counters.name countername,
    sum(billitems.discount) discount, sum(billitems.additionaldiscount::numeric * billitems.qty::numeric) additionaldiscount, 
    sum(billitems.receivable) amount, sum(billitems.schemediscount) schemediscount,
    sum(case when coalesce(incentiveconfig.percentage::numeric,0::numeric)>0::numeric 
	then billitems.receivable::numeric*coalesce(incentiveconfig.percentage::numeric,0::numeric)/100::numeric 
	else billitems.qty::numeric*coalesce(incentiveconfig.incentive::numeric ,0::numeric) end)::numeric as incentive
from bill 
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
inner join salablegoods on salablegoods.id = billitems.salablegoodsid
inner join stock on stock.id = salablegoods.stockid
left outer join lrinvoiceitems on lrinvoiceitems.id = stock.invoiceitemid
left outer join lrinvoice on lrinvoice.id = lrinvoiceitems.lrinvoiceid
left outer join promotions on billitems.schemeid = promotions.id
left outer join newstockmarker on newstockmarker.salablegoodsid = salablegoods.id
left outer join stockmarker on stockmarker.id = newstockmarker.id
left outer join incentiveconfig on incentiveconfig.salablegoodsid = billitems.salablegoodsid and incentiveconfig.isactive = true
left outer join items on items.id = stock.itemid 
left outer join products on products.id = stock.productid 
left outer join brand brand on brand.id = items.brandid 
left outer join employee on salesmanid = employee.id
left outer join referencelist section on section.id = employee.sectionid 
left outer join referencelist floor on floor.id = employee.floorid
left outer join referencelist marker on marker.id = stockmarker.markerid
left outer join referencelist size on size.id = sizeid
left outer join referencelist style on style.id = styleid 
left outer join referencelist counters on counters.id = bill.counterid
where billitems.isactive=true ";

            List<SalesmanReport> lst = new List<SalesmanReport>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                QueryBuilder qb = new QueryBuilder();
                qb.CurrentQuery = SQL_Barcodewise;

                qb.AddParameter("bill.isactive", true, "=");
                qb.AddParameter("bill.locationid", _reportcreteria.locationid, "=");
                qb.AddParameter("bill.billtype", 9, "!=");

                if (_reportcreteria.schemeid > 0)
                    //    qb.Add2Query("(billitems.schemeid=0 or 0=0)");
                    //else
                    qb.AddParameter("billitems.schemeid", _reportcreteria.schemeid, "=");

                if (_reportcreteria.fromdate != DateTime.MinValue && _reportcreteria.todate != DateTime.MinValue)
                {
                    qb.AddParameter("bill.billdate", "billdatefrom", _reportcreteria.fromdate.Date, ">=");
                    qb.AddParameter("bill.billdate", "billdateto", _reportcreteria.todate.AddDays(1).Date, "<");
                }

                if (!string.IsNullOrEmpty(_reportcreteria.barcode))
                    qb.AddParameter("billitems.barcode", _reportcreteria.barcode, "=");
                if (_reportcreteria.employeeid > 0)
                    qb.AddParameter("employee.id", _reportcreteria.employeeid, "=");
                if (_reportcreteria.stockmarkerid > 0)
                    qb.AddParameter("stockmarker.markerid", _reportcreteria.stockmarkerid, "=");
                if (_reportcreteria.sectionid > 0)
                    qb.AddParameter("products.salescounterid", _reportcreteria.sectionid, "=");

                qb.GroupBY = "marker.name, promotions.name, employeecode, employee.name, products.salescounterid, floor.name, section.name, " +
                    "billitems.id, billitems.barcode, bill.billdate, bill.billno, brand.name, products.name, size.name, style.name,billitems.tax, billitems.price,lrinvoice.invoicedate,counters.name," +
                    "cast(billitems.attributes->> 'islastbit' as boolean), cast(billitems.attributes->> 'lastbitqty' as numeric) ";
                qb.SortField = "employeecode";

                command = qb.GetCommand(conn);

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReport oitem = new SalesmanReport();
                        oitem.billitemid = reader["billitemid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["billitemid"]);
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.section = reader["section"] == DBNull.Value ? "" : reader["section"].ToString();
                        oitem.schemename = reader["schemename"] == DBNull.Value ? "" : reader["schemename"].ToString();
                        oitem.markername = reader["markername"] == DBNull.Value ? "" : reader["markername"].ToString();
                        oitem.floor = reader["floor"] == DBNull.Value ? "" : reader["floor"].ToString();
                        oitem.employeecode = reader["employeecode"] == DBNull.Value ? "" : reader["employeecode"].ToString();
                        oitem.employeename = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        oitem.countername = reader["countername"] == DBNull.Value ? "" : reader["countername"].ToString();
                        oitem.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        oitem.invoicedate = reader["invoicedate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["invoicedate"]);
                        oitem.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                        oitem.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                        oitem.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
                        oitem.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                        oitem.salescounterid = reader["salescounterid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["salescounterid"]);
                        oitem.islastbit = reader["islastbit"] == DBNull.Value ? false : Convert.ToBoolean(reader["islastbit"]);
                        oitem.lastbitqty = reader["lastbitqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["lastbitqty"]);

                        if (!Context.HasPermission(PermissionSet.showsellingvalue, InfyPOS.Common.Action.View))
                        {
                            oitem.incentive = reader["incentive"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["incentive"]);
                            oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                            oitem.price = reader["price"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["price"]);
                            oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            oitem.additionaldiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            oitem.schemediscount = reader["schemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["schemediscount"]);
                            oitem.taxableamount = reader["taxableamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxableamount"]);
                            oitem.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);

                            if (oitem.schemediscount > 0)
                                oitem.discount = oitem.discount - oitem.schemediscount;
                        }

                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public List<SalesBarcodeVoid> SearchSalesVoid(RetailReportCreteria _reportcreteria)
        {
            List<SalesBarcodeVoid> lst = new List<SalesBarcodeVoid>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();

                NpgsqlCommand command = null;


                command = GetCommand(SQL_SalesVoid, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("employeeid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.employeeid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesBarcodeVoid oitem = new SalesBarcodeVoid();
                        oitem.glncode = reader["serialno"] == DBNull.Value ? "" : reader["serialno"].ToString();
                        oitem.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        oitem.hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                        oitem.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                        oitem.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                        oitem.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                        oitem.patternname = reader["patternname"] == DBNull.Value ? "" : reader["patternname"].ToString();
                        oitem.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                        oitem.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
                        oitem.materialname = reader["materialname"] == DBNull.Value ? "" : reader["materialname"].ToString();
                        oitem.typename = reader["typename"] == DBNull.Value ? "" : reader["typename"].ToString();
                        oitem.colourname = reader["colourname"] == DBNull.Value ? "" : reader["colourname"].ToString();
                        oitem.sectionname = reader["sectionname"] == DBNull.Value ? "" : reader["sectionname"].ToString();
                        oitem.designid = reader["designid"] == DBNull.Value ? "" : reader["designid"].ToString();
                        oitem.biller = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        oitem.counter = reader["countername"] == DBNull.Value ? "" : reader["countername"].ToString();
                        oitem.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        oitem.measure = reader["measure"] == DBNull.Value ? "NOS" : (reader["measure"].ToString() == "N" ? "NOS" : "METER");
                        oitem.invoiceno = reader["invoiceno"] == DBNull.Value ? "" : reader["invoiceno"].ToString();
                        oitem.invoicedate = reader["invoicedate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["invoicedate"]);
                        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);

                        if (!Context.HasPermission(PermissionSet.showvalue, InfyPOS.Common.Action.View))
                        {
                            oitem.mrp = reader["price"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["price"]);
                            oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            oitem.mrpvalue = Math.Round(oitem.mrp * oitem.qty, 2);
                            oitem.buyingprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                            oitem.ibuyingprice = reader["ibuyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["ibuyingprice"]);
                            oitem.buyingprice = Math.Round(oitem.buyingprice * oitem.qty, 2);
                            oitem.ibuyingprice = Math.Round(oitem.ibuyingprice * oitem.qty, 2);
                            if (oitem.ibuyingprice > oitem.buyingprice) oitem.taxoncostprice = Math.Round(oitem.ibuyingprice - oitem.buyingprice, 2);

                            oitem.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            oitem.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            oitem.taxableamount = Math.Round(oitem.receivable - oitem.tax, 2);

                            var schdiscount = reader["schemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["schemediscount"]);
                            oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            oitem.discount += reader["schemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["schemediscount"]);
                            oitem.discount += reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            if (schdiscount > 0)
                                oitem.discount = oitem.discount - schdiscount;

                        }

                        if (Context.HasPermission(PermissionSet.hidesupplier, InfyPOS.Common.Action.View))
                            oitem.suppliername = "hidden";
                        else
                            oitem.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                        lst.Add(oitem);
                    }
                }
                conn.Close();


                if (_reportcreteria.reporttype == "3")
                {
                    StoretransactionDataService storetransactionDataService = new StoretransactionDataService() { Context = this.Context };
                    var storeresult = storetransactionDataService.Search(new StoretransactionCreteria()
                    {
                        fromdate = _reportcreteria.fromdate,
                        todate = _reportcreteria.todate,
                        locationid = _reportcreteria.locationid,
                        type = "SaleReturn"
                    });
                    foreach (var items in storeresult.GroupBy(x => x.actiondate.Date))
                    {
                        var item = items.OrderBy(x => x.id).Last();
                        if (item.SalesReturnAtribute != null &&
                            item.SalesReturnAtribute.items != null &&
                            item.SalesReturnAtribute.items.Count > 0)
                        {
                            var validated = item.SalesReturnAtribute.items.FindAll(x => x.vqty != 0);
                            var validatedqty = item.SalesReturnAtribute.items.Sum(x => x.vqty);
                            validated.ForEach(x =>
                            {
                                var barcodes = lst.FindAll(y => y.barcode == x.barcode);
                                var eitem = lst.Find(y => y.barcode == x.barcode && y.vqty == 0 && Math.Abs(y.qty) == x.vqty);
                                if (eitem != null)
                                {
                                    eitem.vqty = x.vqty;
                                }
                                else
                                {
                                    eitem = lst.Find(y => y.barcode == x.barcode && Math.Abs(y.qty) - x.vqty >= 0);
                                    if (eitem != null)
                                    {
                                        eitem.vqty += x.vqty;
                                    }
                                }
                            });
                        }
                    }
                }
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        internal byte[] DownloadSalesBarcode(string orgid, string fromdate, string todate, string companyid, string locationid, string isb2b)
        {
            DateTime dateTime1 = BaseEntity.GetDataFromString(fromdate);
            DateTime dateTime2 = BaseEntity.GetDataFromString(todate);

            ClosedXML.Excel.XLWorkbook xLWorkbook = new ClosedXML.Excel.XLWorkbook();
            List<SalesBarcodeWise> lst = SearchSalesBarcode(new RetailReportCreteria()
            {
                fromdate = dateTime1,
                todate = dateTime2,
                companyid = long.Parse(companyid),
                locationid = long.Parse(locationid),
                isb2b = bool.Parse(isb2b)
            });

            using (System.IO.MemoryStream memoryStream = new System.IO.MemoryStream())
            {
                DataTable dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Company", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Location", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("EAN", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Item Code", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Barcode", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Product", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Section", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("HSN Code", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Supplier", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Brand", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Bill No", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Bill Date", typeof(DateTime)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Customer", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Customer GST", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("MRP", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Qty", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("MRP Value", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Taxable", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Tax %", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("IGST %", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("CGST %", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("SGST %", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Tax Value", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("IGST", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("CGST", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("SGST", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Sale Value", typeof(decimal)) });

                foreach (var p in lst)
                {
                    dt.Rows.Add(new object[] {
                        p.companyname,
                        p.locationname,
                        p.glncode,
                        p.itbuscode,
                        p.barcode,
                        p.productname,
                        p.sectionname,
                        p.hsncode,
                        p.suppliername,
                        p.brandname,
                        p.billno,
                        p.billdate,
                        p.customername,
                        p.gstno,
                        p.mrp,
                        p.qty,
                        p.mrpvalue,
                        p.taxableamount,
                        p.taxpercentage,
                        p.igsttaxpercentage,
                        p.cgsttaxpercentage,
                        p.sgsttaxpercentage,
                        p.tax,
                        p.igst,
                        p.cgst,
                        p.sgst,
                        p.receivable
                    });
                }
                var sheet = xLWorkbook.AddWorksheet(dt, "Sales");

                xLWorkbook.SaveAs(memoryStream);
                return memoryStream.ToArray();
            }

        }
        public List<SalesBarcodeWise> SearchSalesBarcode(RetailReportCreteria _reportcreteria)
        {
            List<SalesBarcodeWise> lst = new List<SalesBarcodeWise>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                string query = "";
                if (string.IsNullOrEmpty(_reportcreteria.reporttype))
                    _reportcreteria.reporttype = "0";

                if (_reportcreteria.reporttype == "1")
                    query = string.Format(SQL_SalesBarcode, (_reportcreteria.includeb2b) ? "" : "and bill.isb2b=false", " and billitems.qty>0 ");
                else if (_reportcreteria.reporttype == "2" || _reportcreteria.reporttype == "3")
                    query = string.Format(SQL_SalesBarcode, (_reportcreteria.includeb2b) ? "" : "and bill.isb2b=false", " and billitems.qty<0 ");
                else
                    query = string.Format(SQL_SalesBarcode, (_reportcreteria.includeb2b) ? "" : "and bill.isb2b=false", " ");

                //if (_reportcreteria.reporttype == "0" || _reportcreteria.reporttype == "1" || _reportcreteria.reporttype == "2")
                if (_reportcreteria.reporttype == "0" || _reportcreteria.reporttype == "1")
                    query = query.Replace("and billtype in (8, 9) and bill.isreturn=true and bill.unsettledcancelled=false", "and billtype!=9 ");

                if (_reportcreteria.isb2b)
                    query = query.Replace("and bill.isb2b=false", "and bill.isb2b=true");

                if (_reportcreteria.onlysales)
                    query = query.Replace("where bill.isactive = true", "where bill.isactive = true and salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty) < 0 and salablegoods.oqty !=0");

                command = GetCommand(query, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesBarcodeWise oitem = new SalesBarcodeWise();
                        oitem.glncode = reader["serialno"] == DBNull.Value ? "" : reader["serialno"].ToString();
                        oitem.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        oitem.hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                        oitem.itbuscode = reader["itbuscode"] == DBNull.Value ? "" : reader["itbuscode"].ToString();
                        oitem.posid = reader["posid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["posid"]);
                        oitem.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                        oitem.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                        oitem.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                        oitem.patternname = reader["patternname"] == DBNull.Value ? "" : reader["patternname"].ToString();
                        oitem.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                        oitem.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
                        oitem.materialname = reader["materialname"] == DBNull.Value ? "" : reader["materialname"].ToString();
                        oitem.typename = reader["typename"] == DBNull.Value ? "" : reader["typename"].ToString();
                        oitem.colourname = reader["colourname"] == DBNull.Value ? "" : reader["colourname"].ToString();
                        oitem.sectionname = reader["sectionname"] == DBNull.Value ? "" : reader["sectionname"].ToString();
                        oitem.returnreason = reader["returnreason"] == DBNull.Value ? "" : reader["returnreason"].ToString();
                        oitem.designid = reader["designid"] == DBNull.Value ? "" : reader["designid"].ToString();
                        oitem.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        oitem.measure = reader["measure"] == DBNull.Value ? "NOS" : (reader["measure"].ToString() == "N" ? "NOS" : "METER");
                        oitem.invoiceno = reader["invoiceno"] == DBNull.Value ? "" : reader["invoiceno"].ToString();
                        oitem.invoicedate = reader["invoicedate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["invoicedate"]);
                        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        oitem.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        oitem.customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        oitem.gstno = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                        oitem.companyname = reader["companyname"] == DBNull.Value ? "" : reader["companyname"].ToString();
                        oitem.locationname = reader["locationname"] == DBNull.Value ? "" : reader["locationname"].ToString();
                        oitem.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);

                        if (!Context.HasPermission(PermissionSet.showvalue, InfyPOS.Common.Action.View))
                        {
                            oitem.mrp = reader["price"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["price"]);
                            oitem.mrpvalue = Math.Round(oitem.mrp * oitem.qty, 2);
                            oitem.buyingprice = reader["buyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["buyingprice"]);
                            oitem.ibuyingprice = reader["ibuyingprice"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["ibuyingprice"]);
                            oitem.buyingprice = Math.Round(oitem.buyingprice * oitem.qty, 2);
                            oitem.ibuyingprice = Math.Round(oitem.ibuyingprice * oitem.qty, 2);
                            if (oitem.ibuyingprice > oitem.buyingprice) oitem.taxoncostprice = Math.Round(oitem.ibuyingprice - oitem.buyingprice, 2);

                            oitem.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            oitem.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            oitem.taxableamount = Math.Round(oitem.receivable - oitem.tax, 2);

                            oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            oitem.schemediscount = reader["schemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["schemediscount"]);
                            oitem.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            //oitem.discount += reader["schemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["schemediscount"]);
                            //oitem.discount += reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            if (oitem.schemediscount > 0)
                                oitem.discount = oitem.discount - oitem.schemediscount;
                            oitem.totaldiscount = oitem.discount + oitem.schemediscount + oitem.addlndiscount;

                            oitem.grossvalue = oitem.receivable + oitem.totaldiscount;

                            if (oitem.grossvalue != 0 && oitem.totaldiscount != 0)
                                oitem.totaldiscountpercent = Math.Round(oitem.totaldiscount / oitem.grossvalue * 100, 2);
                            if (oitem.grossvalue != 0 && oitem.discount != 0)
                                oitem.discountpercent = Math.Round(oitem.discount / oitem.grossvalue * 100, 2);
                            if (oitem.grossvalue != 0 && oitem.addlndiscount != 0)
                                oitem.addlndiscountpercent = Math.Round(oitem.addlndiscount / oitem.grossvalue * 100, 2);
                            if (oitem.grossvalue != 0 && oitem.schemediscount != 0)
                                oitem.schemediscountpercent = Math.Round(oitem.schemediscount / oitem.grossvalue * 100, 2);

                            if (oitem.isinterstatesale)
                            {
                                oitem.igsttaxpercentage = oitem.taxpercentage;
                                oitem.igst = oitem.tax;
                            }
                            else
                            {
                                oitem.cgsttaxpercentage = oitem.taxpercentage > 0 ? Math.Round((oitem.taxpercentage / 2), 2) : 0;
                                oitem.sgsttaxpercentage = oitem.taxpercentage > 0 ? Math.Round((oitem.taxpercentage / 2), 2) : 0;
                                oitem.cgst = oitem.tax != 0 ? Math.Round((oitem.tax / 2), 2) : 0;
                                oitem.sgst = oitem.tax != 0 ? Math.Round((oitem.tax / 2), 2) : 0;
                            }

                        }

                        if (Context.HasPermission(PermissionSet.hidesupplier, InfyPOS.Common.Action.View))
                            oitem.suppliername = "hidden";
                        else
                            oitem.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                        lst.Add(oitem);
                    }
                }
                conn.Close();


                if (_reportcreteria.reporttype == "3")
                {
                    StoretransactionDataService storetransactionDataService = new StoretransactionDataService() { Context = this.Context };
                    var storeresult = storetransactionDataService.Search(new StoretransactionCreteria()
                    {
                        fromdate = _reportcreteria.fromdate,
                        todate = _reportcreteria.todate,
                        locationid = _reportcreteria.locationid,
                        type = "SaleReturn"
                    });
                    foreach (var items in storeresult.GroupBy(x => x.actiondate.Date))
                    {
                        var item = items.OrderBy(x => x.id).Last();
                        if (item.SalesReturnAtribute != null &&
                            item.SalesReturnAtribute.items != null &&
                            item.SalesReturnAtribute.items.Count > 0)
                        {
                            var validated = item.SalesReturnAtribute.items.FindAll(x => x.vqty != 0);
                            var validatedqty = item.SalesReturnAtribute.items.Sum(x => x.vqty);
                            validated.ForEach(x =>
                            {
                                var barcodes = lst.FindAll(y => y.barcode == x.barcode);
                                var eitem = lst.Find(y => y.barcode == x.barcode && y.vqty == 0 && Math.Abs(y.qty) == x.vqty);
                                if (eitem != null)
                                {
                                    eitem.vqty = x.vqty;
                                }
                                else
                                {
                                    eitem = lst.Find(y => y.barcode == x.barcode && Math.Abs(y.qty) - x.vqty >= 0);
                                    if (eitem != null)
                                    {
                                        eitem.vqty += x.vqty;
                                    }
                                }
                            });
                        }
                    }
                }
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public List<HSNSummary> SearchSalesHSNSummary(RetailReportCreteria _reportcreteria)
        {
            List<HSNSummary> lst = new List<HSNSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            string sql = @" Select billitems.hsncode, bill.isinterstatesale, billitems.taxpercentage, products.name, case when products.sellingmode = 3 then 'M' else 'N' end as Measure, 
                        sum(billitems.receivable) receivable, sum(billitems.qty) qty, sum(billitems.tax) tax                        
                        from bill 
                        inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        inner join salablegoods on salablegoods.id = billitems.salablegoodsid
                        inner join stock on stock.id = salablegoods.stockid
                        inner join products on products.id = stock.productid
                        where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end 
                        group by billitems.hsncode, bill.isinterstatesale, billitems.taxpercentage, products.name, 
                        case when products.sellingmode = 3 then 'M' else 'N' end
                        UNION ALL
                        select cast(additionalinfo->>'formula' as character varying(10)) as hsncode, bill.isinterstatesale, 
                        Billadditionalcharges.taxpercentage, Billadditionalcharges.name, 'N' as Measure,
                        sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 0 qty, sum(Billadditionalcharges.tax) tax
                        from bill inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                        inner join referencelist on referencelist.id = Billadditionalcharges.additionalchargestypeid
                        where bill.isactive = true and billtype!=9 and bill.isb2b=@isb2b and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                        and case when @companyid=0 then bill.companyid != 0 else bill.companyid = @companyid end 
                        and cast(additionalinfo->>'paytype' as character varying(10)) != 'EXPORTGST'
                        --and Billadditionalcharges.taxpercentage>0 and Billadditionalcharges.tax != 0
                        group by cast(additionalinfo->>'formula' as character varying(10)), bill.isinterstatesale, 
                        Billadditionalcharges.taxpercentage, Billadditionalcharges.name, Measure
                        order by hsncode, taxpercentage ";

            if (_reportcreteria.showdetail)
            {
                sql = sql.Replace("products.name,", "");
                sql = sql.Replace("Billadditionalcharges.name,", "");
            }
            if (_reportcreteria.hsnsourceid == 1)
                sql = sql.Replace("billitems.hsncode", "stock.hsncode");
            else if (_reportcreteria.hsnsourceid == 2)
                sql = sql.Replace("billitems.hsncode", "products.hsncode");

            if (_reportcreteria.includeb2b)
                sql = sql.Replace("and bill.isb2b=@isb2b", "");
            try
            {
                conn.Open();
                NpgsqlCommand command = null;
                command = GetCommand(sql, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        HSNSummary oitem = null;
                        string hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                        string productname = "";
                        if (!_reportcreteria.showdetail)
                            productname = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        string units = reader["Measure"] == DBNull.Value ? "NOS-NUMBERS" : (reader["Measure"].ToString() == "N" ? "NOS-NUMBERS" : "MTR-METERS");
                        decimal taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        bool interstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);

                        if (lst.Exists(e => e.hsncode == hsncode && e.unit == units
                        && e.taxpercentage == taxpercentage && e.productname == productname && e.isinterstatesale == interstatesale))
                        {
                            oitem = lst.Find(e => e.hsncode == hsncode && e.unit == units
                                && e.taxpercentage == taxpercentage && e.productname == productname && e.isinterstatesale == interstatesale);

                            oitem.qty += reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            oitem.tax += reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            oitem.value += reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            oitem.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                            oitem.taxable = Math.Round(oitem.value - oitem.tax, 2);
                            oitem.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);

                            if (oitem.isinterstatesale && oitem.tax != 0)
                            {
                                oitem.igst += reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            }
                            else
                            {
                                oitem.sgst += Math.Round(oitem.tax / 2, 2);
                                oitem.cgst += Math.Round(oitem.tax / 2, 2);
                            }
                        }
                        else
                        {
                            oitem = new HSNSummary();
                            oitem.hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                            if (_reportcreteria.showdetail)
                                oitem.productname = "";
                            else
                                oitem.productname = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                            oitem.unit = reader["Measure"] == DBNull.Value ? "NOS-NUMBERS" : (reader["Measure"].ToString() == "N" ? "NOS-NUMBERS" : "MTR-METERS");
                            oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            oitem.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            oitem.value = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            oitem.isinterstatesale = reader["isinterstatesale"] == DBNull.Value ? false : Convert.ToBoolean(reader["isinterstatesale"]);
                            oitem.taxable = Math.Round(oitem.value - oitem.tax, 2);
                            oitem.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);

                            if (oitem.isinterstatesale && oitem.tax != 0)
                            {
                                oitem.igst = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            }
                            else
                            {
                                oitem.sgst = Math.Round(oitem.tax / 2, 2);
                                oitem.cgst = Math.Round(oitem.tax / 2, 2);
                            }
                            lst.Add(oitem);
                        }
                    }
                }
                conn.Close();

            }
            catch (Exception exp)
            {
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public POReport SearchSalesHSN(RetailReportCreteria _reportcreteria)
        {
            POReport saleshsn = new POReport();
            List<POReport.taxheader> lsttaxheader = new List<POReport.taxheader>();
            List<POEntry> lst = new List<POEntry>();
            List<POEntry> result = new List<POEntry>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                string _SQL = _reportcreteria.gstbill ? SQL_SalesGSTHSN : (_reportcreteria.nongstbill ? SQL_SalesNONGSTHSN : SQL_SalesHSN);

                string condition = "";

                if (_reportcreteria.sectionid == 1)
                    condition = condition + " and products.sellingmode != 3";
                else if (_reportcreteria.sectionid == 2)
                    condition = condition + " and products.sellingmode = 3";

                if (_reportcreteria.onlysales)
                    condition = condition + " and billitems.qty>0";

                else if (_reportcreteria.onlyreturn)
                    condition = condition + " and billitems.qty<0";


                if (_reportcreteria.posbill)
                    condition = condition + " and bill.billtype in (0,8) and bill.isb2b=false";

                if (_reportcreteria.dealerbill)
                    condition = condition + " and bill.billtype =1";

                if (_reportcreteria.creditbill)
                    condition = condition + " and bill.iscreditbill =true ";

                if (_reportcreteria.onlyb2b)
                    _SQL = _SQL.Replace("and bill.isb2b=@isb2b", "and bill.isb2b=true");

                if (_reportcreteria.includeb2b)
                    _SQL = _SQL.Replace("and bill.isb2b=@isb2b", "");

                _SQL = string.Format(_SQL, condition);

                if (_reportcreteria.showdetail)
                {
                    _SQL = _SQL.Replace("products.name,", "");
                    _SQL = _SQL.Replace("Billadditionalcharges.name,", "");
                }

                if (_reportcreteria.hsnsourceid == 1)
                    _SQL = _SQL.Replace("billitems.hsncode", "stock.hsncode");
                else if (_reportcreteria.hsnsourceid == 2)
                    _SQL = _SQL.Replace("billitems.hsncode", "products.hsncode");


                conn.Open();
                NpgsqlCommand command = null;
                command = GetCommand(_SQL, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                List<decimal> taxpercent = new List<decimal>();
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        POEntry oitem;
                        string hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                        string billno = "";
                        string customername = "";
                        string customergst = "";
                        string units = reader["Measure"] == DBNull.Value ? "Nos" : (reader["Measure"].ToString() == "N" ? "Nos" : "Mts");
                        if (_reportcreteria.gstbill)
                        {
                            billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            customergst = reader["gstno"] == DBNull.Value ? "" : reader["gstno"].ToString();
                        }
                        string productname = "";
                        decimal taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        if (!_reportcreteria.showdetail)
                            productname = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();

                        if (lst.Exists(e => e.hsncode == hsncode
                            && e.productname == productname
                            && e.billno == billno
                            && e.customer == customername
                            && e.gstno == customergst
                            && e.measure == units))
                        {
                            oitem = lst.Find(e => e.hsncode == hsncode && e.productname == productname
                                && e.billno == billno && e.customer == customername && e.gstno == customergst && e.measure == units);
                        }
                        else
                        {
                            oitem = new POEntry();
                            oitem.taxbreakup = new List<POEntry.POTaxValue>();
                            oitem.hsncode = reader["hsncode"] == DBNull.Value ? "" : reader["hsncode"].ToString();
                            oitem.measure = reader["Measure"] == DBNull.Value ? "Nos" : (reader["Measure"].ToString() == "N" ? "Nos" : "Mts");
                            if (_reportcreteria.showdetail)
                                oitem.productname = "";
                            else
                                oitem.productname = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                            oitem.billno = billno;
                            oitem.gstno = customergst;
                            oitem.customer = customername;
                            lst.Add(oitem);
                        }


                        POEntry.POTaxValue otax = new POEntry.POTaxValue();
                        otax.taxpercent = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        otax.taxamount = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        otax.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        otax.taxableamount = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - otax.taxamount;
                        if (oitem.taxbreakup.Exists(e => e.taxpercent == otax.taxpercent))
                        {
                            var taxb = oitem.taxbreakup.Find(e => e.taxpercent == otax.taxpercent);
                            taxb.taxamount += otax.taxamount;
                            taxb.qty += otax.qty;
                            taxb.taxableamount += otax.taxableamount;
                        }
                        else
                        {
                            oitem.taxbreakup.Add(otax);
                        }
                        if (!taxpercent.Contains(otax.taxpercent))
                            taxpercent.Add(otax.taxpercent);
                    }
                }
                conn.Close();

                // For Row level Total 
                foreach (POEntry item in lst)
                {
                    POEntry.POTaxValue otax = new POEntry.POTaxValue();
                    otax.taxpercent = 100;
                    otax.taxamount = item.taxbreakup.Sum(e => e.taxamount);
                    otax.qty = item.taxbreakup.Sum(e => e.qty);
                    otax.taxableamount = item.taxbreakup.Sum(e => e.taxableamount);

                    item.taxbreakup.Add(otax);
                }
                StringBuilder sb = new StringBuilder();
                foreach (var item in lst)
                {
                    if (item.taxbreakup.Exists(e => e.taxpercent == 12))
                    {
                        sb.Append(string.Format("{0}\t{1}\t{2}\r\n", item.hsncode, item.productname, item.taxbreakup.Find(e => e.taxpercent == 12).taxableamount));
                    }
                }

                var taxable = lst.Sum(e => e.taxbreakup.Sum(x => x.taxableamount));
                //List<decimal> taxpercent = lst.Select(x =>  x.percentage).Distinct().ToList();
                if (taxpercent != null && taxpercent.Count > 0)
                {
                    foreach (decimal taxitem in taxpercent.OrderBy(e => e).ToList())
                    {
                        lsttaxheader.Add(new POReport.taxheader
                        {
                            percentage = taxitem,
                            type = 1,
                            displaytext = taxitem.ToString() + "% VALUE",
                            taxalevalue = lst.Sum(e => e.taxbreakup.Sum(x => x.taxpercent == taxitem ? x.taxableamount : 0))
                        });
                        lsttaxheader.Add(new POReport.taxheader
                        {
                            percentage = taxitem,
                            type = 2,
                            displaytext = taxitem.ToString() + "% TAX"
                        });
                        lsttaxheader.Add(new POReport.taxheader
                        {
                            percentage = taxitem,
                            type = 3,
                            displaytext = taxitem.ToString() + "% QTY"
                        });
                    }
                    lsttaxheader.Add(new POReport.taxheader
                    {
                        percentage = 100,
                        type = 1,
                        displaytext = "TOT.VALUE",
                    });
                    lsttaxheader.Add(new POReport.taxheader
                    {
                        percentage = 100,
                        type = 2,
                        displaytext = "TOT.TAX"
                    });
                    lsttaxheader.Add(new POReport.taxheader
                    {
                        percentage = 100,
                        type = 3,
                        displaytext = "TOT.QTY"
                    });
                }
                //List<string> ids = lst.GroupBy(g => new { g.hsncode , g.productname}).Where(grp => grp.Count() > 1).Select(grp => grp.Key.hsncode).ToList();


                //if (ids != null && ids.Count > 0)
                //{
                //    foreach (string id in ids)
                //    {
                //        List<POEntry> tomerge = lst.Where(x => x.hsncode == id).ToList();
                //        lst.RemoveAll(x => x.hsncode == id);

                //        POEntry oitem = new POEntry();
                //        oitem.taxbreakup = new List<POEntry.POTaxValue>();
                //        int count = 0;
                //        foreach (POEntry newitem in tomerge)
                //        {
                //            if (count == 0)
                //            {
                //                oitem.invoiceid = newitem.invoiceid;
                //                oitem.supplier = newitem.supplier;
                //                oitem.cityid = newitem.cityid;
                //                oitem.isinterstatesale = newitem.isinterstatesale;
                //                oitem.hsncode = newitem.hsncode;
                //                oitem.measure = newitem.measure;
                //                oitem.productname = newitem.productname;
                //            }
                //            POEntry.POTaxValue otax = new POEntry.POTaxValue();
                //            otax.taxpercent = newitem.taxbreakup[0].taxpercent;
                //            otax.taxamount = newitem.taxbreakup[0].taxamount;
                //            otax.taxableamount = newitem.taxbreakup[0].taxableamount;
                //            otax.qty = newitem.taxbreakup[0].qty;
                //            oitem.taxbreakup.Add(otax);
                //            count++;
                //        }
                //        result.Add(oitem);
                //    }
                //}
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }

            //result.Sum(e=>e.taxbreakup.Sum(a>as)
            //result.AddRange(lst);
            saleshsn.poentry = lst;
            saleshsn.taxhead = lsttaxheader;
            return saleshsn;
        }

        const string SQL_SearchOpeningBalance = @"select id, isactive, createdby, modifiedby, version, createdon, modifiedon,status,cashierid, paidbyemployeeid, receivedbyemployeid, paidon, returnedon, counterid, locationid, openingamount, closingamount, openingdinomination, closingdinomination, billno,expenses, takenamount, cardamount, upiamount from cash where id=@id";

        public List<OpeningClosingSummary> SearchOpeningClosing(OpeningClosingSummary _cash)
        {
            List<OpeningClosingSummary> lst = new List<OpeningClosingSummary>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;

                QueryBuilder qb = new QueryBuilder();
                qb.CurrentQuery = SQL_SearchOpeningBalance.Substring(0, SQL_SearchOpeningBalance.IndexOf("where"));
                qb.AddParameter("isactive", true, "=");

                if (_cash.fromdate != DateTime.MinValue && _cash.todate != DateTime.MinValue)
                {
                    qb.AddParameter("paidon", "fromdate", _cash.fromdate.Date, ">=");
                    qb.AddParameter("paidon", "todate", _cash.todate.AddDays(1).Date, "<");
                }

                if (_cash.locationid > 0)
                    qb.AddParameter("locationid", _cash.locationid, "=");
                if (_cash.counterid > 0)
                    qb.AddParameter("counterid", _cash.counterid, "=");
                if (_cash.cashierid > 0)
                    qb.AddParameter("cashierid", _cash.cashierid, "=");

                qb.SortField = "paidon desc";
                command = qb.GetCommand(conn);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        OpeningClosingSummary ocash = new OpeningClosingSummary();
                        ocash.paidbyemployeeid = reader["paidbyemployeeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["paidbyemployeeid"].ToString());
                        ocash.cashierid = reader["cashierid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["cashierid"].ToString());
                        ocash.receivedbyemployeid = reader["receivedbyemployeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["receivedbyemployeid"].ToString());
                        ocash.paidon = reader["paidon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["paidon"].ToString());
                        ocash.returnedon = reader["returnedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["returnedon"].ToString());

                        ocash.counterid = reader["counterid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["counterid"].ToString());
                        ocash.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"].ToString());
                        ocash.expenses = reader["expenses"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["expenses"].ToString());
                        ocash.openingamount = reader["openingamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["openingamount"].ToString());
                        ocash.closingamount = reader["closingamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["closingamount"].ToString());
                        ocash.takenamount = reader["takenamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["takenamount"].ToString());
                        ocash.cardamount = reader["cardamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cardamount"].ToString());
                        ocash.upiamount = reader["upiamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["upiamount"].ToString());
                        lst.Add(ocash);
                    }
                }
                conn.Close();

                if (lst.Count > 0)
                {
                    List<SettlementReport> lstsettlement = SearchSettlement(new RetailReportCreteria()
                    {
                        fromdate = _cash.fromdate,
                        todate = _cash.todate,
                        locationid = _cash.locationid,
                        counterid = _cash.counterid
                    });

                    foreach (SettlementReport item in lstsettlement)
                    {
                        if (lst.Exists(e => e.locationid == item.locationid && e.counterid == item.counterid
                        && e.cashierid == item.cashierid && e.paidon.Date == item.receiptdate.Date))
                        {
                            var cashitem = lst.Find(e => e.locationid == item.locationid && e.counterid == item.counterid
                            && e.cashierid == item.cashierid && e.paidon.Date == item.receiptdate.Date);
                            cashitem.closingcollected = item.paid_cash;
                            cashitem.closingdifference = cashitem.closingamount - (item.paid_cash + item.openingcash);

                            cashitem.cardcollected = item.paid_card;
                            cashitem.carddifference = cashitem.cardamount - item.paid_card;

                            cashitem.upicollected = item.paid_upi;
                            cashitem.upidifference = cashitem.upiamount - item.paid_upi;

                            cashitem.creditnotereceived = item.paid_voucher;
                            cashitem.creditnoteissued = item.creditnote_refund;
                        }
                    }

                }
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _cash);
            }
            return lst;
        }

        public List<StockReport> SearchSalesAnalysis(StockReportCreteria _reportcreteria)
        {
            StringBuilder SQL_Select = new StringBuilder();
            StringBuilder SQL_From = new StringBuilder();
            StringBuilder SQL_Where = new StringBuilder();
            StringBuilder SQL_Groupby = new StringBuilder(@" group by ");
            StringBuilder SQL_Orderby = new StringBuilder(@" order by ");

            SQL_Select.Append(@"Select sum(billitems.receivable) as value, sum(billitems.qty) qty, sum(billitems.tax) tax, sum(billitems.discount) discount, sum(billitems.schemediscount) schemediscount, 
                                            sum(billitems.additionaldiscount::numeric * billitems.qty::numeric) additionaldiscount, sum(billitems.qty * stock.buyingprice::numeric) purchasevalue, sum(billitems.qty * stock.ibuyingprice::numeric) ipurchasevalue ");
            SQL_From.Append(@" from bill inner join billitems on billitems.billid = bill.id  
                    inner join salablegoods on salablegoods.id = billitems.salablegoodsid 
                    left outer join stock on stock.id = salablegoods.stockid 
                    left outer join lrinvoiceitems on lrinvoiceitems.id = stock.invoiceitemid
                    left outer join lrinvoice on lrinvoice.id = lrinvoiceitems.lrinvoiceid
                    left outer join lrentry on lrentry.id = lrinvoice.lrid
                    left outer join items on items.id = stock.itemid 
                    left outer join products on products.id = stock.productid 
                    left outer join supplier on supplier.id = stock.supplierid
                    left outer join suppliercompany on suppliercompany.supplierid = supplier.id
                        left outer join brand brand on brand.id = items.brandid
                        left outer join referencelist colour on colour.id = colourid
                        left outer join referencelist size on size.id = sizeid
                        left outer join referencelist style on style.id = styleid
                        left outer join referencelist pattern on pattern.id = patternid
                        left outer join referencelist material on material.id = materialid
                        left outer join referencelist type on type.id = typeid
                        left outer join referencelist section on section.id = products.salescounterid ");

            SQL_Where.Append(@" where bill.isactive = true and billitems.isactive=true and bill.billtype!=9 and bill.isb2b=@isb2b and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end and bill.billdate>=@fromdate and bill.billdate<@todate");

            List<StockReport> lst = new List<StockReport>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;

                QueryBuilder qb = new QueryBuilder();

                if (!_reportcreteria.product && !_reportcreteria.brand && !_reportcreteria.material
                    && !_reportcreteria.pattern && !_reportcreteria.style && !_reportcreteria.size
                    && !_reportcreteria.supplier && !_reportcreteria.section && !_reportcreteria.sourcesupplier)
                {
                    SQL_Select.Append(",products.name as column1");
                    SQL_Orderby.Append("products.name,");
                    SQL_Groupby.Append("products.name,");
                }
                if (_reportcreteria.product)
                {
                    SQL_Select.Append(",products.name as column1");
                    SQL_Groupby.Append("products.name,");
                    SQL_Orderby.Append("products.name,");
                }
                if (_reportcreteria.brand)
                {
                    SQL_Select.Append(",brand.name as column2");
                    SQL_Groupby.Append("brand.name,");
                    SQL_Orderby.Append("brand.name,");
                }
                if (_reportcreteria.material)
                {
                    SQL_Select.Append(",material.name as column3");
                    SQL_Groupby.Append("material.name,");
                    SQL_Orderby.Append("material.name,");
                }
                if (_reportcreteria.pattern)
                {
                    SQL_Select.Append(",pattern.name as column4");
                    SQL_Groupby.Append("pattern.name,");
                    SQL_Orderby.Append("pattern.name,");
                }
                if (_reportcreteria.style)
                {
                    SQL_Select.Append(",style.name as column5");
                    SQL_Groupby.Append("style.name,");
                    SQL_Orderby.Append("style.name,");
                }
                if (_reportcreteria.size)
                {
                    SQL_Select.Append(",size.name as column6");
                    SQL_Groupby.Append("size.name,");
                    SQL_Orderby.Append("size.name,");
                }
                if (_reportcreteria.design)
                {
                    SQL_Select.Append(",stock.designid as column7");
                    SQL_Groupby.Append("stock.designid,");
                    SQL_Orderby.Append("stock.designid,");
                }
                if (_reportcreteria.supplier)
                {
                    SQL_Select.Append(",stock.supplierid as column8");
                    SQL_Groupby.Append("stock.supplierid,");
                    SQL_Orderby.Append("stock.supplierid,");
                }
                if (_reportcreteria.section)
                {
                    SQL_Select.Append(",products.salescounterid as column9");
                    SQL_Groupby.Append("products.salescounterid,");
                    SQL_Orderby.Append("products.salescounterid,");
                }
                if (_reportcreteria.sourcesupplier)
                {
                    SQL_Select.Append(",lrentry.sourcesupplierid as column10");
                    SQL_Groupby.Append("lrentry.sourcesupplierid,");
                    SQL_Orderby.Append("lrentry.sourcesupplierid,");
                }
                if (_reportcreteria.isbarcode)
                {
                    SQL_Select.Append(",billitems.barcode as column11");
                    SQL_Groupby.Append("billitems.barcode,");
                    SQL_Orderby.Append("billitems.barcode,");
                }
                if (_reportcreteria.isgln)
                {
                    SQL_Select.Append(",stock.serialno as column12");
                    SQL_Groupby.Append("stock.serialno,");
                    SQL_Orderby.Append("stock.serialno,");
                }
                if (_reportcreteria.issuppliercity)
                {
                    SQL_Select.Append(",suppliercompany.cityid as column13");
                    SQL_Groupby.Append("suppliercompany.cityid,");
                    SQL_Orderby.Append("suppliercompany.cityid,");
                }
                if (_reportcreteria.agent)
                {
                    SQL_Select.Append(",lrentry.agentid as column14");
                    SQL_Groupby.Append("lrentry.agentid,");
                    SQL_Orderby.Append("lrentry.agentid,");
                }
                if (_reportcreteria.multicompany && _reportcreteria.companyid > 0)
                    SQL_Where.Append(" and bill.companyid=" + _reportcreteria.companyid);
                if (_reportcreteria.productid > 0)
                    SQL_Where.Append(" and items.productid=" + _reportcreteria.productid);
                if (_reportcreteria.brandid > 0)
                    SQL_Where.Append(" and items.brandid=" + _reportcreteria.brandid);
                if (_reportcreteria.materialid > 0)
                    SQL_Where.Append(" and items.materialid=" + _reportcreteria.materialid);
                if (_reportcreteria.patternid > 0)
                    SQL_Where.Append(" and items.patternid=" + _reportcreteria.patternid);
                if (_reportcreteria.styleid > 0)
                    SQL_Where.Append(" and items.styleid=" + _reportcreteria.styleid);
                if (_reportcreteria.sizeid > 0)
                    SQL_Where.Append(" and items.sizeid=" + _reportcreteria.sizeid);
                if (_reportcreteria.supplierid > 0)
                    SQL_Where.Append(" and supplier.id=" + _reportcreteria.supplierid);
                if (_reportcreteria.sourcesupplierid > 0)
                    SQL_Where.Append(" and lrentry.sourcesupplierid=" + _reportcreteria.sourcesupplierid);

                if (_reportcreteria.agentid > 0)
                    SQL_Where.Append(" and lrentry.agentid=" + _reportcreteria.agentid);
                if (_reportcreteria.suppliercityid > 0)
                    SQL_Where.Append(" and suppliercompany.cityid=" + _reportcreteria.suppliercityid);

                if (!string.IsNullOrEmpty(_reportcreteria.designid))
                {
                    if (_reportcreteria.designid.IndexOf(",") > 0)
                    {
                        string designquery = string.Join(" or ", _reportcreteria.designid.Split(',').ToList().ConvertAll(x => "stock.designid ilike '" + WebAPI.Data.Utility.SafeSQL(x) + "'"));
                        qb.Add2Query("(" + designquery + ")");
                    }
                    else
                    {
                        SQL_Where.Append(" and lower(stock.designid)='" + WebAPI.Data.Utility.SafeSQL(_reportcreteria.designid.ToLower()) + "'");
                    }
                }

                if (_reportcreteria.sectionid > 0)
                    SQL_Where.Append(" and products.salescounterid=" + _reportcreteria.sectionid);

                qb.CurrentQuery = SQL_Select.ToString() + SQL_From.ToString() + SQL_Where.ToString()
                    + SQL_Groupby.ToString(0, SQL_Groupby.Length - 1) + SQL_Orderby.ToString(0, SQL_Orderby.Length - 1);

                //command = qb.GetCommand(conn);
                command = GetCommand(qb.CurrentQuery, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = _reportcreteria.fromdate.Date;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = _reportcreteria.todate.AddDays(1).Date;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        StockReport oitem = new StockReport();

                        if (!_reportcreteria.product && !_reportcreteria.brand && !_reportcreteria.material && !_reportcreteria.pattern
                            && !_reportcreteria.style && !_reportcreteria.size && !_reportcreteria.supplier && !_reportcreteria.section && !_reportcreteria.sourcesupplier)
                            oitem.productname = reader["column1"] == DBNull.Value ? "" : reader["column1"].ToString();
                        if (_reportcreteria.product)
                            oitem.productname = reader["column1"] == DBNull.Value ? "" : reader["column1"].ToString();
                        if (_reportcreteria.brand)
                            oitem.brandname = reader["column2"] == DBNull.Value ? "" : reader["column2"].ToString();
                        if (_reportcreteria.material)
                            oitem.materialname = reader["column3"] == DBNull.Value ? "" : reader["column3"].ToString();
                        if (_reportcreteria.pattern)
                            oitem.patternname = reader["column4"] == DBNull.Value ? "" : reader["column4"].ToString();
                        if (_reportcreteria.style)
                            oitem.stylename = reader["column5"] == DBNull.Value ? "" : reader["column5"].ToString();
                        if (_reportcreteria.size)
                            oitem.sizename = reader["column6"] == DBNull.Value ? "" : reader["column6"].ToString();
                        if (_reportcreteria.design)
                            oitem.designid = reader["column7"] == DBNull.Value ? "" : reader["column7"].ToString();
                        if (_reportcreteria.supplier)
                            oitem.supplierid = reader["column8"] == DBNull.Value ? 0 : Convert.ToInt64(reader["column8"]);
                        if (_reportcreteria.section)
                            oitem.sectionid = reader["column9"] == DBNull.Value ? 0 : Convert.ToInt64(reader["column9"]);
                        if (_reportcreteria.sourcesupplier)
                            oitem.sourcesupplierid = reader["column10"] == DBNull.Value ? 0 : Convert.ToInt64(reader["column10"]);
                        if (_reportcreteria.isbarcode)
                            oitem.barcode = reader["column11"] == DBNull.Value ? "" : reader["column11"].ToString();
                        if (_reportcreteria.isgln)
                            oitem.glncode = reader["column12"] == DBNull.Value ? "" : reader["column12"].ToString();
                        if (_reportcreteria.issuppliercity)
                            oitem.suppliercityid = reader["column13"] == DBNull.Value ? 0 : Convert.ToInt64(reader["column13"]);
                        if (_reportcreteria.agent)
                            oitem.agentid = reader["column14"] == DBNull.Value ? 0 : Convert.ToInt64(reader["column14"]);

                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.taxvalue = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        oitem.price = reader["value"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["value"]);
                        oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        oitem.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                        oitem.schemediscount = reader["schemediscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["schemediscount"]);
                        oitem.stockvalue = reader["purchasevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["purchasevalue"]);
                        oitem.istockvalue = reader["ipurchasevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["ipurchasevalue"]);
                        if (oitem.schemediscount > 0)
                            oitem.discount = oitem.discount - oitem.schemediscount;
                        oitem.grosssalevalue = oitem.price + oitem.discount + oitem.addlndiscount + oitem.schemediscount;   // Gross Sale value which is including discount and tax
                        oitem.netsalevalue = oitem.price - oitem.taxvalue;     // Net Sale value which is GS-Discount-Tax
                        oitem.ibuyingprice = oitem.istockvalue - oitem.stockvalue; // useing this attribute to get the purchase tax 
                        if (_reportcreteria.exclusivetax)
                        {
                            if (oitem.netsalevalue > 0 && oitem.stockvalue > 0)
                            {
                                oitem.marginpercentage = Math.Round(((oitem.netsalevalue - oitem.stockvalue) / oitem.stockvalue) * 100, 2);
                                oitem.markdown = Math.Round(100 - ((oitem.stockvalue / oitem.netsalevalue) * 100), 2);
                            }
                        }
                        else
                        {
                            if (oitem.istockvalue > 0 && oitem.price > 0)
                            {
                                oitem.marginpercentage = Math.Round(((oitem.price - oitem.istockvalue) / oitem.istockvalue) * 100, 2);
                                oitem.markdown = Math.Round(100 - ((oitem.istockvalue / oitem.price) * 100), 2);
                            }
                        }

                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public void FindUANPriceMissmatch()
        {
            string query = @"with missmatchprice
as
(
select distinct serialno,salablegoods.price-salablegoods.discount from salablegoods
inner join stock on stock.id = salablegoods.stockid
	where serialno != ''
),missmatchuan
as
(
select serialno,count(*) from missmatchprice
	group by serialno having count(*)>1
)
	

--select * from missmatchprice
--where serialno in (select serialno from missmatchuan)


select  serialno,salablegoods.barcode,salablegoods.iqty,salablegoods.oqty,salablegoods.jqty,salablegoods.dqty,salablegoods.price,salablegoods.modifiedon,salablegoods.createdby,salablegoods.discount,
salablegoods.isactive,stock.invoiceitemid from salablegoods
inner join stock on stock.id = salablegoods.stockid
	where serialno = 'M138957'";
        }
        public string GetSQL4B2B(string locationfilter, string query)
        {
            if (!string.IsNullOrEmpty(locationfilter))
                query = query.Replace("and bill.isb2b=false", "and bill.isb2b=false " + locationfilter);

            if (InfyPOS.Services.ConfigManager.Instance(this.Context.OrganizationID).Config.system_isb2bapplication ||
                InfyPOS.Services.ConfigManager.Instance(this.Context.OrganizationID).Config.system_ismfgapplication)
                return query.Replace("and bill.isb2b=false", "").Replace("and bill.isb2b=@isb2b", "");
            return query;
        }
        public DashboardData SearchDashboardData(RetailReportCreteria _reportcreteria)
        {
            System.Diagnostics.Stopwatch stopwatch = new System.Diagnostics.Stopwatch();
            stopwatch.Start();
            const string SQL_Saledata = @"Select company.name, location.name as location, sum(receivable+rounding) billamount, sum(qty) billqty, count(bill.billno) as billcount
                            from bill inner join referencelist location on location.id = bill.locationid
                            inner join company on company.id = bill.companyid
                            where bill.isactive = true and bill.billdate>=@fromdate and bill.billdate<@todate
                            and bill.billtype != 9 and bill.isb2b=false
                            group by company.name, location.name 
                            order by company.name, location";

            const string SQL_SaleperHrs = @"Select sum(receivable+rounding) billamount, count(bill.billno) as billcount, date_part('hour', bill.billdate) billhrs
                            from bill inner join referencelist location on location.id = bill.locationid
                            where bill.isactive = true and bill.billdate>=@fromdate and bill.billdate<@todate
                            and bill.billtype != 9 and bill.isb2b=false
                            group by date_part('hour', bill.billdate)
                            order by date_part('hour', bill.billdate)";

            const string SQL_Unsettlebillcount = @"Select count(bill.billno) unsettlebillcount from bill where bill.isactive = true and bill.settled = false and billtype!=9 and bill.isb2b=false 
            and bill.billdate>=@fromdate and bill.billdate<@todate";

            const string SQL_Settlementdata = @"with billsettle as (select id, billsettlementmaster.receivable,billsettlementmaster.paidamount, billsettlementmaster.createdby,
                            paid_cash cash,paid_card,paid_upi,paid_credit,paid_voucher, case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'cash_return' as numeric) else 0 end cashreturn, 
                            case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'creditnote_refund' as numeric) else 0 end creditnoterefund, 
                            cast(paymentinfo->>'adjustment_paid' as numeric) adjustment_paid, cast(paymentinfo->>'discount_paid' as numeric) discount_paid, 
                            billsettlementmaster.locationid, billsettlementmaster.counterid,loan_paid from billsettlementmaster
                            where billsettlementmaster.isactive=true and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
                            {0})

                            select location.name as location, sum(cash) as cashpaid,sum(paid_card) card,sum(paid_upi) upi,sum(coalesce(loan_paid,0)) as loan_paid, sum(paid_credit) as paid_credit, 
                            sum(cashreturn) as cashreturn, sum(creditnoterefund) creditnoterefund, sum(paid_voucher) as paid_voucher, sum(adjustment_paid) as adjustment, sum(discount_paid) as discount from billsettle
                            inner join referencelist location on location.id = billsettle.locationid
                            group by location.name
                            order by location ";

            const string SQL_TopSalesman = @"Select employeecode, employee.name, section.name section, sum(billitems.qty) qty, sum(billitems.receivable) amount 
					from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
					left outer join employee on salesmanid = employee.id
					left outer join referencelist section on section.id = employee.sectionid
                    where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate 
                    and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                    group by employeecode, employee.name, section.name
                    order by amount desc
                    limit 6";

            const string SQL_TopSalesSection = @"Select section.name section, sum(billitems.qty) qty, sum(billitems.receivable) amount 
					from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
					inner join stock on stock.id = billitems.stockid
					inner join products on products.id = stock.productid
					left outer join referencelist section on section.id = products.salescounterid
                    where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate 
                    and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                    group by section.name
                    order by amount desc";

            const string SQL_TopSalesProductgroup = @"Select pgs.name productgroup, sum(billitems.qty) qty, sum(billitems.receivable) amount 
					from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
					inner join stock on stock.id = billitems.stockid
					inner join products on products.id = stock.productid
                    left outer join referencelist pgs on pgs.id = products.productgroup
                    where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate 
                    and case when @locationid=0 then bill.locationid != 0 else bill.locationid = @locationid end
                    group by pgs.name
                    order by amount desc";

            const string SQL_EmployeeAvailable = @"with totalemployee as
   (
   select employee.sectionid,count(*) total from employee
   where employee.isactive = true and(employee.hasleft = false or employee.relievingdate > @fromdate)
    group by employee.sectionid), availableemployee as

    (select employee.sectionid, count(*) absent from employee
    left outer join employeeinout on employeeinout.employeeid = employee.id and attendanceon = @fromdate
    left outer join employeeleave on employeeleave.isactive =true and employeeleave.employeeid = employee.id and (fromdate<= @fromdate and todate >= @fromdate)
    where employee.isactive = true and(employee.hasleft = false or employee.relievingdate > @fromdate)
    and (employeeleave.days>0 or (employeeinout.id is null))
    group by employee.sectionid
    )
    select referencelist.name,te.total,ae.absent from totalemployee te
    left outer join referencelist on referencelist.id = te.sectionid
    left outer join availableemployee ae on ae.sectionid = te.sectionid;

select referencelist.name section,employee.name absent from employee
    left outer join referencelist on referencelist.id = employee.sectionid
    left outer join employeeinout on employeeinout.employeeid= employee.id and attendanceon = @fromdate
    where employee.isactive = true and (employee.hasleft = false or employee.relievingdate>@fromdate) 
    and (employeeinout.id is null or employeeinout.morningabsent = true or employeeinout.afternoonabsent = true);";

            const string SQL_EmployeeAvailableOLD = @"
    with totalemployee as 
    (
    select referencelist.id,referencelist.name,count(*) total from employee
    left outer join referencelist on referencelist.id = employee.sectionid
    where employee.isactive = true and (employee.hasleft = false or employee.relievingdate>@fromdate) 
    group by referencelist.id,referencelist.name), availableemployee as 

    (select referencelist.id, referencelist.name,count(*) absent from employee
    left outer join referencelist on referencelist.id = employee.sectionid
    left outer join employeeinout on employeeinout.employeeid= employee.id and attendanceon = @fromdate
    where employee.isactive = true and (employee.hasleft = false or employee.relievingdate>@fromdate) 
    and (employeeinout.id is null or employeeinout.morningabsent = true or employeeinout.afternoonabsent = true)
    group by referencelist.id, referencelist.name
    )
    select te.name,te.total,ae.absent from totalemployee te
    left outer join availableemployee ae on ae.id = te.id;

    select referencelist.name section,employee.name absent from employee
    left outer join referencelist on referencelist.id = employee.sectionid
    left outer join employeeinout on employeeinout.employeeid= employee.id and attendanceon = @fromdate
    where employee.isactive = true and (employee.hasleft = false or employee.relievingdate>@fromdate) 
    and (employeeinout.id is null or employeeinout.morningabsent = true or employeeinout.afternoonabsent = true)";



            List<DashboardData.Sale> lstsale = new List<DashboardData.Sale>();
            List<DashboardData.Settlement> lstsettlement = new List<DashboardData.Settlement>();
            List<DashboardData.TopSaleItem> lstsalesperhrs = new List<DashboardData.TopSaleItem>();
            List<SalesmanReport> lstsalesman = new List<SalesmanReport>();
            List<SalesmanReport> lstsalesection = new List<SalesmanReport>();
            List<SalesmanReport> lstsalepgrp = new List<SalesmanReport>();
            List<DashboardData.EmployeeBySection> lstempsection = new List<DashboardData.EmployeeBySection>();

            long unsettlecount = 0;
            decimal taxlossonsales = 0;
            decimal taxlossonstock = 0;

            string locationfilter = "";
            string settlementlocationfilter = "";
            if (!Context.accessiblelocation.Exists(e => e == -1))
            {
                if (Context.accessiblelocation.Count == 1)
                {
                    locationfilter = " and bill.locationid = " + Context.accessiblelocation[0].ToString();
                    settlementlocationfilter = " and billsettlementmaster.locationid = " + Context.accessiblelocation[0].ToString();
                }
                if (Context.accessiblelocation.Count > 1)
                {
                    locationfilter = " and bill.locationid in (" + string.Join(",", Context.accessiblelocation) + ")";
                    settlementlocationfilter = " and billsettlementmaster.locationid in (" + string.Join(",", Context.accessiblelocation) + ")";
                }
            }
            if (!Context.accessiblecompany.Exists(e => e == -1))
            {
                if (Context.accessiblecompany.Count == 1)
                {
                    locationfilter = " and bill.companyid = " + Context.accessiblecompany[0].ToString();
                    settlementlocationfilter = " and billsettlementmaster.companyid = " + Context.accessiblecompany[0].ToString();
                }
                if (Context.accessiblecompany.Count > 1)
                {
                    locationfilter += " and bill.companyid in (" + string.Join(",", Context.accessiblecompany) + ")";
                    settlementlocationfilter += " and billsettlementmaster.companyid in (" + string.Join(",", Context.accessiblecompany) + ")";
                }
            }
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.Date.AddDays(1);
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                if (InfyPOS.Services.ConfigManager.Instance(Context.OrganizationID).Config.db_hidereturnbillvalue)
                {
                    command = GetCommand(GetSQL4B2B(locationfilter, SQL_Saledata.Replace("and bill.billtype != 9", "and bill.billtype != 9 and (bill.billtype != 8 or bill.settled=true)")), conn);
                }
                else
                {
                    command = GetCommand(GetSQL4B2B(locationfilter, SQL_Saledata), conn);
                }
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DashboardData.Sale oitem = new DashboardData.Sale();
                        oitem.company = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        //oitem.billtype = reader["billtype"] == DBNull.Value ? (int)InfyPOS.Models.Bill.BillTypes.Cash : Convert.ToInt32(reader["billtype"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.billcount = reader["billcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["billcount"]);
                        oitem.billvalue = reader["billamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billamount"]);
                        oitem.billqty = reader["billqty"] == DBNull.Value ? 0 : Convert.ToInt64(reader["billqty"]);
                        if (oitem.billvalue > 0 && oitem.billcount > 0)
                            oitem.avgbillvalue = Math.Round(oitem.billvalue / oitem.billcount, 2);
                        lstsale.Add(oitem);
                    }
                }

                command = GetCommand(GetSQL4B2B(locationfilter, SQL_SaleperHrs), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DashboardData.TopSaleItem oitem = new DashboardData.TopSaleItem();
                        int hour = reader["billhrs"] == DBNull.Value ? 0 : Convert.ToInt32(reader["billhrs"]);
                        oitem.name = string.Format("{0}{1}", hour, hour >= 12 ? "PM" : "AM");
                        oitem.qty = reader["billcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["billcount"]);
                        oitem.value = reader["billamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billamount"]);
                        lstsalesperhrs.Add(oitem);
                    }
                }

                command = GetCommand(string.Format(SQL_Settlementdata, settlementlocationfilter), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DashboardData.Settlement oitem = new DashboardData.Settlement();
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.cash = reader["cashpaid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashpaid"]);
                        oitem.card = reader["card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["card"]);
                        oitem.upi = reader["upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["upi"]);
                        oitem.loan = reader["loan_paid"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["loan_paid"]);
                        oitem.credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                        oitem.adjustment = reader["adjustment"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["adjustment"]);
                        oitem.cashreturn = reader["cashreturn"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cashreturn"]);
                        oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        oitem.voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);
                        oitem.creditnote = reader["creditnoterefund"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["creditnoterefund"]);
                        lstsettlement.Add(oitem);
                    }
                }
                command = GetCommand(GetSQL4B2B(locationfilter, SQL_TopSalesman), conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = 0;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReport oitem = new SalesmanReport();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        oitem.section = reader["section"] == DBNull.Value ? "" : reader["section"].ToString();
                        oitem.employeecode = reader["employeecode"] == DBNull.Value ? "" : reader["employeecode"].ToString();
                        oitem.employeename = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        lstsalesman.Add(oitem);
                    }
                }
                command = GetCommand(GetSQL4B2B(locationfilter, SQL_TopSalesSection), conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = 0;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReport oitem = new SalesmanReport();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        oitem.section = reader["section"] == DBNull.Value ? "" : reader["section"].ToString();
                        lstsalesection.Add(oitem);
                    }
                }

                command = GetCommand(GetSQL4B2B(locationfilter, SQL_TopSalesProductgroup), conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = 0;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesmanReport oitem = new SalesmanReport();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        oitem.section = reader["productgroup"] == DBNull.Value ? "" : reader["productgroup"].ToString();
                        lstsalepgrp.Add(oitem);
                    }
                }
                command = GetCommand(GetSQL4B2B(locationfilter, SQL_Unsettlebillcount), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        unsettlecount = reader["unsettlebillcount"] == DBNull.Value ? 0 : Convert.ToInt64(reader["unsettlebillcount"]);
                    }
                }

                locationfilter = "";
                if (!Context.accessiblelocation.Exists(e => e == -1))
                {
                    if (Context.accessiblelocation.Count == 1)
                        locationfilter = " and employee.locationid = " + Context.accessiblelocation[0].ToString();
                    if (Context.accessiblelocation.Count > 1)
                        locationfilter = " and employee.locationid in (" + string.Join(",", Context.accessiblelocation) + ")";
                }

                locationfilter = "";
                if (!Context.accessiblecompany.Exists(e => e == -1))
                {
                    if (Context.accessiblecompany.Count == 1)
                        locationfilter = " and employee.companyid = " + Context.accessiblecompany[0].ToString();
                    if (Context.accessiblecompany.Count > 1)
                        locationfilter = " and employee.companyid in (" + string.Join(",", Context.accessiblecompany) + ")";
                }

                var newquery = SQL_EmployeeAvailable;
                if (DateTimeNow.Date == today.Date)
                {
                    if (DateTimeNow.TimeOfDay.Hours > 14)
                    {
                        newquery = SQL_EmployeeAvailable.Replace("(employeeinout.id is null or employeeinout.morningabsent = true or employeeinout.afternoonabsent = true)",
                                    "(employeeinout.id is null) or employeeinout.afternoonabsent = true");
                    }
                    else
                    {
                        newquery = SQL_EmployeeAvailable.Replace("(employeeinout.id is null or employeeinout.morningabsent = true or employeeinout.afternoonabsent = true)",
                                    "(employeeinout.id is null) or employeeinout.morningabsent = true");
                    }
                }

                if (!string.IsNullOrEmpty(locationfilter))
                {
                    newquery = newquery.Replace("employee.isactive = true", "employee.isactive = true " + locationfilter);
                }

                command = GetCommand(newquery, conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DashboardData.EmployeeBySection oitem = new DashboardData.EmployeeBySection();
                        oitem.section = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        oitem.total = reader["total"] == DBNull.Value ? 0 : Convert.ToInt32(reader["total"]);
                        oitem.absent = reader["absent"] == DBNull.Value ? 0 : Convert.ToInt32(reader["absent"]);
                        lstempsection.Add(oitem);
                    }

                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {

                            var section = reader["section"] == DBNull.Value ? "" : reader["section"].ToString();
                            var employeename = reader["absent"] == DBNull.Value ? "" : reader["absent"].ToString();
                            if (lstempsection.Exists(e => e.section == section))
                                lstempsection.Find(e => e.section == section).absentemployees.Add(employeename);
                        }
                    }
                }

                //command = GetCommand(SQL_Stockvalue, conn);
                //using (System.Data.IDataReader reader = command.ExecuteReader())
                //{
                //    while (reader.Read())
                //    {
                //        stockvalue = reader["stockvalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockvalue"]);
                //    }
                //}


                command = GetCommand(GetSQL4B2B(locationfilter.Replace("employee.", "bill."), SQL_Unsettlebillcount), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        unsettlecount = reader["unsettlebillcount"] == DBNull.Value ? 0 : Convert.ToInt64(reader["unsettlebillcount"]);
                    }
                }

                if (string.IsNullOrEmpty(Context.Platform) || Context.Platform.ToLower() == "web")
                {
                    command = GetCommand(@"with salesloss
                as
                (
                select bill.billdate,billitems.barcode,billitems.receivable/billitems.qty rate,billitems.qty from bill
                inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                inner join products on products.id = billitems.productid
                inner join tax on tax.id=products.salestaxid and tax.type=2
                where bill.isactive=true and billtype != 9 and billdate>=@fromdate and billdate<@todate 
                and (billitems.receivable)/billitems.qty>2625 and 
                (
                    billitems.receivable)/billitems.qty<2950 and billitems.qty>0
                    and billitems.sellingmode!=3 
                    and billitems.taxpercentage = 18
                )
                select sum(round(2500-(rate/118*100),2)*qty) lossvalue from salesloss", conn);
                    command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                    command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            taxlossonsales = reader["lossvalue"] == DBNull.Value ? 0 : Convert.ToInt64(reader["lossvalue"]);
                        }
                    }
                    command = GetCommand(@"select 
                sum(round(998-((salablegoods.price-salablegoods.discount)/118*100),2)*iqty-(oqty+jqty+dqty) ) lossvalue from stock 
                inner join salablegoods  on salablegoods.stockid = stock.id
                inner join products on products.id = stock.productid
			    inner join tax on tax.id=products.salestaxid and tax.type=2
                where (salablegoods.price-salablegoods.discount)>2625 
                and (salablegoods.price-salablegoods.discount)<2950 and stock.isactive=true
                and salablegoods.hasstock=true and salablegoods.isactive=true  and iqty-(oqty+jqty+dqty)>0 ", conn);
                    command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                    command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            taxlossonstock = reader["lossvalue"] == DBNull.Value ? 0 : Convert.ToInt64(reader["lossvalue"]);
                        }
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }


            var dashboard = new DashboardData()
            {
                unsettlebillcount = unsettlecount,
                lstsale = lstsale,
                taxlossonsales = taxlossonsales,
                taxlossonstock = taxlossonstock,
                lstsettlement = lstsettlement,
                lstsalesection = lstsalesection.OrderByDescending(e => e.amount).ToList(),
                lstsalesman = lstsalesman.OrderByDescending(e => e.amount).ToList(),
                lstproduct = lstsalesperhrs,
                lststockvalue = SearchStockValue(_reportcreteria),
                lstempsection = lstempsection,
                lstsalepgrp = lstsalepgrp.OrderByDescending(e => e.amount).ToList()
            };
            stopwatch.Stop();
            dashboard.timetaken = stopwatch.ElapsedMilliseconds;
            stopwatch.Reset();
            dashboard.totalstock = dashboard.lststockvalue.Sum(e => e.stockvalue);
            dashboard.totalsalevalue = dashboard.lststockvalue.Sum(e => e.salevalue);
            if (!_reportcreteria.hidebusinesstrend)
            {
                stopwatch.Start();
                dashboard.lrstockvssales = GetDashboard_StockVsSales(dashboard.lststockvalue.Sum(e => e.stockvalue), DateTimeNow.Date.AddDays(-15));
                stopwatch.Stop();
                dashboard.timetakensvs = stopwatch.ElapsedMilliseconds;
            }

            stopwatch.Reset();
            stopwatch.Start();
            dashboard.additionaldashboard = SearchAdditionalDiscount(_reportcreteria);
            dashboard.additionaldashboard.lstlrvalue = SearchLRStatus(_reportcreteria);
            EmployeesalaryDataService employeeDataService = new EmployeesalaryDataService() { Context = this.Context };
            dashboard.hrdashboard = employeeDataService.Dashboard(new EmployeesalaryDataService.HRReportCreteria()
            {
                fromdate = _reportcreteria.fromdate,
                todate = _reportcreteria.todate
            });
            stopwatch.Stop();
            dashboard.timetakenadd = stopwatch.ElapsedMilliseconds;
            CustomerwalkinsDataService customerwalkinsDataService = new CustomerwalkinsDataService() { Context = this.Context };
            dashboard.totalwalkin = customerwalkinsDataService.GetWalkinCount(today);

            if (Context.HasPermission(PermissionSet.hidedbstock, InfyPOS.Common.Action.View))
            {
                dashboard.removestockvalues();
            }
            return dashboard;
        }

        public AdditionalDashboardData SearchAdditionalDiscount(RetailReportCreteria _reportcreteria)
        {

            const string SQL_AddDiscountBillingWise = @"Select location.name as location, counter.name as counter, employee.name employeename, sum(additionaldiscount) as additionaldiscount
                                                from bill inner join referencelist location on location.id = bill.locationid
                                                inner join referencelist counter on counter.id = bill.counterid
                                                inner join users on users.id = bill.createdby
                                                left outer join employee on employeeid = employee.id
                                                where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate
                                                and case when @locationid=0 then bill.locationid <> 0 else bill.locationid=@locationid end
                                                and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
                                                and additionaldiscount>0
                                                group by location.name, counter.name, employee.name
                                                order by location, counter";

            const string SQL_AddDiscountSettlementWise = @"select location.name as location, counter.name as counter, employee.name employeename, sum(paid_discount) as additionaldiscount
                                                from billsettlementmaster inner join referencelist location on location.id = locationid
                                                inner join referencelist counter on counter.id = counterid
                                                left outer join users on users.id = billsettlementmaster.createdby
                                                left outer join employee on employeeid = employee.id
                                                where billsettlementmaster.isactive=true and settlementon>=@fromdate and settlementon<@todate
                                                and case when @locationid=0 then billsettlementmaster.locationid <> 0 else billsettlementmaster.locationid=@locationid end
                                                and case when @companyid=0 then billsettlementmaster.companyid >= 0 else billsettlementmaster.companyid = @companyid end
                                                and paid_discount>0
                                                group by location.name, counter.name, employee.name
                                                order by location, counter";


            List<AdditionalDashboardData.TotalDiscount> lstbillingwisediscount = new List<AdditionalDashboardData.TotalDiscount>();
            List<AdditionalDashboardData.TotalDiscount> lstsettlementwisediscount = new List<AdditionalDashboardData.TotalDiscount>();

            string locationfilter = "";
            if (!Context.accessiblelocation.Exists(e => e == -1))
            {
                if (Context.accessiblelocation.Count == 1)
                    locationfilter = " and bill.locationid = " + Context.accessiblelocation[0].ToString();
                if (Context.accessiblelocation.Count > 1)
                    locationfilter = " and bill.locationid in (" + string.Join(",", Context.accessiblelocation) + ")";
            }
            if (!Context.accessiblecompany.Exists(e => e == -1))
            {
                if (Context.accessiblecompany.Count == 1)
                    locationfilter = " and bill.companyid = " + Context.accessiblecompany[0].ToString();
                if (Context.accessiblecompany.Count > 1)
                    locationfilter = " and bill.companyid in (" + string.Join(",", Context.accessiblecompany) + ")";
            }

            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.Date.AddDays(1);
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(GetSQL4B2B(locationfilter, SQL_AddDiscountBillingWise), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        AdditionalDashboardData.TotalDiscount oitem = new AdditionalDashboardData.TotalDiscount();
                        oitem.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        oitem.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.additionaldiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["additionaldiscount"]);
                        lstbillingwisediscount.Add(oitem);
                    }
                }

                command = GetCommand(GetSQL4B2B(locationfilter, SQL_AddDiscountSettlementWise), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        AdditionalDashboardData.TotalDiscount oitem = new AdditionalDashboardData.TotalDiscount();
                        oitem.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        oitem.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.additionaldiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["additionaldiscount"]);
                        lstsettlementwisediscount.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            var dashboard = new AdditionalDashboardData()
            {
                lstbillwisediscount = lstbillingwisediscount,
                lstsettlementwisediscount = lstsettlementwisediscount,
            };
            return dashboard;
        }

        public List<AdditionalDashboardData.LRtotal> SearchLRStatus(RetailReportCreteria _reportcreteria)
        {
            if (Context.HasPermission(PermissionSet.warehouselocation, InfyPOS.Common.Action.View))
                return new List<AdditionalDashboardData.LRtotal>();

            const string SQL_LR = @"select statusid, 
                                    sum(case when lrentry.lrentrydate>=@fromdate and lrentry.lrentrydate<@todate then 1 else 0 end) as todaycount,
                                    count(*) as totalcount
                                    from lrentry 
                                    inner join inbox on inbox.referenceid=lrentry.id and typeid=1
                                    where lrentry.lrentrydate>=@startofyear and statusid>=200 {0}
                                    group by statusid;
									
                                    select sum(case when lrentry.lrentrydate>=@fromdate and lrentry.lrentrydate<@todate then 1 else 0 end) as todaycount,
                                    count(*) as totalcount
                                    from lrentry 
                                    inner join inbox on inbox.referenceid=lrentry.id and typeid=1
                                    where lrentry.lrentrydate>=@startofyear and statusid=2 {0};";

            List<AdditionalDashboardData.LRtotal> lstlr = new List<AdditionalDashboardData.LRtotal>();

            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.Date.AddDays(1);
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                var query = SQL_LR;
                string locationfilter = "";
                if (!Context.accessiblelocation.Exists(e => e == -1))
                {
                    if (Context.accessiblelocation.Count == 1)
                    {
                        locationfilter = " and lrentry.entrylocationid = " + Context.accessiblelocation[0].ToString();
                    }
                    if (Context.accessiblelocation.Count > 1)
                    {
                        locationfilter = " and lrentry.entrylocationid in (" + string.Join(",", Context.accessiblelocation) + ")";
                    }
                }
                if (!Context.accessiblecompany.Exists(e => e == -1))
                {
                    if (Context.accessiblecompany.Count == 1)
                    {
                        locationfilter = " and lrentry.lrcompanyid = " + Context.accessiblecompany[0].ToString();
                    }
                    if (Context.accessiblecompany.Count > 1)
                    {
                        locationfilter += " and lrentry.lrcompanyid in (" + string.Join(",", Context.accessiblecompany) + ")";
                    }
                }

                NpgsqlCommand command = null;
                command = GetCommand(string.Format(SQL_LR, locationfilter), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("startofyear", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = new DateTime(today.Year, today.Month, 1);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        AdditionalDashboardData.LRtotal oitem = new AdditionalDashboardData.LRtotal();
                        oitem.status = reader["statusid"] == DBNull.Value ? 0 : Convert.ToInt32(reader["statusid"]);
                        oitem.statusname = ((Inbox.StatusList)oitem.status).ToString();
                        oitem.todaycount = reader["todaycount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["todaycount"]);
                        oitem.totalcount = reader["totalcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["totalcount"]);
                        lstlr.Add(oitem);
                    }
                    if (reader.NextResult() && reader.Read())
                    {
                        AdditionalDashboardData.LRtotal oitem = new AdditionalDashboardData.LRtotal();
                        oitem.status = 2;
                        oitem.statusname = ((Inbox.StatusList)oitem.status).ToString();
                        oitem.todaycount = reader["todaycount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["todaycount"]);
                        oitem.totalcount = reader["totalcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["totalcount"]);
                        lstlr.Add(oitem);
                    }
                }

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lstlr;
        }
        public AdditionalDashboardData SearchAdditionalDashboard(RetailReportCreteria _reportcreteria)
        {
            const string SQL_SalePerDay = @"Select bill.companyid,location.name as location,billitems.printingname, sum(billitems.receivable::numeric) as receivetotal, sum(billitems.qty::numeric) as qtytotal,
                                            sum(billitems.discount+(billitems.additionaldiscount::numeric * billitems.qty::numeric)) totaldiscount, sum(billitems.schemediscount) schemediscount, sum(billitems.additionaldiscount::numeric * billitems.qty::numeric) additionaldiscount 
                                            from  bill inner join referencelist location on location.id = bill.locationid
                                            inner join billitems on billitems.billid = bill.id  and billitems.isactive=true
                                            where bill.isactive = true and billtype!=9 and bill.isb2b=false and bill.billdate>=@fromdate and bill.billdate<@todate
                                            and case when @locationid=0 then bill.locationid <> 0 else bill.locationid=@locationid end
                                            and case when @companyid=0 then bill.companyid >= 0 else bill.companyid=@companyid end
                                            group by bill.companyid,location.name, billitems.printingname 
                                            order by bill.companyid,location";


            const string SQL_LR = @"select statusid, 
                                    sum(case when inbox.createdon>=@fromdate and inbox.createdon<@todate then 1 else 0 end) as todaycount,
                                    count(*) as totalcount
                                    from lrentry 
                                    inner join inbox on inbox.referenceid=lrentry.id and typeid=1
                                    where inbox.createdon>=@startofyear and statusid>=200
                                    group by statusid;
									
                                    select sum(case when inbox.createdon>=@fromdate and inbox.createdon<@todate then 1 else 0 end) as todaycount,
                                    count(*) as totalcount
                                    from lrentry 
                                    inner join inbox on inbox.referenceid=lrentry.id and typeid=1
                                    where inbox.createdon>=@startofyear and statusid=2;";

            List<AdditionalDashboardData.SaleValue> lstsaleperday = new List<AdditionalDashboardData.SaleValue>();
            List<AdditionalDashboardData.TotalDiscount> lstbillingwisediscount = new List<AdditionalDashboardData.TotalDiscount>();
            List<AdditionalDashboardData.TotalDiscount> lstsettlementwisediscount = new List<AdditionalDashboardData.TotalDiscount>();
            List<AdditionalDashboardData.SalesReturn> lstsalesreturn = new List<AdditionalDashboardData.SalesReturn>();
            List<AdditionalDashboardData.Unsettlementtotal> lstunsettledbill = new List<AdditionalDashboardData.Unsettlementtotal>();
            List<AdditionalDashboardData.LRtotal> lstlr = new List<AdditionalDashboardData.LRtotal>();

            decimal stockvalue = 0;
            string locationfilter = "";
            if (!Context.accessiblelocation.Exists(e => e == -1))
            {
                if (Context.accessiblelocation.Count == 1)
                    locationfilter = " and bill.locationid = " + Context.accessiblelocation[0].ToString();
                if (Context.accessiblelocation.Count > 1)
                    locationfilter = " and bill.locationid in (" + string.Join(",", Context.accessiblelocation) + ")";
            }

            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.Date.AddDays(1);
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(GetSQL4B2B(locationfilter, SQL_SalePerDay), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        AdditionalDashboardData.SaleValue oitem = new AdditionalDashboardData.SaleValue();
                        oitem.printingname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                        oitem.qtytotal = reader["qtytotal"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qtytotal"]);
                        oitem.receivetotal = reader["receivetotal"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivetotal"]);
                        oitem.discount = reader["totaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["totaldiscount"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        oitem.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"].ToString());
                        lstsaleperday.Add(oitem);
                    }
                }
                command = GetCommand(SQL_LR, conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("startofyear", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = new DateTime(today.Year, today.Month, 1);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        AdditionalDashboardData.LRtotal oitem = new AdditionalDashboardData.LRtotal();
                        oitem.status = reader["statusid"] == DBNull.Value ? 0 : Convert.ToInt32(reader["statusid"]);
                        oitem.statusname = ((Inbox.StatusList)oitem.status).ToString();
                        oitem.todaycount = reader["todaycount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["todaycount"]);
                        oitem.totalcount = reader["totalcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["totalcount"]);
                        lstlr.Add(oitem);
                    }
                    if (reader.NextResult() && reader.Read())
                    {
                        AdditionalDashboardData.LRtotal oitem = new AdditionalDashboardData.LRtotal();
                        oitem.status = 2;
                        oitem.statusname = ((Inbox.StatusList)oitem.status).ToString();
                        oitem.todaycount = reader["todaycount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["todaycount"]);
                        oitem.totalcount = reader["totalcount"] == DBNull.Value ? 0 : Convert.ToInt32(reader["totalcount"]);
                        lstlr.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            var dashboard = new AdditionalDashboardData()
            {
                stockvalue = stockvalue,
                lstsalevalue = lstsaleperday,
                lstbillwisediscount = lstbillingwisediscount,
                lstsettlementwisediscount = lstsettlementwisediscount,
                lstsalesreturn = lstsalesreturn,
                lstunsettled = lstunsettledbill,
                lstlrvalue = lstlr
            };

            if (Context.HasPermission(PermissionSet.hidedbstock, InfyPOS.Common.Action.View))
                dashboard.removestockvalues();
            return dashboard;
        }

