                        {
                            obill.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                            obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            obill.returnbillno = reader["returnbillno"] == DBNull.Value ? "" : reader["returnbillno"].ToString();
                            obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.billtype = reader["billtype"] == DBNull.Value ? Bill.BillTypes.Bulk : (Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                            obill.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                            obill.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                            obill.approvedby = reader["approvedbyname"] == DBNull.Value ? "" : reader["approvedbyname"].ToString();
                            obill.customer = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            obill.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();

                        }
                        else
                        {
                            obill.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                            obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                            obill.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                            obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                            obill.returnbillno = reader["returnbillno"] == DBNull.Value ? "" : reader["returnbillno"].ToString();

                            obill.customer = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                            obill.mobileno = reader["mobileno"] == DBNull.Value ? "" : reader["mobileno"].ToString();
                            obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                            obill.billtype = reader["billtype"] == DBNull.Value ? InfyPOS.Models.Bill.BillTypes.Cash : (InfyPOS.Models.Bill.BillTypes)Convert.ToInt32(reader["billtype"]);
                            obill.employeename = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                            obill.approvedby = reader["approvedbyname"] == DBNull.Value ? "" : reader["approvedbyname"].ToString();
                            obill.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                            obill.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                            obill.billedqty = reader["billedqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["billedqty"]);
                            obill.journalqty = reader["journalqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["journalqty"]);

                            obill.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                            obill.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                            obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                            obill.taxable = Math.Round(obill.amount - obill.saletax, 2);

                            obill.rate = reader["total"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["total"]);
                            obill.itemname = reader["printingname"] == DBNull.Value ? "" : reader["printingname"].ToString();
                            obill.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                            obill.productid = reader["productid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["productid"]);
                            obill.productname = reader["productname"] == DBNull.Value ? "" : reader["productname"].ToString();
                            obill.brandid = reader["brandid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["brandid"]);
                            obill.brandname = reader["brandname"] == DBNull.Value ? "" : reader["brandname"].ToString();
                            obill.patternid = reader["patternid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["patternid"]);
                            obill.patternname = reader["patternname"] == DBNull.Value ? "" : reader["patternname"].ToString();
                            obill.styleid = reader["styleid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["styleid"]);
                            obill.stylename = reader["stylename"] == DBNull.Value ? "" : reader["stylename"].ToString();
                            obill.sizeid = reader["sizeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["sizeid"]);
                            obill.sizename = reader["sizename"] == DBNull.Value ? "" : reader["sizename"].ToString();
                            obill.materialid = reader["materialid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["materialid"]);
                            obill.materialname = reader["materialname"] == DBNull.Value ? "" : reader["materialname"].ToString();
                            obill.typeid = reader["typeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["typeid"]);
                            obill.typename = reader["typename"] == DBNull.Value ? "" : reader["typename"].ToString();
                            obill.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                            obill.suppliername = reader["suppliername"] == DBNull.Value ? "" : reader["suppliername"].ToString();
                            obill.employeecode = reader["imageid"] == DBNull.Value ? "" : reader["imageid"].ToString();
                            obill.sectionname = reader["sectionname"] == DBNull.Value ? "" : reader["sectionname"].ToString();
                            if (obill.returnbillno.StartsWith("~"))
                            {
                                obill.returnbillno = "";
                                obill.balanceqty = obill.saleqty - (obill.billedqty + obill.journalqty);
                            }
                            else if (!string.IsNullOrEmpty(obill.returnbillno) && obill.returnbillno == _reportcreteria.billno)
                            {
                                obill.returnbillno = obill.billno.Substring(1);
                                obill.billno = "";
                                if (obill.saleqty < 0)
                                {
                                    obill.journalqty += (obill.saleqty * -1);
                                    obill.billtype = Bill.BillTypes.BulkSaleReturn;
                                    obill.saleqty = 0;
                                }

                                if (obill.journalqty > 0 && obill.billedqty > 0)
                                {
                                    obill.billtype = Bill.BillTypes.BulkSaleBilledWithReturns;
                                }
                                else if (obill.journalqty > 0)
                                {
                                    obill.billtype = Bill.BillTypes.BulkSaleReturn;
                                }
                                else if (obill.billedqty > 0)
                                {
                                    obill.billtype = Bill.BillTypes.BulkSaleBilled;
                                }
                            }
                            else if (obill.billno.StartsWith("~") && !string.IsNullOrEmpty(obill.returnbillno))
                            {
                                var str = obill.returnbillno;
                                obill.returnbillno = obill.billno.Substring(1);
                                obill.billno = str;
                            }
                        }
                        lst.Add(obill);
                    }
                }

                if (lst.Count > 0 && !_reportcreteria.showdetail)
                {
                    using (var reader = ExecuteReader(@"select billid,sum(billedqty) billedqty,sum(journalqty) journalqty,sum(qty) qty from bulkbillitems
                                where billid in (" + string.Join(",", lst.ConvertAll(e => e.id)) + ") group by billid", new SortedList<string, object>()))
                    {
                        while (reader.Read())
                        {
                            long id = reader.GetInt64(0);
                            decimal billedqty = reader.GetDecimal(1);
                            decimal journalqty = reader.GetDecimal(2);
                            decimal qty = reader.GetDecimal(3);
                            var obill = lst.Find(e => e.id == id);

                            obill.saleqty = qty;
                            obill.journalqty = journalqty;
                            obill.billedqty = billedqty;

                            if (obill.returnbillno == "" || obill.returnbillno.StartsWith("~"))
                            {
                                obill.returnbillno = "";
                                obill.balanceqty = obill.saleqty - (obill.billedqty + obill.journalqty);
                            }
                            else
                            {
                                var abillno = obill.returnbillno;
                                if (obill.billno.IndexOf("~") == 0)
                                    obill.returnbillno = obill.billno.Substring(1);
                                else
                                    obill.returnbillno = obill.billno;
                                obill.billno = abillno;
                                if (obill.saleqty < 0)
                                {
                                    obill.journalqty += (obill.saleqty * -1);
                                    obill.billtype = Bill.BillTypes.BulkSaleReturn;
                                    obill.saleqty = 0;
                                }

                                if (obill.journalqty > 0 && obill.billedqty > 0)
                                {
                                    obill.billtype = Bill.BillTypes.BulkSaleBilledWithReturns;
                                }
                                else if (obill.journalqty > 0)
                                {
                                    obill.billtype = Bill.BillTypes.BulkSaleReturn;
                                }
                                else if (obill.billedqty > 0)
                                {
                                    obill.billtype = Bill.BillTypes.BulkSaleBilled;
                                }
                            }
                        }
                    }
                }

                if (_reportcreteria.unsettled && lst.Count > 0 && !_reportcreteria.showdetail)
                    lst.RemoveAll(e => e.balanceqty == 0);

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public List<DeliveryReport> SearchDelivery(SaleRetailCreteria _reportcreteria)
        {
            const string SQL_DeliveryReport = @"Select bill.id, location.name as location, counter.name as counter, employee.name employeename, 
                                    bill.billno, billdate, bill.qty, (receivable+rounding) receivable,
                                    status,receivedby,receivedon,deliveredby,deliveredon,validatedby,deliverycounter.name as deliverycounter
                                    from bill inner join referencelist location on location.id = bill.locationid
                                    left outer join delivery on delivery.billid = bill.id
                                    left outer join referencelist counter on counter.id = bill.counterid
                                    left outer join referencelist deliverycounter on deliverycounter.id = delivery.counterid
                                    left outer join users on users.id = bill.createdby
                                    left outer join employee on employeeid = employee.id 
                                    where bill.isactive = true and billtype!=9 and bill.billdate>=@fromdate and bill.billdate<@todate 
                                    and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
                                    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end 
                                    order by bill.id";

            const string SQL_Employeedet = @"select users.id, employee.name from users left outer join employee on employeeid = employee.id";

            List<DeliveryReport> lst = new List<DeliveryReport>();
            SortedDictionary<long, string> employeename = new SortedDictionary<long, string>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(SQL_DeliveryReport, conn);

                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DeliveryReport obill = new DeliveryReport();
                        obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        obill.billdate = reader["billdate"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["billdate"]);
                        obill.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        obill.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        obill.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        obill.deliverycounter = reader["deliverycounter"] == DBNull.Value ? "" : reader["deliverycounter"].ToString();
                        obill.billedby = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        obill.receivedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        obill.receivedbyid = reader["receivedby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["receivedby"]);
                        obill.verifiedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        obill.verifiedbyid = reader["validatedby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["validatedby"]);
                        obill.deliveredon = reader["deliveredon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["deliveredon"]);
                        obill.deliveredbyid = reader["deliveredby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["deliveredby"]);
                        obill.status = reader["status"] == DBNull.Value ? -9 : Convert.ToInt32(reader["status"]);
                        lst.Add(obill);
                    }
                }
                if (lst.Count > 0)
                {
                    command = GetCommand(SQL_Employeedet, conn);
                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            var id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                            var name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                            employeename.Add(id, name);
                        }
                    }
                    foreach (var item in lst)
                    {
                        item.receivedby = employeename.ContainsKey(item.receivedbyid) ? employeename[item.receivedbyid] : "";
                        item.verifiedby = employeename.ContainsKey(item.verifiedbyid) ? employeename[item.verifiedbyid] : "";
                        item.deliveredby = employeename.ContainsKey(item.deliveredbyid) ? employeename[item.deliveredbyid] : "";
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

