where isalteration = true and delivery.isactive = true and delivery.receivedon>=@fromdate and delivery.receivedon<@todate 
and case when @locationid=0 then delivery.locationid <> 0 else delivery.locationid = @locationid end
order by delivery.id";

            const string SQL_Employeedet = @"select users.id, employee.name from users left outer join employee on employeeid = employee.id";

            List<DeliveryReport> lst = new List<DeliveryReport>();
            SortedDictionary<long, string> employeename = new SortedDictionary<long, string>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(SQL_AlterationReport, conn);

                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DeliveryReport obill = new DeliveryReport();
                        obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        obill.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        obill.customername = reader["customername"] == DBNull.Value ? "" : reader["customername"].ToString();
                        obill.mobileno = reader["contactno"] == DBNull.Value ? "" : reader["contactno"].ToString();
                        obill.deliverycounter = reader["deliverycounter"] == DBNull.Value ? "" : reader["deliverycounter"].ToString();
                        obill.receivedby = reader["employeename"] == DBNull.Value ? "" : reader["employeename"].ToString();
                        obill.receivedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        obill.receivedbyid = reader["receivedby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["receivedby"]);
                        //obill.verifiedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        obill.verifiedbyid = reader["validatedby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["validatedby"]);
                        obill.deliveredon = reader["deliveredon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["deliveredon"]);
                        obill.deliveredbyid = reader["deliveredby"] == DBNull.Value ? 0 : Convert.ToInt64(reader["deliveredby"]);
                        obill.status = reader["status"] == DBNull.Value ? -9 : Convert.ToInt32(reader["status"]);
                        if (obill.status == 0) obill.statusstring = "RECEIVED";
                        else if (obill.status == 1) obill.statusstring = "READY";
                        else if (obill.status == 2) obill.statusstring = "DELIVERED";
                        lst.Add(obill);
                    }
                }
                if (lst.Count > 0)
                {
                    command = GetCommand(SQL_Employeedet, conn);
                    using (System.Data.IDataReader reader = command.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            var id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                            var name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                            employeename.Add(id, name);
                        }
                    }
                    foreach (var item in lst)
                    {
                        item.receivedby = employeename.ContainsKey(item.receivedbyid) ? employeename[item.receivedbyid] : "";
                        item.verifiedby = employeename.ContainsKey(item.verifiedbyid) ? employeename[item.verifiedbyid] : "";
                        item.deliveredby = employeename.ContainsKey(item.deliveredbyid) ? employeename[item.deliveredbyid] : "";
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        public List<DeliveryReport> SearchDeliveryStatus(SaleRetailCreteria _reportcreteria)
        {
            const string SQL_Received = @"Select delivery.id, location.name as location, employee.name receivedby, billno, receivedon, amount, qty, status
                            from delivery inner join referencelist location on location.id = delivery.locationid
                            inner join users on users.id = delivery.receivedby
                            left outer join employee on employeeid = employee.id 
                            where status = 0";

            const string SQL_Delivered = @"Select delivery.id, location.name as location, employee.name deliveredby, billno, deliveredon, amount, qty, status
                            from delivery inner join referencelist location on location.id = delivery.locationid
                            inner join users on users.id = delivery.deliveredby
                            left outer join employee on employeeid = employee.id
                            where status = 1";

            const string SQL_Returned = @"Select delivery.id, location.name as location, employee.name returnby, returnto.name returnto, billno, receivedon, amount, qty, status
                            from delivery inner join referencelist location on location.id = delivery.locationid
                            inner join users on users.id = delivery.returnby
                            inner join employee on users.employeeid = employee.id
                            inner join employee returnto on returnto.id = delivery.returnto
                            where status = 2 ";

            List<DeliveryReport> lst = new List<DeliveryReport>();
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();
                NpgsqlCommand command = null;
                QueryBuilder qb = new QueryBuilder();

                if (_reportcreteria.counterid == 0)
                    qb.CurrentQuery = SQL_Received;
                else if (_reportcreteria.counterid == 1)
                    qb.CurrentQuery = SQL_Delivered;
                else if (_reportcreteria.counterid == 2)
                    qb.CurrentQuery = SQL_Returned;


                qb.AddParameter("delivery.isactive", true, "=");
                qb.AddParameter("delivery.locationid", _reportcreteria.locationid, "=");

                if (_reportcreteria.fromdate != DateTime.MinValue && _reportcreteria.todate != DateTime.MinValue)
                {
                    qb.AddParameter("delivery.receivedon", "billdatefrom", _reportcreteria.fromdate.Date, ">=");
                    qb.AddParameter("delivery.receivedon", "billdateto", _reportcreteria.todate.AddDays(1).Date, "<");
                }

                qb.SortField = "delivery.id";
                command = qb.GetCommand(conn);

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DeliveryReport obill = new DeliveryReport();
                        obill.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        obill.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        obill.amount = reader["amount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["amount"]);
                        obill.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();

                        if (_reportcreteria.counterid == 0)
                        {
                            obill.receivedby = reader["receivedby"] == DBNull.Value ? "" : reader["receivedby"].ToString();
                            obill.receivedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        }
                        else if (_reportcreteria.counterid == 1)
                        {
                            obill.deliveredby = reader["deliveredby"] == DBNull.Value ? "" : reader["deliveredby"].ToString();
                            obill.deliveredon = reader["deliveredon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["deliveredon"]);
                        }
                        else if (_reportcreteria.counterid == 2)
                        {
                            obill.returnedby = reader["returnby"] == DBNull.Value ? "" : reader["returnby"].ToString();
                            obill.returnedto = reader["returnto"] == DBNull.Value ? "" : reader["returnto"].ToString();
                            obill.receivedon = reader["receivedon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["receivedon"]);
                        }
                        lst.Add(obill);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }



        public B2BDashboard SearchB2BDashboard(RetailReportCreteria _reportcreteria)
        {
            B2BDashboard response = new B2BDashboard();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(B2B_Dashboard + B2B_Triggers, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        response.sales.Add(new B2BDashboard.Sales()
                        {
                            type = (reader["billtype"] != DBNull.Value ? (Bill.BillTypes)Convert.ToInt32(reader["billtype"]) : Bill.BillTypes.Cash).ToString(),
                            qty = reader["qty"] != DBNull.Value ? Convert.ToDecimal(reader["qty"]) : 0,
                            receivable = reader["receivable"] != DBNull.Value ? Convert.ToDecimal(reader["receivable"]) : 0
                        });
                    }
                    if (reader.NextResult())
                    {
                        if (reader.Read())
                        {
                            response.bulksales.issuedqty = reader["issued"] != DBNull.Value ? Convert.ToDecimal(reader["issued"]) : 0;
                            response.bulksales.billedqty = reader["billed"] != DBNull.Value ? Convert.ToDecimal(reader["billed"]) : 0;
                            response.bulksales.returnqty = reader["returned"] != DBNull.Value ? Convert.ToDecimal(reader["returned"]) : 0;
                            response.bulksales.returnamount = reader["returnamount"] != DBNull.Value ? Convert.ToDecimal(reader["returnamount"]) : 0;
                            response.bulksales.issuedamount = reader["issuedamount"] != DBNull.Value ? Convert.ToDecimal(reader["issuedamount"]) : 0;
                        }
                    }
                    if (reader.NextResult())
                    {
                        if (reader.Read())
                        {
                            response.purchase.buyingamount = reader["buyingamount"] != DBNull.Value ? Convert.ToDecimal(reader["buyingamount"]) : 0;
                            response.purchase.buyingqty = reader["buyingqty"] != DBNull.Value ? Convert.ToDecimal(reader["buyingqty"]) : 0;
                            response.purchase.buyingmeter = reader["buyingmeter"] != DBNull.Value ? Convert.ToDecimal(reader["buyingmeter"]) : 0;
                        }
                    }
                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            response.jobwork.Add(new B2BDashboard.JobWork()
                            {
                                mode = "Issue",
                                supplier = reader["name"] != DBNull.Value ? reader["name"].ToString() : "",
                                receivedamount = reader["totalamount"] != DBNull.Value ? Convert.ToDecimal(reader["totalamount"]) : 0,
                                receiveddqty = reader["received"] != DBNull.Value ? Convert.ToDecimal(reader["received"]) : 0
                            });
                        }
                    }
                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            response.jobwork.Add(new B2BDashboard.JobWork()
                            {
                                mode = "Inward",
                                supplier = reader["name"] != DBNull.Value ? reader["name"].ToString() : "",
                                receivedamount = reader["totalamount"] != DBNull.Value ? Convert.ToDecimal(reader["totalamount"]) : 0,
                                receiveddqty = reader["received"] != DBNull.Value ? Convert.ToDecimal(reader["received"]) : 0
                            });
                        }
                    }

                    if (reader.NextResult())
                    {
                        if (reader.Read())
                        {
                            response.payments.amount = reader["paidamount"] != DBNull.Value ? Convert.ToDecimal(reader["paidamount"]) : 0;
                        }
                    }

                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            response.debitnotes.Add(new B2BDashboard.Sales()
                            {
                                type = (reader["returntype"] != DBNull.Value ? (Lrinvoicereturn.ReturnTypes)Convert.ToInt32(reader["returntype"]) : Lrinvoicereturn.ReturnTypes.DebitNote).ToString(),
                                qty = reader["qty"] != DBNull.Value ? Convert.ToDecimal(reader["qty"]) : 0,
                                receivable = reader["amount"] != DBNull.Value ? Convert.ToDecimal(reader["amount"]) : 0
                            });

                        }
                    }

                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            response.advances.Add(new B2BDashboard.Advance()
                            {
                                type = reader["type"] != DBNull.Value ? reader["type"].ToString() : "",
                                name = reader["name"] != DBNull.Value ? reader["name"].ToString() : "",
                                advance = reader["advance"] != DBNull.Value ? Convert.ToDecimal(reader["advance"]) : 0
                            });
                        }
                    }

                    while (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            response.triggers.Add(new B2BDashboard.Triggers()
                            {
                                title = reader["title"] != DBNull.Value ? reader["title"].ToString() : "",
                                balance = reader["balance"] != DBNull.Value ? Convert.ToDecimal(reader["balance"]) : 0,
                                noofbills = reader["noofbills"] != DBNull.Value ? Convert.ToDecimal(reader["noofbills"]) : 0
                            });
                        }
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return response;
        }

        const string B2B_Triggers = @"select 'Customer Overdue' as Title,
sum(round(customerinvoice.receivable,0)-(coalesce(customerinvoice.paid,0)+customerinvoice.discount)) balance,
count(*) noofbills from customerinvoice
inner join customer on customer.id = customerinvoice.customerid
where customerinvoice.isactive = true
and customerinvoice.type in (1,2)
and (round(customerinvoice.receivable,0)-(coalesce(customerinvoice.paid,0)+customerinvoice.discount))!=0
and (customer.supportcredit=false or (transactiondate::date + customer.creditdays::int<current_date));

select 'Customer Advance' as Title,sum(round(customerinvoice.receivable,0)-(coalesce(customerinvoice.paid,0)+customerinvoice.discount)) balance,
count(*) noofbills from customerinvoice
inner join customer on customer.id = customerinvoice.customerid
where customerinvoice.isactive = true
and customerinvoice.type in (5)
and (round(customerinvoice.receivable,0)-(coalesce(customerinvoice.paid,0)+customerinvoice.discount))!=0
and (customer.supportcredit=false or (transactiondate::date + customer.creditdays::int<current_date));

select 
 'DebitNote Overdue' as Title,sum(lrinvoicereturn.total) as balance,count(*) noofbills from lrinvoicereturn 
left outer join (select sum(paidamount) paidamount,invoiceid
from supplierpaymentinvoice where supplierpaymentinvoice.isactive = true and supplierpaymentinvoice.hascancel=false and islrinvoicereturn = true
group by invoiceid) paidinvoice on paidinvoice.invoiceid = lrinvoicereturn.id
inner join suppliercompany on suppliercompany.id = lrinvoicereturn.suppliercompanyid
where lrinvoicereturn.isactive = true and lrinvoicereturn.settled = false and
lrinvoicereturn.returntype != 7 and lrinvoicereturn.returntype < 10 and lrinvoicereturn.total-coalesce(paidinvoice.paidamount,0)>0;

select 
'Supplier Advance' as Title,sum(lrinvoicereturn.total) as balance,count(*) noofbills from lrinvoicereturn 
left outer join (select sum(paidamount) paidamount,invoiceid
from supplierpaymentinvoice where supplierpaymentinvoice.isactive = true and supplierpaymentinvoice.hascancel=false and islrinvoicereturn = true
group by invoiceid) paidinvoice on paidinvoice.invoiceid = lrinvoicereturn.id
inner join suppliercompany on suppliercompany.id = lrinvoicereturn.suppliercompanyid
where lrinvoicereturn.isactive = true and lrinvoicereturn.settled = false and
lrinvoicereturn.returntype = 7 and lrinvoicereturn.total-coalesce(paidinvoice.paidamount,0)>0;

select 
'Supplier Due' as Title,sum(lrinvoice.totalamount-tdsamount-coalesce(lrinvoice.presettled,0)-coalesce(paidinvoice.paidamount,0)) as balance,count(*) noofbills
from lrinvoice 
left outer join (select sum(paidamount) paidamount,invoiceid
from supplierpaymentinvoice where islrinvoicereturn = false and isactive = true
group by invoiceid) paidinvoice on paidinvoice.invoiceid = lrinvoice.id
left outer join suppliercompany on suppliercompany.id = lrinvoice.suppliercompanyid
left outer join supplier on supplier.id = suppliercompany.supplierid
left outer join lrentry on lrentry.id = lrinvoice.lrid
where lrinvoice.isactive = true and lrinvoice.settled = false and lrinvoice.totalamount-coalesce(paidinvoice.paidamount,0)>0
and coalesce(lrentry.duedate,lrinvoice.entrydate::date + creditdays)<current_date;

select 'Jobwork Due Qty' as Title,0::decimal as balance,sum(Jobworkbillitems.oqty-(rqty+dqty)) noofbills from jobworkbillitems 
        inner join Jobworkbill on Jobworkbill.id = Jobworkbillid
        where jobworkbillitems.isactive = true and Jobworkbillitems.oqty-(rqty+dqty)>0
		and coalesce(Jobworkbill.expecteddate,Jobworkbill.entrydate::date+30)>current_date;

select 'Approved Due Qty' as Title,0::decimal as balance,sum(bulkbillitems.qty-(bulkbillitems.billedqty+bulkbillitems.journalqty)) noofbills from bulkbillitems
inner join bulkbill on bulkbill.id = bulkbillitems.billid
where bulkbill.isactive = true and bulkbillitems.isactive = true
and bulkbillitems.qty-(bulkbillitems.billedqty+bulkbillitems.journalqty)>0 and billtype = 10
and (case when billattributes->>'duedate' is null then billdate::date+30 
 when billattributes->>'duedate' = '0001-01-01' then billdate::date+30 
 else cast(billattributes->>'duedate' as date) end)<current_date;

select 'B2B Bill unpacked' as Title,sum(billvalue) as balance, count(*) as noofbills from Billinbox
where (lrno = '' or packedby = 0)
and billdate>=@fromdate and billdate<@todate;

select 'Debit Note unpacked' as Title,sum(total) as balance, count(*) as noofbills from lrinvoicereturn
where returndate>=@fromdate and returndate<@todate and (lrno = '' or packedby = 0);

select 'Less Cost' as Title,
sum(stock.buyingprice-((billitems.receivable-billitems.tax)/billitems.qty)*billitems.qty) as balance,
sum(billitems.qty) Noofbills from bill
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
inner join salablegoods on salablegoods.id = billitems.salablegoodsid
inner join stock on stock.id = billitems.stockid
where billitems.qty>0 and bill.isactive=true  
and (billitems.receivable-billitems.tax)/billitems.qty<stock.buyingprice
and billdate>=@fromdate and billdate<@todate;";

        const string B2B_Dashboard = @"select sum(billitems.receivable) receivable,sum(billitems.qty) qty,billtype from bill
inner join billitems on billitems.billid = bill.id and billitems.isactive=true
where bill.billdate>=@fromdate and bill.billdate<@todate and
bill.isactive = true and billtype !=9 
group by billtype;

select sum(case when billtype=12 then 0 else BulkBillItems.receivable end) issuedamount ,
sum(case when billtype=12 then BulkBillItems.receivable else 0  end) returnamount ,sum(case when billtype=12 then 0 else BulkBillItems.qty end) issued,
sum(case when billtype=12 then BulkBillItems.qty else 0  end) returned,
sum(case when billtype=10 then BulkBillItems.billedqty else 0 end) billed from bulkbill
inner join BulkBillItems on BulkBillItems.billid = bulkbill.id 
where bulkbill.billdate>=@fromdate and bulkbill.billdate<@todate and
bulkbill.isactive = true and BulkBillItems.isactive=true;

select sum(lrinvoiceitems.amount) buyingamount,sum(case when sellingmode = 3 then 0 else lrinvoiceitems.buyingqty end) buyingqty,
sum(case when sellingmode =3 then lrinvoiceitems.buyingqty else 0 end) buyingmeter from lrinvoice 
inner join lrinvoiceitems on lrinvoiceitems.lrinvoiceid = lrinvoice.id
left outer join products on products.id = productid
where  lrinvoice.entrydate>=@fromdate and lrinvoice.entrydate<@todate 
and lrinvoice.isactive = true and lrinvoiceitems.isactive = true;

select sum(oqty) received,sum(totalamount) totalamount,suppliercompany.name from jobworkbill  
inner join suppliercompany on suppliercompany.id = jobworkbill.suppliercompanyid
where jobworkbill.invoicedate>=@fromdate and jobworkbill.invoicedate<@todate and
jobworkbill.isactive = true
group by suppliercompany.name;

select sum(qty) received,sum(totalamount) totalamount,suppliercompany.name from jobworkbillgrn
inner join suppliercompany on suppliercompany.id = jobworkbillgrn.suppliercompanyid
where jobworkbillgrn.entrydate>=@fromdate and jobworkbillgrn.entrydate<@todate and
jobworkbillgrn.isactive = true
group by suppliercompany.name;

select sum(paidamount) paidamount from supplierpayment
where supplierpayment.paymentdate>=@fromdate and supplierpayment.paymentdate<@todate and
supplierpayment.isactive = true and supplierpayment.hascancel=false ;

select returntype,sum(qty) qty,sum(amount) amount from lrinvoicereturn 
where lrinvoicereturn.returndate>=@fromdate and lrinvoicereturn.returndate<@todate and lrinvoicereturn.isactive = true
group by returntype;

select 'customer' as type,customer.name, advance from customerinvoice
inner join customer on customer.id = customerinvoice.customerid
where customerinvoice.type=5
and customerinvoice.transactiondate>=@fromdate and customerinvoice.transactiondate<@todate 
and customerinvoice.isactive = true
union all
select 'supplier' as type,suppliercompany.name, amount advance from Lrinvoicereturn
inner join suppliercompany on suppliercompany.id = Lrinvoicereturn.suppliercompanyid
where Lrinvoicereturn.returntype=7 
and lrinvoicereturn.returndate>=@fromdate and lrinvoicereturn.returndate<@todate 
and lrinvoicereturn.isactive = true;
";

        public class SyncOnlineRequest : BaseEntity
        {
            public long productid { get; set; }
            public long supplierid { get; set; }
            public long markerid { get; set; }
            public string designid { get; set; }
            public List<imageitem> imagelist { get; set; }
            public List<markeritem> markerlist { get; set; }
            public class imageitem
            {
                public long colourid { get; set; }
                public string imageid { get; set; }
                public string oimageid { get; set; }
                public List<stockimage> removelist { get; set; }
                public List<stockimage> imagelist { get; set; }
                public class stockimage
                {
                    public long id { get; set; }
                    public string imageid { get; set; }
                }
            }

            public class markeritem
            {
                public long locationid { get; set; }
                public decimal qty { get; set; }
                public long colourid { get; set; }

                public List<BarcodeStock> GetBarcodeStock()
                {
                    List<BarcodeStock> newstock = new List<BarcodeStock>();
                    var avilqty = qty;
                    if (qty == 0) return newstock;
                    for (var idx = 0; idx < bstock.Count; idx++)
                    {
                        if (bstock[idx].qty >= avilqty)
                        {
                            newstock.Add(new BarcodeStock()
                            {
                                barcode = bstock[idx].barcode,
                                serialno = bstock[idx].serialno,
                                qty = avilqty
                            });
                            avilqty = 0;
                        }
                        else if (avilqty > 0 && bstock[idx].qty > 0)
                        {
                            newstock.Add(new BarcodeStock()
                            {
                                barcode = bstock[idx].barcode,
                                serialno = bstock[idx].serialno,
                                qty = bstock[idx].qty
                            });
                            avilqty -= bstock[idx].qty;
                        }
                        if (avilqty == 0) break;
                    }
                    return newstock;
                }
                public List<BarcodeStock> bstock { get; set; }

                public class BarcodeStock
                {
                    public decimal qty { get; set; }
                    public decimal oqty { get; set; }
                    public decimal bqty { get; set; }
                    public string serialno { get; set; }
                    public string barcode { get; set; }

                }
            }
        }
