        public class DesignStockResponse
        {
            public long productid { get; set; }
            public string designid { get; set; }
            public List<ColourStock> stock { get; set; }
            public List<string> sizelist { get; set; }

            public class ColourStock
            {
                public long colourid { get; set; }
                public long supplierid { get; set; }
                public string colour { get; set; }
                public string supplier { get; set; }
                public string designid { get; set; }
                public string product { get; set; }
                public DateTime fpurchase { get; set; }
                public DateTime lpurchase { get; set; }
                public DateTime fsales { get; set; }
                public DateTime lsales { get; set; }
                public string imageid { get; set; }
                public decimal wstock { get; set; }
                public List<StockImage> imagelist { get; set; }
                public List<LocationStock> stock { get; set; }
                [JsonIgnore]
                public DateTime purchasedate
                {
                    set
                    {
                        if (fpurchase == DateTime.MinValue || fpurchase > value)
                            fpurchase = value;
                        if (lpurchase == DateTime.MinValue || lpurchase < value)
                            lpurchase = value;
                    }
                }
                [JsonIgnore]
                public DateTime salesdate
                {
                    set
                    {
                        if (fsales == DateTime.MinValue || fsales > value)
                            fsales = value;
                        if (lsales == DateTime.MinValue || lsales < value)
                            lsales = value;
                    }
                }
                public class StockImage
                {
                    public long id { get; set; }
                    public string imageid { get; set; }
                }
            }

            public class LocationStock
            {
                public long locationid { get; set; }
                public long sizeid { get; set; }
                public string size { get; set; }
                public decimal qty { get; set; }
                public decimal oqty { get; set; }
                public decimal bqty { get; set; }
                public List<BarcodeStock> bstock { get; set; }

                public class BarcodeStock
                {
                    public decimal qty { get; set; }
                    public decimal oqty { get; set; }
                    public decimal bqty { get; set; }
                    public string serialno { get; set; }
                    public string barcode { get; set; }

                }
            }
        }

