        public bool SyncOnline(SyncOnlineRequest request)
        {
            var availablecolours = request.markerlist.ConvertAll(x => x.colourid).Distinct().ToList();
            request.imagelist.RemoveAll(x => !availablecolours.Contains(x.colourid));

            var images = request.imagelist.FindAll(x => (x.imagelist != null && x.imagelist.Count > 0) || (x.removelist != null && x.removelist.Count > 0));

            if (images.Count > 0)
            {
                using (var connection = CreateConnection())
                {

                    try
                    {
                        connection.Open();
                        var transaction = connection.BeginTransaction();
                        foreach (var image in images)
                        {

                            if (image.imagelist != null)
                            {
                                foreach (var img in image.imagelist)
                                {

                                    if (img.id <= 0)
                                    {
                                        string stockimagequery = "insert into stockimage(productid,supplierid,designid,colourid,imageid) values (@productid,@supplierid,@designid,@colourid,@imageid)";
                                        NpgsqlCommand command = new NpgsqlCommand(stockimagequery, connection, transaction);
                                        command.Parameters.Add("productid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = request.productid;
                                        command.Parameters.Add("supplierid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = request.supplierid;
                                        command.Parameters.Add("colourid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = image.colourid;
                                        command.Parameters.Add("imageid", NpgsqlTypes.NpgsqlDbType.Varchar).Value = img.imageid == null ? "" : img.imageid;
                                        command.Parameters.Add("designid", NpgsqlTypes.NpgsqlDbType.Varchar).Value = request.designid == null ? "" : request.designid;
                                        command.ExecuteNonQuery();
                                    }
                                }
                            }
                            if (image.removelist != null)
                            {
                                ExecuteQuery("delete from stockimage where id in (" + String.Join(",", image.removelist.ConvertAll(x => x.id)) + ")", null,
                                    connection, transaction);
                            }
                        }
                        transaction.Commit();
                        connection.Close();
                    }
                    catch (Exception exp)
                    {
                        connection.Close();
                    }
                }
            }

            images = request.imagelist.FindAll(x => x.imageid != x.oimageid);
            if (images.Count > 0 && InfyPOS.Services.ConfigManager.Instance(this.Context.OrganizationID).Config.system_ismfgapplication)
            {
                MfgdesignDataService mfgdesignDataService = new MfgdesignDataService() { Context = this.Context };
                var designs = mfgdesignDataService.Search(new MfgdesignCreteria()
                {
                    code = request.designid,
                    includecolours = true,
                    includedetail = true
                });

                if (designs.Count == 0)
                {
                    designs = mfgdesignDataService.Search(new MfgdesignCreteria()
                    {
                        name = request.designid,
                        includecolours = true,
                        includedetail = true
                    });
                }

                if (designs.Count == 1 && designs[0].sizegroup != null &&
                    designs[0].sizegroup.colouritems != null)
                {
                    if (designs[0].imagelist == null)
                        designs[0].imagelist = new List<string>();

                    if (designs[0].imagelist.Count == 0)
                        designs[0].imagelist.AddRange(images.ConvertAll(x => x.imageid));

                    foreach (var item in images)
                    {
                        if (designs[0].sizegroup.colouritems.Exists(x => x.colourid == item.colourid))
                        {
                            designs[0].sizegroup.colouritems.Find(x => x.colourid == item.colourid).imageid = item.imageid;
                        }
                        else
                        {
                            designs[0].sizegroup.colouritems.Add(new Mfgdesign.Sizegroup.ColourItem()
                            {
                                colourid = item.colourid,
                                imageid = item.imageid,
                            });
                        }
                    }
                    mfgdesignDataService.UpdateImages(designs[0]);
                }
            }

            foreach (var img in images)
            {
                var param = new SortedList<string, object>();
                param.Add("imageid", img.imageid);
                var imagebarcodes = request.markerlist.FindAll(x => x.colourid == img.colourid);
                if (imagebarcodes.Count > 0)
                {
                    foreach (var barcodestock in imagebarcodes)
                    {
                        string imageupdatequery = "Update stock set imageid=@imageid where barcode in (" + String.Join(",", barcodestock.bstock.ConvertAll(x => "'" + x.barcode + "'")) + ")";
                        ExecuteQuery(imageupdatequery, param);
                    }
                }
            }

            StockmarkerDataService stockmarkerDataService = new StockmarkerDataService() { Context = this.Context };
            var marker = new MarkerContainer()
            {
                markerid = request.markerid,
                isonline = false,
                items = new List<Stockmarker>()
            };
            foreach (var img in request.markerlist)
            {
                foreach (var barcodestock in img.GetBarcodeStock())
                {
                    var param = new SortedList<string, object>();
                    param.Add("markerid", request.markerid);
                    param.Add("locationid", img.locationid);
                    param.Add("barcode", barcodestock.barcode);
                    param.Add("qty", barcodestock.qty);
                    string salablegoodsquery = @"Update salablegoods set olqty=@qty 
                where barcode=@barcode and locationid=@locationid 
                RETURNING id,stockid";

                    long salablegoodsid = 0;
                    long stockid = 0;
                    using (var reader = ExecuteReader(salablegoodsquery, param))
                    {
                        if (reader.Read())
                        {
                            salablegoodsid = reader.GetInt64(0);
                            stockid = reader.GetInt64(1);
                        }
                    }

                    if (salablegoodsid > 0)
                    {
                        string imageupdatequery = @"Update stockmarker set qty=@qty 
                                                    where markerid=@markerid and barcode=@barcode and locationid=@locationid and isactive=true";
                        if (ExecuteQuery(imageupdatequery, param) == 0)
                        {
                            marker.locationid = img.locationid;
                            marker.items.Clear();
                            marker.items.Add(new Stockmarker()
                            {
                                markerid = request.markerid,
                                barcode = barcodestock.barcode,
                                locationid = img.locationid,
                                salablegoodsid = salablegoodsid,
                                stockid = stockid,
                                qty = barcodestock.qty,
                                isactive = true,
                                version = 1,
                                createdby = Context.UserID,
                                modifiedby = Context.UserID,
                                createdon = DateTime.Now,
                                modifiedon = DateTime.Now
                            });
                            stockmarkerDataService.Save(marker);
                        }
                    }
                }
            }

            ProcessManager.Instance(Context.OrganizationID).Start(new ProcessManager.ProcessData()
            {
                action = "UploadQTKart",
                criteria = new OnlineIntegration.ProductCriteria()
                {
                    designid = request.designid,
                    productid = request.productid,
                    markerid = request.markerid,
                    colourid = availablecolours
                }
            });
            return true;
        }
        public DesignStockResponse SearchDesignwiseStock(SearchDesignCriteria criteria)
        {
            DesignStockResponse response = new DesignStockResponse()
            {
                designid = criteria.designid,
                productid = criteria.productid,
                stock = new List<DesignStockResponse.ColourStock>()
            };
            var param = new SortedList<string, object>();
            string query = @"select stock.designid,salablegoods.locationid,items.sizeid,
            colour.name colurname,size.name sizename,products.name productname,items.colourid,
            stock.supplierid,supplier.name suppliername,stock.imageid,stock.barcode,stock.serialno,
            sum(salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty)) rstock
            from stock
            left outer join lrinvoiceitems on lrinvoiceitems.id = stock.invoiceitemid
            left outer join lrinvoice on lrinvoice.id= lrinvoiceid
            inner join items on items.id = stock.itemid
            inner join products on products.id = items.productid
            left outer join referencelist colour on colour.id = items.colourid
            left outer join referencelist size on size.id = items.sizeid
            left outer join salablegoods on stockid = stock.id
            left outer join supplier on supplier.id = stock.supplierid ";

            if (criteria.allstock)
            {
                if (string.IsNullOrEmpty(criteria.designid))
                    query += " where stock.isactive =true ";
                else
                    query += " where stock.isactive =true and stock.designid = @designid ";
            }
            else
            {
                query += " where stock.isactive =true and (stock.hasstock=true or (salablegoods.hasstock=true and salablegoods.isactive=true)) and stock.designid = @designid";
            }

            if (criteria.sizeids != null && criteria.sizeids.Count > 0)
            {
                query += " and items.sizeid in (" + String.Join(",", criteria.sizeids) + ")";
            }

            if (criteria.colourids != null && criteria.colourids.Count > 0)
            {
                query += " and items.colourid in (" + String.Join(",", criteria.colourids) + ")";
            }

            if (criteria.productid > 0)
                query += " and stock.productid=@productid";
            if (criteria.supplierid > 0)
                query += " and stock.supplierid=@supplierid";
            if (criteria.locationid > 0)
                query += " and salablegoods.locationid=@locationid";

            if (criteria.pfromdate.Date != DateTime.MinValue && criteria.ptodate.Date != DateTime.MinValue)
            {
                param.Add("pfromdate", criteria.pfromdate);
                param.Add("ptodate", criteria.ptodate.AddDays(1));
                query += " and lrinvoice.entrydate>=@pfromdate and lrinvoice.entrydate<@ptodate ";
            }

            query += " group by stock.designid,salablegoods.locationid,items.sizeid,stock.imageid,colour.name,size.name,products.name,items.colourid,stock.supplierid,supplier.name,stock.barcode,stock.serialno";

            param.Add("designid", string.IsNullOrEmpty(criteria.designid) ? "" : criteria.designid);
            param.Add("productid", criteria.productid);
            param.Add("locationid", criteria.locationid);
            param.Add("supplierid", criteria.supplierid);

            List<string> barcodeList = new List<string>();
            using (var reader = ExecuteReader(query, param))
            {
                while (reader.Read())
                {
                    string designid = reader["designid"] == DBNull.Value ? "" : Convert.ToString(reader["designid"]);
                    decimal rstock = reader["rstock"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rstock"]);
                    long sizeid = reader["sizeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["sizeid"]);
                    long colourid = reader["colourid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["colourid"]);
                    long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                    long supplierid = reader["supplierid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["supplierid"]);
                    string colurname = reader["colurname"] == DBNull.Value ? "" : Convert.ToString(reader["colurname"]);
                    string sizename = reader["sizename"] == DBNull.Value ? "" : Convert.ToString(reader["sizename"]);
                    string productname = reader["productname"] == DBNull.Value ? "" : Convert.ToString(reader["productname"]);
                    string suppliername = reader["suppliername"] == DBNull.Value ? "" : Convert.ToString(reader["suppliername"]);
                    string imageid = reader["imageid"] == DBNull.Value ? "" : Convert.ToString(reader["imageid"]);
                    string barcode = reader["barcode"] == DBNull.Value ? "" : Convert.ToString(reader["barcode"]);
                    string serialno = reader["serialno"] == DBNull.Value ? "" : Convert.ToString(reader["serialno"]);
                    barcodeList.Add(barcode);
                    DesignStockResponse.ColourStock colourStock = null;
                    if (!response.stock.Exists(x => x.designid == designid && x.colour == colurname && x.product == productname && x.supplierid == supplierid))
                    {
                        colourStock = new DesignStockResponse.ColourStock()
                        {
                            product = productname,
                            colour = colurname,
                            supplier = suppliername,
                            colourid = colourid,
                            designid = designid,
                            imageid = imageid,
                            supplierid = supplierid,
                            stock = new List<DesignStockResponse.LocationStock>()
                        };
                        response.stock.Add(colourStock);
                    }
                    else
                    {
                        colourStock = response.stock.Find(x => x.designid == designid && x.colour == colurname && x.product == productname && x.supplierid == supplierid);
                    }
                    if (colourStock.stock.Exists(x => x.locationid == locationid && x.sizeid == sizeid))
                    {
                        colourStock.stock.Find(x => x.locationid == locationid && x.sizeid == sizeid).qty += rstock;
                    }
                    else
                    {
                        var lstock = new DesignStockResponse.LocationStock()
                        {
                            locationid = locationid,
                            qty = rstock,
                            size = sizename,
                            sizeid = sizeid,
                        };
                        colourStock.stock.Add(lstock);
                        lstock.bstock = new List<DesignStockResponse.LocationStock.BarcodeStock>();
                    }
                    var bstocklist = colourStock.stock.Find(x => x.locationid == locationid && x.sizeid == sizeid).bstock;
                    if (bstocklist.Exists(x => x.barcode == barcode))
                    {
                        bstocklist.Find(x => x.barcode == barcode).qty += rstock;
                    }
                    else
                    {
                        bstocklist.Add(new DesignStockResponse.LocationStock.BarcodeStock()
                        {
                            barcode = barcode,
                            serialno = serialno,
                            qty = rstock
                        });
                    }
                }
            }

            if (criteria.includesales)
            {
                query = @"select stock.designid,salablegoods.locationid,items.sizeid,
                            products.name productname,items.colourid,
                            stock.supplierid,supplier.name suppliername,
                            stock.imageid,colour.name colurname,size.name sizename,
                            sum(billitems.qty) soldqty
                            from bill
                            inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                            inner join salablegoods on salablegoods.id = billitems.salablegoodsid
                            inner join stock on stock.id = salablegoods.stockid
                            left outer join lrinvoiceitems on lrinvoiceitems.id = stock.invoiceitemid
                            left outer join lrinvoice on lrinvoice.id= lrinvoiceid
                            inner join items on items.id = stock.itemid
                            inner join products on products.id = items.productid
                            left outer join referencelist colour on colour.id = items.colourid
                            left outer join referencelist size on size.id = items.sizeid
                            left outer join supplier on supplier.id = stock.supplierid
                            where billdate>=@fromdate and billdate<@todate";

                if (!string.IsNullOrEmpty(criteria.designid))
                    query += " and stock.designid = @designid";

                param.Clear();
                param.Add("designid", string.IsNullOrEmpty(criteria.designid) ? "" : criteria.designid);
                param.Add("productid", criteria.productid);
                param.Add("locationid", criteria.locationid);
                param.Add("supplierid", criteria.supplierid);

                if (criteria.fromdate.Date == DateTime.MinValue || criteria.todate.Date == DateTime.MinValue)
                {
                    criteria.todate = DateTime.Now.Date;
                    criteria.fromdate = DateTime.Now.Date.AddMonths(-3);
                }

                param.Add("fromdate", criteria.fromdate);
                param.Add("todate", criteria.todate.AddDays(1));

                if (criteria.pfromdate.Date != DateTime.MinValue && criteria.ptodate.Date != DateTime.MinValue)
                {
                    param.Add("pfromdate", criteria.pfromdate);
                    param.Add("ptodate", criteria.ptodate.AddDays(1));
                    query += " and lrinvoice.entrydate>=@pfromdate and lrinvoice.entrydate<@ptodate ";
                }

                if (criteria.sizeids != null && criteria.sizeids.Count > 0)
                {
                    query += " and items.sizeid in (" + String.Join(",", criteria.sizeids) + ")";
                }

                if (criteria.colourids != null && criteria.colourids.Count > 0)
                {
                    query += " and items.colourid in (" + String.Join(",", criteria.colourids) + ")";
                }

                if (criteria.productid > 0)
                    query += " and stock.productid=@productid";
                if (criteria.supplierid > 0)
                    query += " and stock.supplierid=@supplierid";
                if (criteria.locationid > 0)
                    query += " and salablegoods.locationid=@locationid";

                query += @" group by stock.designid,salablegoods.locationid,items.sizeid,
                            products.name,items.colourid,stock.supplierid,supplier.name,
                            stock.imageid,colour.name,size.name";

                using (var reader = ExecuteReader(query, param))
                {
                    while (reader.Read())
                    {
                        string designid = reader["designid"] == DBNull.Value ? "" : Convert.ToString(reader["designid"]);
                        decimal soldqty = reader["soldqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["soldqty"]);
                        long sizeid = reader["sizeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["sizeid"]);
                        long colourid = reader["colourid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["colourid"]);
                        long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        long supplierid = reader["supplierid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["supplierid"]);

                        string colurname = reader["colurname"] == DBNull.Value ? "" : Convert.ToString(reader["colurname"]);
                        string sizename = reader["sizename"] == DBNull.Value ? "" : Convert.ToString(reader["sizename"]);
                        string productname = reader["productname"] == DBNull.Value ? "" : Convert.ToString(reader["productname"]);
                        string suppliername = reader["suppliername"] == DBNull.Value ? "" : Convert.ToString(reader["suppliername"]);
                        string imageid = reader["imageid"] == DBNull.Value ? "" : Convert.ToString(reader["imageid"]);
                        DesignStockResponse.ColourStock colourStock = null;
                        if (!response.stock.Exists(x => x.designid == designid && x.colour == colurname && x.product == productname && x.supplierid == supplierid))
                        {
                            colourStock = new DesignStockResponse.ColourStock()
                            {
                                product = productname,
                                colour = colurname,
                                supplier = suppliername,
                                colourid = colourid,
                                designid = designid,
                                imageid = imageid,
                                supplierid = supplierid,
                                stock = new List<DesignStockResponse.LocationStock>()
                            };
                            response.stock.Add(colourStock);
                        }
                        else
                        {
                            colourStock = response.stock.Find(x => x.designid == designid && x.colour == colurname && x.product == productname && x.supplierid == supplierid);
                        }
                        if (colourStock.stock.Exists(x => x.locationid == locationid && x.sizeid == sizeid))
                        {
                            colourStock.stock.Find(x => x.locationid == locationid && x.sizeid == sizeid).bqty += soldqty;
                        }
                        else
                        {
                            colourStock.stock.Add(new DesignStockResponse.LocationStock()
                            {
                                locationid = locationid,
                                bqty = soldqty,
                                size = sizename,
                                sizeid = sizeid
                            });
                        }
                    }
                }
            }


            if (InfyPOS.Services.ConfigManager.Instance(this.Context.OrganizationID).Config.system_ismfgapplication &&
                !string.IsNullOrEmpty(criteria.designid))
            {
                MfgdesignDataService mfgdesignDataService = new MfgdesignDataService() { Context = this.Context };
                var designs = mfgdesignDataService.Search(new MfgdesignCreteria()
                {
                    code = criteria.designid,
                    includecolours = true,
                    includedetail = true
                });
                if (designs.Count == 0)
                {
                    designs = mfgdesignDataService.Search(new MfgdesignCreteria()
                    {
                        name = criteria.designid,
                        includecolours = true,
                        includedetail = true
                    });
                }

                if (designs.Count == 1 && designs[0].sizegroup != null &&
                    designs[0].sizegroup.colouritems != null)
                {
                    foreach (var item in response.stock)
                    {
                        var imageid = item.imageid;
                        if (designs[0].sizegroup.colouritems.Exists(x => x.colourid == item.colourid) &&
                           !string.IsNullOrEmpty(designs[0].sizegroup.colouritems.Find(x => x.colourid == item.colourid).imageid))
                        {
                            imageid = designs[0].sizegroup.colouritems.Find(x => x.colourid == item.colourid).imageid;
                        }
                        else if (string.IsNullOrEmpty(imageid) && designs[0].imagelist != null &&
                            designs[0].imagelist.Count > 0)
                        {
                            imageid = designs[0].imagelist[0];
                        }
                        item.imageid = imageid;
                    }
                }
            }


            string stockimagequery = "select colourid,supplierid,designid,imageid from stockimage where productid=@productid and supplierid=@supplierid and designid=@designid";
            var stockimageparam = new SortedList<string, object>();
            stockimageparam.Add("productid", criteria.productid);
            stockimageparam.Add("designid", string.IsNullOrEmpty(criteria.designid) ? "" : criteria.designid);
            stockimageparam.Add("supplierid", criteria.supplierid);
            if (criteria.supplierid <= 0)
                stockimagequery = stockimagequery.Replace("and supplierid=@supplierid", "");
            if (string.IsNullOrEmpty(criteria.designid))
                stockimagequery = stockimagequery.Replace(" and designid=@designid", "");

            using (var reader = ExecuteReader(stockimagequery, stockimageparam))
            {
                while (reader.Read())
                {
                    long colourid = reader.GetInt64(0);
                    long supplierid = reader.GetInt64(1);
                    string designid = reader.GetString(2);
                    string imageid = reader.GetString(3);
                    if (response.stock.Exists(x => x.colourid == colourid && x.supplierid == supplierid && x.designid == designid))
                    {
                        response.stock.Find(x => x.colourid == colourid && x.supplierid == supplierid && x.designid == designid).imageid = imageid;
                    }
                }
            }

            ReferencelistDataService referencelistDataService = new ReferencelistDataService() { Context = this.Context };
            var stockmarkers = referencelistDataService.Search(new ReferencelistCreteria()
            {
                type = "MARKER"
            });
            var onlinemarkerid = stockmarkers.FindAll(x => x.additionalinfo != null && x.additionalinfo.isonline).ConvertAll(x => x.id);
            if (onlinemarkerid.Count > 0 && barcodeList.Count > 0)
            {
                query = string.Format(@"select Stockmarker.barcode,Stockmarker.locationid,olqty,colourid,sizeid,stock.designid,stock.serialno from Stockmarker 
                inner join stock on stock.barcode = Stockmarker.barcode 
                inner join salablegoods on salablegoods.barcode = Stockmarker.barcode and salablegoods.locationid = Stockmarker.locationid
                inner join items on items.id = stock.itemid
                where markerid in ({0}) and Stockmarker.barcode in ({1})", string.Join(",", onlinemarkerid),
                string.Join(",", barcodeList.ConvertAll(x => "'" + x + "'")));
                if (criteria.locationid > 0)
                    query += " salablegoods.locationid=@locationid";

                using (var reader = ExecuteReader(query, param))
                {
                    while (reader.Read())
                    {
                        string barcode = reader["barcode"] == DBNull.Value ? "" : Convert.ToString(reader["barcode"]);
                        string serialno = reader["serialno"] == DBNull.Value ? "" : Convert.ToString(reader["serialno"]);
                        string designid = reader["designid"] == DBNull.Value ? "" : Convert.ToString(reader["designid"]);
                        decimal olqty = reader["olqty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["olqty"]);
                        long sizeid = reader["sizeid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["sizeid"]);
                        long colourid = reader["colourid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["colourid"]);
                        long locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);

                        var stockitem = response.stock.Find(x => x.designid == designid && x.colourid == colourid).stock;
                        if (stockitem != null)
                        {
                            if (!stockitem.Exists(x => x.locationid == locationid))
                            {
                                var lstock = new DesignStockResponse.LocationStock()
                                {
                                    locationid = locationid,
                                    size = stockitem.First().size,
                                    sizeid = stockitem.First().sizeid,
                                    bstock = new List<DesignStockResponse.LocationStock.BarcodeStock>()
                                };
                                stockitem.Add(lstock);
                            }
                            stockitem.Find(x => x.locationid == locationid).oqty = olqty;
                            var bstocklist = stockitem.Find(x => x.locationid == locationid).bstock;
                            if (bstocklist.Exists(x => x.barcode == barcode))
                            {
                                bstocklist.Find(x => x.barcode == barcode).oqty += olqty;
                            }
                            else
                            {
                                bstocklist.Add(new DesignStockResponse.LocationStock.BarcodeStock()
                                {
                                    barcode = barcode,
                                    serialno = serialno,
                                    oqty = olqty
                                });
                            }
                        }
                    }
                }
            }
            response.stock.RemoveAll(x => x.stock == null || x.stock.Count == 0);

            if (criteria.groupsize)
            {
                List<string> sizeList = new List<string>();
                response.stock.ForEach(x =>
                {
                    x.stock = x.stock.GroupBy(y => y.sizeid).ToList().ConvertAll(z => new DesignStockResponse.LocationStock()
                    {
                        sizeid = z.Key,
                        size = z.First().size,
                        bqty = z.Sum(a => a.bqty),
                        oqty = z.Sum(a => a.oqty),
                        qty = z.Sum(a => a.qty),
                    }).ToList();
                    sizeList.AddRange(x.stock.ConvertAll(z => z.size));
                });
                sizeList = sizeList.Distinct().ToList();
                List<string> list = WebAPI.Data.Utility.GetSizeList(sizeList);
                if (list == null || list.Count == 0)
                {
                    response.sizelist = sizeList;
                }
                else
                {
                    list.RemoveAll(x => x != null && !sizeList.Contains(x));
                    response.sizelist = list;
                }
            }
            response.stock = response.stock.OrderBy(x => x.supplier).ThenBy(y => y.product).ToList();
            return response;
        }


        internal string SaveStockImages(DesignStockImageRequest item)
        {
            int deletedimages = 0;
            int insertedimages = 0;
            int updatedstocks = 0;
            try
            {
                using (var connection = CreateConnection())
                {
                    connection.Open();
                    var transaction = connection.BeginTransaction();
                    foreach (var imgitem in item.List)
                    {
                        string stockimagequery = @"delete from stockimage where productid=@productid and supplierid=@supplierid and designid=@designid and colourid =@colourid;";

                        NpgsqlCommand command = new NpgsqlCommand(stockimagequery, connection, transaction);
                        command.Parameters.Add("productid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = item.productid;
                        command.Parameters.Add("supplierid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = imgitem.supplierid;
                        command.Parameters.Add("colourid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = imgitem.colourid;
                        command.Parameters.Add("imageid", NpgsqlTypes.NpgsqlDbType.Varchar).Value = imgitem.imageid == null ? "" : imgitem.imageid;
                        command.Parameters.Add("designid", NpgsqlTypes.NpgsqlDbType.Varchar).Value = item.designid == null ? "" : item.designid;
                        deletedimages += command.ExecuteNonQuery();

                        //command.CommandText = @"insert into stockimage(productid,supplierid,designid,colourid,imageid) values (@productid,@supplierid,@designid,@colourid,@imageid);";
                        //insertedimages += command.ExecuteNonQuery();

                        command.CommandText = @"insert into stockimage(productid,supplierid,designid,colourid,imageid) values (@productid,@supplierid,@designid,@colourid,@imageid);";
                        insertedimages += command.ExecuteNonQuery();
                        if (imgitem.colourid > 0)
                        {
                            command.CommandText = @"update stock set imageid=@imageid from items where items.id = stock.itemid
                                                and items.productid=@productid and supplierid=@supplierid and designid=@designid and items.colourid=@colourid;";
                        }
                        else
                        {
                            command.CommandText = "update stock set imageid=@imageid where productid=@productid and designid=@designid and supplierid=@supplierid;";
                        }
                        updatedstocks += command.ExecuteNonQuery();

                    }
                    transaction.Commit();
                    connection.Close();
                }
                return string.Format("Deleted Images {0},Inserted Images {1}, Updated Stock with New Images {2}",
                    deletedimages, insertedimages, updatedstocks);

            }
            catch (Exception exp)
            {
                return exp.Message;
            }
        }

        public List<string> SearchDesignList(SearchDesignCriteria criteria)
        {
            List<string> response = new List<string>();
            List<string> conditions = new List<string>();
            var param = new SortedList<string, object>();
            if (criteria.productid == 0 &&
                criteria.supplierid == 0 &&
                string.IsNullOrEmpty(criteria.barcode))
                return new List<string>();

            if (criteria.productid > 0)
                conditions.Add(" stock.productid = @productid ");
            if (criteria.supplierid > 0)
                conditions.Add(" stock.supplierid = @supplierid ");
            if (!string.IsNullOrEmpty(criteria.barcode))
                conditions.Add(" stock.barcode = @barcode ");
            string query = String.Format(@"select designid,sum(salablegoods.iqty-(salablegoods.oqty+salablegoods.dqty+salablegoods.jqty)) rstock,
            sum(stock.qty - (stock.transfered+stock.returnqty+stock.damagedqty+stock.journalqty)) wstock from stock
            left outer join salablegoods on stockid = stock.id
            where designid != '' and (stock.hasstock=true or (salablegoods.hasstock=true and salablegoods.isactive=true)) and {0}
            group by designid", String.Join(" and ", conditions));
            param.Add("productid", criteria.productid);
            param.Add("supplierid", criteria.supplierid);
            param.Add("barcode", string.IsNullOrEmpty(criteria.barcode) ? "" : criteria.barcode);
            using (var reader = ExecuteReader(query, param))
            {
                while (reader.Read())
                {
                    response.Add(reader.GetString(0));
                }
            }
            return response;
        }

        static AutoResetEvent dashboardcache = new AutoResetEvent(true);
        public List<Dashboard_StockVsSales> GetDashboard_StockVsSalesCached(decimal currentStock, DateTime fromDate)
        {
            if (HasResctrictedAccess)
                return new List<Dashboard_StockVsSales>();

            StoretransactionDataService storetransactionDataService = new StoretransactionDataService() { Context = this.Context };
            var cached = storetransactionDataService.Search(new StoretransactionCreteria()
            {
                type = "StkDBoard",
                actiondate = DateTimeNow.Date
            });
            if (cached.Count > 0)
                return cached[0].StockDBoardAtribute;

            if (dashboardcache.WaitOne(new TimeSpan(0, 2, 0)))
            {
                cached = storetransactionDataService.Search(new StoretransactionCreteria()
                {
                    type = "StkDBoard",
                    actiondate = DateTimeNow.Date
                });
                if (cached.Count > 0)
                {
                    dashboardcache.Set();
                    return cached[0].StockDBoardAtribute;
                }

                if (Context.Platform != "WEB" && Context.Platform != "" &&
                    Services.ConfigManager.Instance(Context.OrganizationID).Config.analyser_data_cache)
                    return new List<Dashboard_StockVsSales>();

                    return BuildSalesVsStockDashBoard(currentStock, fromDate);
            }
            return new List<Dashboard_StockVsSales>();
        }

        public List<Dashboard_StockVsSales> BuildSalesVsStockDashBoard(decimal currentStock, DateTime fromDate)
        {
            if (HasResctrictedAccess)
                return new List<Dashboard_StockVsSales>();

            StoretransactionDataService storetransactionDataService = new StoretransactionDataService() { Context = this.Context };
            SortedDictionary<DateTime, Dashboard_StockVsSales> retValue = new SortedDictionary<DateTime, Dashboard_StockVsSales>();
            NpgsqlCommand command = null;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                var query = SQL_SalesVsStockDashboard_Cache;

                conn.Open();
                command = GetCommand(query, conn);
                command.Parameters.AddWithValue("fromdate", fromDate);
                command.Parameters.AddWithValue("todate", DateTimeNow.Date);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    //if (reader.Read())
                    //{
                    //    currentStock = reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    //}
                    //if (reader.NextResult() && reader.Read())
                    //{
                    //    currentStock += reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    //}
                    //if (reader.NextResult() && reader.Read())
                    //{
                    //    currentStock += reader.IsDBNull(0) ? 0 : reader.GetDecimal(0);
                    //}
                    //if (reader.NextResult())
                    {
                        //inwards
                        while (reader.Read())
                        {
                            decimal value = reader["value"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["value"]);
                            DateTime stockdate = reader["date"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["date"]);
                            if (stockdate < fromDate) continue;

                            if (retValue.ContainsKey(stockdate))
                                retValue[stockdate].Purchase += value;
                            else
                                retValue.Add(stockdate, new Dashboard_StockVsSales()
                                {
                                    Date = stockdate,
                                    Purchase = value
                                });
                        }
                    }

                    if (reader.NextResult())
                    {
                        while (reader.Read())
                        {
                            decimal value = reader["value"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["value"]);
                            DateTime stockdate = reader["date"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["date"]);
                            if (stockdate < fromDate) continue;

                            if (retValue.ContainsKey(stockdate))
                                retValue[stockdate].Purchase += value;
                            else
                                retValue.Add(stockdate, new Dashboard_StockVsSales()
                                {
                                    Date = stockdate,
                                    Purchase = value
                                });
                        }
                    }

                    if (reader.NextResult())
                    {
                        //sales
                        while (reader.Read())
                        {
                            decimal cost = reader["cost"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["cost"]);
                            decimal value = reader["value"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["value"]);
                            DateTime stockdate = reader["date"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["date"]);
                            if (retValue.ContainsKey(stockdate))
                            {
                                //retValue[stockdate].Purchase += cost;
                                retValue[stockdate].Sales += value;
                                retValue[stockdate].Margin += (value - cost);
                                retValue[stockdate].Cost += cost;
                            }
                            else
                            {
                                retValue.Add(stockdate, new Dashboard_StockVsSales()
                                {
                                    Date = stockdate,
                                    //Purchase = cost,
                                    Sales = value,
                                    Cost = cost,
                                    Margin = (value - cost)
                                });
                            }
                        }
                    }
                }

                if (!retValue.ContainsKey(DateTimeNow.Date))
                {
                    retValue.Add(DateTimeNow.Date, new Dashboard_StockVsSales()
                    {
                        Date = DateTimeNow.Date,
                        Stock = currentStock
                    });
                }
                else
                {
                    retValue[DateTimeNow.Date].Stock = currentStock - retValue[DateTimeNow.Date].Purchase + retValue[DateTimeNow.Date].Sales;
                }

                var list = retValue.Values.ToList().OrderByDescending(e => e.Date).ToList();
                list.RemoveAll(e => e.Date > DateTimeNow.Date);

                currentStock = 0;
                for (int i = 0; i < list.Count; i++)
                {
                    Dashboard_StockVsSales itm = list[i];
                    if (i == 0)
                    {
                        currentStock = itm.Stock;
                    }
                    else
                    {
                        itm.Stock = currentStock = currentStock - itm.Purchase + itm.Sales;
                    }
                    itm.Cost = Math.Round(itm.Cost, 0);
                    itm.Stock = Math.Round(itm.Stock, 0);
                    itm.Purchase = Math.Round(itm.Purchase, 0);
                    itm.Sales = Math.Round(itm.Sales, 0);
                    itm.Margin = Math.Round(itm.Margin, 0);
                }
                conn.Close();
                var response = list.OrderBy(e => e.Date).ToList();
                storetransactionDataService.Insert(new Storetransaction()
                {
                    type = "StkDBoard",
                    actiondate = DateTimeNow.Date,
                    isactive = true,
                    StockDBoardAtribute = response,
                    createdby = Context.UserID,
                    createdon = DateTimeNow
                });
                dashboardcache.Set();
                return response;
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, fromDate);
            }
            return new List<Dashboard_StockVsSales>();
        }
