        public List<StockValue> SearchStockValue(RetailReportCreteria _reportcreteria)
        {
            string SQL_WarehouseStvalue = @"select 'WAREHOUSE' as location, sum(buyingprice::numeric * (stock.qty-stock.transfered-stock.journalqty-stock.damagedqty-returnqty)::numeric) stockvalue,
            sum((price::numeric-discount::numeric) * (stock.qty-stock.transfered-stock.journalqty-stock.damagedqty-returnqty)::numeric) salevalue
            from stock 
            where stock.isactive = true and stock.hasstock = true and stock.qty-stock.journalqty-stock.transfered-stock.damagedqty-returnqty>0";

            string SQL_RetailStvalue = @"
            with retailstock
            as
            (
            select salablegoods.locationid, sum((stock.buyingprice)::numeric * (salablegoods.iqty-salablegoods.jqty-salablegoods.oqty-salablegoods.dqty)::numeric) stockvalue,
            sum((salablegoods.price-salablegoods.discount)::numeric * (salablegoods.iqty-salablegoods.jqty-salablegoods.oqty-salablegoods.dqty)::numeric) salevalue
            from salablegoods 
            inner join stock on stock.id = salablegoods.stockid and stock.isactive = true
            where salablegoods.isactive=true and salablegoods.hasstock = true and (salablegoods.iqty-salablegoods.jqty-salablegoods.oqty-salablegoods.dqty)>0
            {0}
            group by salablegoods.locationid)
            select retailstock.*,location.name as location from retailstock
            inner join referencelist location on location.id = retailstock.locationid
            ";

            List<StockValue> lst = new List<StockValue>();
            //DateTime today = _reportcreteria.fromdate.Date;
            //DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                string locationfilter = "";
                if (Context.accessiblelocation != null)
                {
                    if (!Context.accessiblelocation.Exists(e => e == -1))
                    {
                        if (Context.accessiblelocation.Count == 1)
                        {
                            locationfilter = " and salablegoods.locationid = " + Context.accessiblelocation[0].ToString();
                        }
                        if (Context.accessiblelocation.Count > 1)
                        {
                            locationfilter = " and salablegoods.locationid in (" + string.Join(",", Context.accessiblelocation) + ")";
                        }
                    }

                    if (!Context.accessiblecompany.Exists(e => e == -1))
                    {
                        if (Context.accessiblecompany.Count == 1)
                        {
                            locationfilter = " and salablegoods.companyid = " + Context.accessiblecompany[0].ToString();
                        }
                        if (Context.accessiblecompany.Count > 1)
                        {
                            locationfilter = " and salablegoods.companyid in (" + string.Join(",", Context.accessiblecompany) + ")";
                        }
                    }
                }

                NpgsqlCommand command = null;
                command = GetCommand(SQL_WarehouseStvalue + locationfilter.Replace("salablegoods.", "stock."), conn);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        StockValue oitem = new StockValue();
                        oitem.locationid = 0;
                        oitem.stockvalue = reader["stockvalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockvalue"]);
                        oitem.salevalue = reader["salevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salevalue"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        lst.Add(oitem);
                    }
                }
                command = GetCommand(string.Format(SQL_RetailStvalue, locationfilter), conn);
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        StockValue oitem = new StockValue();
                        oitem.locationid = reader["locationid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["locationid"]);
                        oitem.stockvalue = reader["stockvalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["stockvalue"]);
                        oitem.salevalue = reader["salevalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["salevalue"]);
                        oitem.location = reader["location"] == DBNull.Value ? "" : reader["location"].ToString();
                        lst.Add(oitem);
                    }
                }

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
        public List<SaleSummary> SearchSaleSummarySlip(RetailReportCreteria _reportcreteria)
        {
            const string SQL_SaleSummarySlip = @"Select bill.billno, sum(receivable+bill.rounding) receivable, sum(tax) tax, sum(discount) discount, 
                                        sum(additionaldiscount) additionaldiscount, sum(qty) qty
                                    from bill 
                                    where bill.isactive = true and bill.billdate>=@fromdate and bill.billdate<@todate
                                    and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end
                                    and case when @companyid=0 then bill.companyid >= 0 else bill.companyid = @companyid end
                                    group by bill.billno 
                                    order by billno";

            List<SaleSummary> lst = new List<SaleSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(SQL_SaleSummarySlip, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SaleSummary oitem = new SaleSummary();
                        oitem.saletax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        oitem.saleqty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.addlndiscount = reader["additionaldiscount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["additionaldiscount"]);
                        oitem.discount = reader["discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["discount"]);
                        oitem.amount = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        oitem.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        lst.Add(oitem);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;

        }
        public DashboardData SearchFastmovingItem(RetailReportCreteria _reportcreteria)
        {

            const string SQL_Fastmoving = @"Select sum(salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty)) as rstock, sum(billitems.receivable) as value, sum(billitems.qty) qty ,{0}.{1} as name 
                            from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                            inner join stock on stock.id = billitems.stockid 
                            inner join items on items.id = stock.itemid
                            inner join salablegoods on salablegoods.stockid = billitems.stockid  
                            where stock.isactive = true and billtype!=9 and bill.isb2b=false and billitems.isactive=true 
                            and bill.billdate>=@fromdate and bill.billdate<@todate 
                            and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end 
                            group by {0}.{1} 
                            order by sum(billitems.receivable) desc
                            limit 10";

            const string SQL_Slowmoving = @"Select sum(salablegoods.iqty-(salablegoods.oqty+salablegoods.jqty+salablegoods.dqty)) as rstock, sum(billitems.receivable) as value, sum(billitems.qty) qty ,{0}.{1} as name 
                            from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                            inner join stock on stock.id = billitems.stockid 
                            inner join items on items.id = stock.itemid
                            inner join salablegoods on salablegoods.stockid = billitems.stockid  
                            where stock.isactive = true and billtype!=9 and bill.isb2b=false and billitems.isactive=true 
                            and bill.billdate>=@fromdate and bill.billdate<@todate 
                            and case when @locationid=0 then bill.locationid <> 0 else bill.locationid = @locationid end 
                            group by {0}.{1} 
                            order by sum(billitems.receivable)
                            limit 10";

            List<DashboardData.TopSaleItem> lstproducts = new List<DashboardData.TopSaleItem>();
            List<DashboardData.TopSaleItem> lstbrand = new List<DashboardData.TopSaleItem>();

            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();
            string tablename, columnname;

            switch (_reportcreteria.reporttype)
            {
                case "PRODUCT":
                    {
                        tablename = "items";
                        columnname = "productname";
                        break;
                    }
                case "BRAND":
                    {
                        tablename = "items";
                        columnname = "brandname";
                        break;
                    }
                case "MATERIAL":
                    {
                        tablename = "items";
                        columnname = "materialname";
                        break;
                    }
                case "PATTERN":
                    {
                        tablename = "items";
                        columnname = "patternname";
                        break;
                    }
                case "STYLE":
                    {
                        tablename = "items";
                        columnname = "stylename";
                        break;
                    }
                case "SIZE":
                    {
                        tablename = "items";
                        columnname = "sizename";
                        break;
                    }
                case "DESIGN":
                    {
                        tablename = "stock";
                        columnname = "designid";
                        break;
                    }
                case "SUPPLIER":
                    {
                        tablename = "stock";
                        columnname = "supplierid";
                        break;
                    }
                default:
                    {
                        tablename = "items";
                        columnname = "productname";
                        break;
                    }
            }

            try
            {
                conn.Open();

                NpgsqlCommand command = null;
                command = GetCommand(string.Format(SQL_Fastmoving, tablename, columnname), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DashboardData.TopSaleItem oitem = new DashboardData.TopSaleItem();
                        oitem.name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.rstock = reader["rstock"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rstock"]);
                        oitem.value = reader["value"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["value"]);
                        lstproducts.Add(oitem);
                    }
                }
                command = GetCommand(string.Format(SQL_Slowmoving, tablename, columnname), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        DashboardData.TopSaleItem oitem = new DashboardData.TopSaleItem();
                        oitem.name = reader["name"] == DBNull.Value ? "" : reader["name"].ToString();
                        oitem.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        oitem.rstock = reader["rstock"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["rstock"]);
                        oitem.value = reader["value"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["value"]);
                        lstbrand.Add(oitem);
                    }
                }

                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            var dashboard = new DashboardData()
            {
                lstproduct = lstproducts,
                lstbrand = lstbrand
            };
            return dashboard;
        }

        public List<SalesSnapshot> SearchSalesSnapshot(SaleRetailCreteria _reportcreteria)
        {
            List<SalesSnapshot> lst = new List<SalesSnapshot>();
            NpgsqlConnection conn = CreateConnection();
            decimal rounding = 0;
            try
            {
                _reportcreteria.mode = "1";
                List<RetailReport> salesummary = SearchSales(_reportcreteria);

                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Report - Location wise",
                    //qty = salesummary.Sum(e => e.saleqty),
                    discount = salesummary.Sum(e => e.discount),
                    additionaldiscount = salesummary.Sum(e => e.addlndiscount),
                    tax = salesummary.Sum(e => e.saletax),
                    netsales = salesummary.Sum(e => e.amount),
                    taxableamount = salesummary.Sum(e => e.amount) - salesummary.Sum(e => e.saletax),
                    rounding = salesummary.Sum(e => e.rounding)
                });
                rounding = salesummary.Sum(e => e.rounding);

                _reportcreteria.mode = "2";
                salesummary = SearchSales(_reportcreteria);

                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Report - Date wise",
                    //qty = salesummary.Sum(e => e.saleqty),
                    discount = salesummary.Sum(e => e.discount),
                    additionaldiscount = salesummary.Sum(e => e.addlndiscount),
                    tax = salesummary.Sum(e => e.saletax),
                    netsales = salesummary.Sum(e => e.amount),
                    taxableamount = salesummary.Sum(e => e.amount) - salesummary.Sum(e => e.saletax),
                    rounding = salesummary.Sum(e => e.rounding)
                });
                _reportcreteria.mode = "4";
                salesummary = SearchSales(_reportcreteria);

                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Report - Bill wise",
                    //qty = salesummary.Sum(e => e.saleqty),
                    discount = salesummary.Sum(e => e.discount),
                    additionaldiscount = salesummary.Sum(e => e.addlndiscount),
                    tax = salesummary.Sum(e => e.saletax),
                    netsales = salesummary.Sum(e => e.amount),
                    taxableamount = salesummary.Sum(e => e.amount) - salesummary.Sum(e => e.saletax),
                    rounding = salesummary.Sum(e => e.rounding)
                });

                List<SalesmanReport> salesman = SearchSalesman(_reportcreteria);
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Report - Salesman",
                    qty = salesman.Sum(e => e.qty),
                    taxableamount = salesman.Sum(e => e.taxableamount),
                    netsales = salesman.Sum(e => e.amount) + rounding,
                    rounding = rounding
                });

                salesummary = SearchSalesMargin(_reportcreteria);
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Report - Sales Margin",
                    discount = salesummary.Sum(e => e.discount),
                    tax = salesummary.Sum(e => e.saletax),
                    netsales = salesummary.Sum(e => e.amount) + rounding,
                    taxableamount = salesummary.Sum(e => e.amount) - salesummary.Sum(e => e.saletax),
                    rounding = rounding
                });

                List<SalesTaxSummary> salesinvoice = SearchInvoicewiseSales(new RetailReportCreteria()
                {
                    fromdate = _reportcreteria.fromdate,
                    todate = _reportcreteria.todate,
                    locationid = _reportcreteria.locationid,
                    companyid = _reportcreteria.companyid
                });
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Report - Invoice Summary",
                    qty = salesinvoice.Sum(e => e.qty),
                    tax = salesinvoice.Sum(e => e.taxamount),
                    netsales = salesinvoice.Sum(e => e.total) + rounding,
                    taxableamount = salesinvoice.Sum(e => e.amount),
                    rounding = rounding
                });

                List<SalesTaxSummary> saletaxsummary = SearchSalesTaxSummary(_reportcreteria);
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Tax Report - Summary",
                    tax = saletaxsummary.Sum(e => e.taxamount),
                    netsales = saletaxsummary.Sum(e => e.total) + rounding,
                    taxableamount = saletaxsummary.Sum(e => e.amount),
                    rounding = rounding
                });

                SalesTaxReport saletax = SearchSalesTax(_reportcreteria);
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Tax Report - Colum wise",
                    tax = saletax.taxvalue,
                    taxableamount = saletax.taxablevalue,
                    netsales = saletax.totalvalue + rounding,
                    rounding = rounding
                });

                decimal tax = 0, taxableamount = 0, netsale = 0;

                string _SQL = "";
                if (_reportcreteria.sectionid == 0)
                    _SQL = string.Format(SQL_SalesHSN, "");
                else if (_reportcreteria.sectionid == 1)
                    _SQL = string.Format(SQL_SalesHSN, "and products.sellingmode != 3");
                else if (_reportcreteria.sectionid == 2)
                    _SQL = string.Format(SQL_SalesHSN, "and products.sellingmode = 3");

                conn.Open();
                NpgsqlCommand command = null;
                command = GetCommand(_SQL, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = _reportcreteria.fromdate.Date;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = _reportcreteria.todate.AddDays(1).Date;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        tax += reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        taxableamount += (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - (reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]));
                        netsale += reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                    }
                }
                conn.Close();

                //POReport salehsn = SearchSalesHSN(_reportcreteria);
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Tax Report - HSN wise",
                    tax = tax,
                    taxableamount = taxableamount,
                    netsales = netsale + rounding,
                    rounding = rounding
                });

                List<StockReport> stock = SearchSalesAnalysis(new StockReportCreteria()
                {
                    fromdate = _reportcreteria.fromdate,
                    todate = _reportcreteria.todate,
                    companyid = _reportcreteria.companyid,
                    locationid = _reportcreteria.locationid,
                    mode = 1,
                    product = true
                });
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Analyser Report",
                    qty = stock.Sum(e => e.qty),
                    tax = stock.Sum(e => e.taxvalue),
                    discount = stock.Sum(e => e.discount),
                    netsales = stock.Sum(e => e.price) + rounding,
                    taxableamount = stock.Sum(e => e.netsalevalue),
                    rounding = rounding
                });

                AnalyserDataService analyserData = new AnalyserDataService() { Context = this.Context };
                List<AnalyserDataService.Condtion> condition = new List<AnalyserDataService.Condtion>();
                if (_reportcreteria.companyid > 0)
                {
                    condition.Add(new AnalyserDataService.Condtion()
                    {
                        type = AnalyserDataService.Condtion.CondtionType.Long,
                        option = AnalyserDataService.Options.Company,
                        longList = new List<long>() { _reportcreteria.companyid }
                    });
                }
                List<AnalyserDataService.Items> salesanalyser = analyserData.StockAnalyser(new AnalyserDataService.Configuration()
                {
                    fromdate = _reportcreteria.fromdate,
                    todate = _reportcreteria.todate,
                    locationid = _reportcreteria.locationid,
                    SecondaryCondtions = condition,
                    reporttype = AnalyserDataService.Configuration.ReportType.Sales
                });
                lst.Add(new SalesSnapshot()
                {
                    reportname = "Sales Analytical - 360* Sales Analyzer",
                    qty = salesanalyser.Sum(e => e.qty),
                    netsales = salesanalyser.Sum(e => e.value) + rounding,
                    rounding = rounding
                });

            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }

        internal byte[] DayTransactionXLSX(string orgid, string billdate, string companyid, string locationid, string isb2b)
        {
            string query = @"select billitems.barcode,stock.serialno,lrinvoiceitems.itbuscode,
billitems.taxpercentage,sum(billitems.tax) tax,
sum(billitems.qty) qty,sum(billitems.receivable) receivable from billitems
inner join bill on bill.id = billid
inner join stock on stock.id = billitems.stockid
left outer join lrinvoiceitems on lrinvoiceitems.id = invoiceitemid
where bill.isactive=true and bill.billtype != 9 and billitems.qty>0 and billitems.isactive=true
and bill.isb2b=@isb2b 
and bill.billdate>=@fromdate and bill.billdate<@todate
and bill.locationid = @locationid and bill.companyid=@companyid
group by billitems.barcode,stock.serialno,lrinvoiceitems.itbuscode,billitems.taxpercentage;

select billitems.barcode,stock.serialno,lrinvoiceitems.itbuscode,
billitems.taxpercentage,sum(billitems.tax) tax,
sum(billitems.qty) qty,sum(billitems.receivable) receivable from billitems
inner join bill on bill.id = billid
inner join stock on stock.id = billitems.stockid
left outer join lrinvoiceitems on lrinvoiceitems.id = invoiceitemid
where bill.isactive=true and bill.billtype != 9 and billitems.qty<0 and billitems.isactive=true
and bill.isb2b=@isb2b 
and bill.billdate>=@fromdate and bill.billdate<@todate
and bill.locationid = @locationid and bill.companyid=@companyid
group by billitems.barcode,stock.serialno,lrinvoiceitems.itbuscode,billitems.taxpercentage;

with billsettle as 
(select billsettlementmaster.id,
billsettlementmaster.receivable,billsettlementmaster.paidamount, billsettlementmaster.createdby,
paid_cash cash,paid_card,paid_credit,paid_voucher, paid_upi,paid_debt,
case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'cash_return' as numeric) else 0 end cashreturn, 
case when billsettlementmaster.paidamount<0 then cast(paymentinfo->>'creditnote_refund' as numeric) else 0 end creditnoterefund, 
cast(paymentinfo->>'adjustment_paid' as numeric) adjustment_paid, 
cast(paymentinfo->>'discount_paid' as numeric) discount_paid, 
billsettlementmaster.locationid, billsettlementmaster.counterid from billsettlementmaster
left outer join users on users.id = billsettlementmaster.createdby
where billsettlementmaster.isactive=true and
billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
and billsettlementmaster.isactive = true and billsettlementmaster.locationid = @locationid
)
select sum(cash) as paid_cash,sum(paidamount) paidamount,
sum(paid_card) paid_card,sum(paid_upi) paid_upi, sum(paid_credit) as paid_credit, 
sum(paid_voucher) paid_voucher,sum(paid_debt) paid_debt,
sum(cashreturn) as paid_refund, sum(creditnoterefund) creditnoterefund, sum(adjustment_paid) as paid_adjustment, 
sum(discount_paid) as paid_discount from billsettle;


select  vouchers.vouchertype,coupons.vouchervalue, coupons.name,
referencelist.name counter,vouchers.issuedon,billsettlement.billno,
vouchers.issueto billsettlementmasterid
from vouchers 
inner join coupons on coupons.id = vouchers.coupenid 
left outer join billsettlementmaster on billsettlementmaster.id = vouchers.issueto
left outer join billsettlement on billsettlement.billsettlementmasterid =billsettlementmaster.id
left outer join referencelist on referencelist.id = coupons.counterid
where coupons.isactive=True And vouchers.isactive=True And vouchers.vouchertype=4    
and vouchers.issuedon>=@fromdate And vouchers.issuedon<@todate 
and billsettlementmaster.companyid=@companyid 
and billsettlementmaster.locationid=@locationid;

select vouchers.vouchertype,coupons.vouchervalue, coupons.name,
vouchers.issuedon,billsettlement.billno,coupons.billsettlementmasterid,
billitems.barcode,billitems.qty,billitems.receivable,billitems.tax,
lrinvoiceitems.itbuscode,referencelist.name counter
from vouchers 
inner join coupons on coupons.id = vouchers.coupenid 
inner join billsettlementmaster on billsettlementmaster.id = coupons.billsettlementmasterid
inner join billsettlement on billsettlement.billsettlementmasterid =billsettlementmaster.id
inner join billitems on billitems.billid = billsettlement.billid and billitems.isactive = true 
inner join stock on stock.id = billitems.stockid 
left outer join referencelist on referencelist.id = coupons.counterid
left outer join lrinvoiceitems on lrinvoiceitems.id =invoiceitemid
where coupons.isactive=True And vouchers.isactive=True And vouchers.vouchertype=7   
and vouchers.issuedon>=@fromdate And vouchers.issuedon<@todate 
and billsettlementmaster.companyid=@companyid 
and billsettlementmaster.locationid=@locationid";

            DateTime dateTime = BaseEntity.GetDataFromString(billdate);

            decimal paidamount = 0;
            decimal receivable = 0;
            decimal totalsale = 0;
            decimal paid_creditnote = 0;
            decimal paid_adjustment = 0;
            decimal paid_cash = 0;
            decimal paid_refund = 0;
            decimal paid_discount = 0;
            decimal paid_card = 0;
            decimal paid_debt = 0;
            decimal paid_upi = 0;
            decimal paid_credit = 0;
            decimal paid_voucher = 0;
            List<DayTransaction> dayTransactions = new List<DayTransaction>();
            List<DayTransactionCreditNote> dayCreditNotes = new List<DayTransactionCreditNote>();
            List<DayTransaction> dayreturnTransactions = new List<DayTransaction>();
            var param = new SortedList<string, object>();
            param.Add("fromdate", dateTime.Date);
            param.Add("todate", dateTime.Date.AddDays(1));
            param.Add("locationid", long.Parse(locationid));
            param.Add("companyid", long.Parse(companyid));
            param.Add("isb2b", bool.Parse(isb2b));
            using (var reader = ExecuteReader(query, param))
            {
                while (reader.Read())
                {
                    DayTransaction dayTransaction = new DayTransaction();
                    dayTransaction.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                    dayTransaction.serialno = reader["serialno"] == DBNull.Value ? "" : reader["serialno"].ToString();
                    dayTransaction.itbuscode = reader["itbuscode"] == DBNull.Value ? "" : reader["itbuscode"].ToString();
                    dayTransaction.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                    dayTransaction.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                    dayTransaction.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                    dayTransaction.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                    dayTransactions.Add(dayTransaction);
                }

                if (reader.NextResult())
                {
                    while (reader.Read())
                    {
                        DayTransaction dayTransaction = new DayTransaction();
                        dayTransaction.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        dayTransaction.serialno = reader["serialno"] == DBNull.Value ? "" : reader["serialno"].ToString();
                        dayTransaction.itbuscode = reader["itbuscode"] == DBNull.Value ? "" : reader["itbuscode"].ToString();
                        dayTransaction.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);
                        dayTransaction.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        dayTransaction.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        dayTransaction.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        dayreturnTransactions.Add(dayTransaction);
                    }
                }

                if (reader.NextResult() && reader.Read())
                {
                    //creditnoterefund, sum(adjustment_paid) as paid_adjustment
                    paidamount = reader["paidamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paidamount"]);

                    paid_creditnote = reader["creditnoterefund"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["creditnoterefund"]);
                    paid_adjustment = reader["paid_adjustment"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_adjustment"]);

                    paid_cash = reader["paid_cash"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_cash"]);
                    paid_refund = reader["paid_refund"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_refund"]);
                    paid_discount = reader["paid_discount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_discount"]);
                    paid_card = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]);
                    paid_debt = reader["paid_debt"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_debt"]);
                    paid_upi = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]);
                    paid_credit = reader["paid_credit"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_credit"]);
                    paid_voucher = reader["paid_voucher"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_voucher"]);

                    totalsale = paid_cash + paid_card + paid_upi + paid_credit + paid_voucher + paid_adjustment + paid_discount - (paid_refund + paid_creditnote);
                    receivable = paid_cash + paid_card + paid_upi + paid_credit + paid_voucher - (paid_refund + paid_creditnote);

                }

                if (reader.NextResult())
                {
                    while (reader.Read())
                    {
                        DayTransactionCreditNote dayTransaction = new DayTransactionCreditNote();
                        dayTransaction.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        dayTransaction.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        dayTransaction.vouchervalue = reader["vouchervalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["vouchervalue"]);
                        dayTransaction.billsettlementmasterid = reader["billsettlementmasterid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["billsettlementmasterid"]);
                        dayTransaction.vouchertype = reader["vouchertype"] == DBNull.Value ? 0 : Convert.ToInt32(reader["vouchertype"]);
                        if (!dayCreditNotes.Exists(x => x.billsettlementmasterid == dayTransaction.billsettlementmasterid))
                            dayCreditNotes.Add(dayTransaction);
                    }
                }

                if (reader.NextResult())
                {
                    while (reader.Read())
                    {
                        DayTransactionCreditNote dayTransaction = new DayTransactionCreditNote();
                        dayTransaction.billno = reader["billno"] == DBNull.Value ? "" : reader["billno"].ToString();
                        dayTransaction.counter = reader["counter"] == DBNull.Value ? "" : reader["counter"].ToString();
                        dayTransaction.vouchervalue = reader["vouchervalue"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["vouchervalue"]);
                        dayTransaction.billsettlementmasterid = reader["billsettlementmasterid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["billsettlementmasterid"]);
                        dayTransaction.vouchertype = reader["vouchertype"] == DBNull.Value ? 0 : Convert.ToInt32(reader["vouchertype"]);
                        dayTransaction.barcode = reader["barcode"] == DBNull.Value ? "" : reader["barcode"].ToString();
                        dayTransaction.qty = reader["qty"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["qty"]);
                        dayTransaction.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        dayTransaction.tax = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        dayCreditNotes.Add(dayTransaction);
                    }
                }
            }


            using (System.IO.MemoryStream memoryStream = new System.IO.MemoryStream())
            {
                ClosedXML.Excel.XLWorkbook xLWorkbook = new ClosedXML.Excel.XLWorkbook();

                DataTable dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Barcode", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("UAN Code", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Item Code", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Qty", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Price", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Amount", typeof(decimal)) });

                foreach (var p in dayTransactions.GroupBy(x => new { x.barcode, x.serialno, x.itbuscode }))
                {
                    var qty = p.Sum(x => x.qty);
                    var amt = p.Sum(x => x.receivable);
                    dt.Rows.Add(new object[] { p.Key.barcode, p.Key.serialno, p.Key.itbuscode,
                        qty, qty!= 0? amt/qty:0,amt
                    });
                }
                var sheet = xLWorkbook.AddWorksheet(dt, "Sales");

                dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Barcode", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("UAN Code", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Item Code", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Qty", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Price", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Amount", typeof(decimal)) });
                ;
                foreach (var p in dayreturnTransactions.GroupBy(x => new { x.barcode, x.serialno, x.itbuscode }))
                {
                    var qty = p.Sum(x => x.qty);
                    var amt = p.Sum(x => x.receivable);
                    dt.Rows.Add(new object[] { p.Key.barcode, p.Key.serialno, p.Key.itbuscode,
                        qty, qty!= 0? amt/qty:0,amt
                    });
                }
                sheet = xLWorkbook.AddWorksheet(dt, "Sales Return");

                dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Counter", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Bill No", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("CN Amount", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Barcode", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Qty", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Rate", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Tax", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Amount", typeof(decimal)) });
                foreach (var p in dayCreditNotes.Where(x => x.vouchertype == 7))
                {
                    dt.Rows.Add(new object[] { p.counter, p.billno, p.vouchervalue,p.barcode,
                    p.qty,p.receivable/p.qty,p.tax,p.receivable});
                }
                sheet = xLWorkbook.AddWorksheet(dt, "Credit Note Issued");

                dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Counter", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Bill No", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("CN Amount", typeof(decimal)) });
                foreach (var p in dayCreditNotes.Where(x => x.vouchertype == 4))
                {
                    dt.Rows.Add(new object[] { p.counter, p.billno, p.vouchervalue });
                }
                sheet = xLWorkbook.AddWorksheet(dt, "Credit Note Consumed");

                dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Tax Percentage", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Taxable", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Tax", typeof(decimal)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Amount", typeof(decimal)) });

                foreach (var p in dayTransactions.GroupBy(x => x.taxpercentage))
                {
                    var qty = p.Sum(x => x.qty);
                    var tax = p.Sum(x => x.tax);
                    var amt = p.Sum(x => x.receivable);
                    dt.Rows.Add(new object[] { p.Key,amt-tax,
                        tax,amt
                    });
                }
                sheet = xLWorkbook.AddWorksheet(dt, "Tax");

                dt = new DataTable();
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Mode", typeof(string)) });
                dt.Columns.AddRange(new DataColumn[1] { new DataColumn("Amount", typeof(decimal)) });

                dt.Rows.Add(new object[] { "Total Sale", totalsale });
                dt.Rows.Add(new object[] { "Total Collection", receivable });
                dt.Rows.Add(new object[] { "Un Paid", receivable - paidamount });
                dt.Rows.Add(new object[] { "Paid Cash", paid_cash });
                dt.Rows.Add(new object[] { "Paid Card", paid_card });
                dt.Rows.Add(new object[] { "Paid UPI", paid_upi });
                dt.Rows.Add(new object[] { "Paid Credit", paid_credit });
                dt.Rows.Add(new object[] { "Paid Debtor", paid_debt });
                dt.Rows.Add(new object[] { "Paid Discount", paid_discount });
                dt.Rows.Add(new object[] { "Paid Voucher", paid_voucher });

                dt.Rows.Add(new object[] { "Tiny Adjustment", paid_adjustment });
                dt.Rows.Add(new object[] { "Issued CR Note", paid_creditnote });
                dt.Rows.Add(new object[] { "Issued Refund", paid_refund });

                sheet = xLWorkbook.AddWorksheet(dt, "Payment");
                xLWorkbook.SaveAs(memoryStream);
                return memoryStream.ToArray();
            }
        }

        internal List<ReconilationSettlement> SearchSettlementReconcilation(RetailReportCreteria _reportcreteria)
        {
            List<long> billmasterids = new List<long>();
            List<ReconilationSettlement> lst = new List<ReconilationSettlement>();
            string query = @"select billsettlementmaster.code,employee.name employ,referencelist.name bank,
billsettlementmaster.createdon,billsettlementmaster.id,billsettlementmaster.recon,
cast(paymentinfo->>'deviceresult' as json)->>'BankInvoice_Num' bankinvoiceno,
cast(paymentinfo->>'deviceresult' as json)->>'Txn_Type' banktxntype,
cast(paymentinfo->>'deviceresult' as json)->>'RRN_No' rrnno,
cast(paymentinfo->>'deviceresult' as json)->>'Amount' amount,
paid_card,receivable,paidamount,paid_upi
from billsettlementmaster
inner join users on users.id = billsettlementmaster.createdby
left outer join employee on employee.id = users.employeeid
left outer join referencelist on referencelist.id = cast(paymentinfo->>'card_bankid' as bigint)
where paymentinfo->>'deviceresult' is not null and billsettlementmaster.settlementon>=@fromdate and billsettlementmaster.settlementon<@todate
and (paid_card+paid_upi)>0";

            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            using (NpgsqlConnection conn = CreateConnection())
            {
                if (!_reportcreteria.integration)
                {
                    query = query.Replace("paymentinfo->>'deviceresult' is not null and", "");
                }
                conn.Open();
                string condition = "";
                if (_reportcreteria.bankid > 0)
                    condition += " and  cast(paymentinfo->>'card_bankid' as bigint)=@bankid ";
                if (_reportcreteria.locationid > 0)
                    condition += " and billsettlementmaster.locationid=@locationid ";
                if (_reportcreteria.companyid > 0)
                    condition += " and billsettlementmaster.locationid=@companyid ";

                NpgsqlCommand command = GetCommand(string.Format(query, condition), conn);
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("bankid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.bankid;

                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        ReconilationSettlement oitem = new ReconilationSettlement();
                        oitem.recon = reader["recon"] == DBNull.Value ? false : Convert.ToBoolean(reader["recon"]);
                        oitem.id = reader["id"] == DBNull.Value ? 0 : Convert.ToInt64(reader["id"]);
                        oitem.code = reader["code"] == DBNull.Value ? "" : Convert.ToString(reader["code"]);
                        oitem.bank = reader["bank"] == DBNull.Value ? "" : Convert.ToString(reader["bank"]);
                        oitem.bankinvoiceno = reader["bankinvoiceno"] == DBNull.Value ? "" : Convert.ToString(reader["bankinvoiceno"]);
                        oitem.banktxntype = reader["banktxntype"] == DBNull.Value ? "" : Convert.ToString(reader["banktxntype"]);
                        oitem.employ = reader["employ"] == DBNull.Value ? "" : Convert.ToString(reader["employ"]);
                        oitem.rrnno = reader["rrnno"] == DBNull.Value ? "" : Convert.ToString(reader["rrnno"]);
                        oitem.paid_card = reader["paid_card"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_card"]);
                        oitem.paid_upi = reader["paid_upi"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paid_upi"]);
                        oitem.paidamount = reader["paidamount"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["paidamount"]);
                        oitem.receivable = reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"]);
                        oitem.createdon = reader["createdon"] == DBNull.Value ? DateTime.MinValue : Convert.ToDateTime(reader["createdon"]);
                        lst.Add(oitem);
                    }
                }
            }
            return lst.OrderBy(x => x.id).ToList();
        }

        internal List<SalesTaxSummary> SearchSalesTaxFullSummary(RetailReportCreteria _reportcreteria)
        {
            string SQL_SalesTaxSummaryModified = @"
                        with billtaxdetail as (
                        Select bill.companyid, billitems.taxpercentage, sum(billitems.receivable) receivable, 
                        sum(case when bill.isinterstatesale then 0 else billitems.tax end) tax,
                        sum(case when bill.isinterstatesale then billitems.tax else 0 end) itax,sum(rounding) rounding
                        from bill inner join billitems on billitems.billid = bill.id and billitems.isactive=true
                        where bill.isactive = true and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and bill.companyid = @companyid 
                        {0}
                        group by bill.companyid, taxpercentage
                        order by taxpercentage
                        ),
                        additionalcharge as (
                        Select bill.companyid, Billadditionalcharges.taxpercentage,
                        sum(Billadditionalcharges.charge + Billadditionalcharges.tax) receivable, 
                        sum(case when bill.isinterstatesale then 0 else Billadditionalcharges.tax end) tax,
                        sum(case when bill.isinterstatesale then Billadditionalcharges.tax else 0 end) itax,	
                        sum(Billadditionalcharges.amount - (Billadditionalcharges.charge+Billadditionalcharges.tax)) rounding
                        from bill 
                        inner join Billadditionalcharges on Billadditionalcharges.billid = bill.id and Billadditionalcharges.isactive=true
                        where bill.isactive = true and bill.billdate>=@fromdate and bill.billdate<@todate 
                        and bill.companyid = @companyid 
                        {0}
                        and Billadditionalcharges.taxpercentage>0 	and Billadditionalcharges.tax != 0
                        group by bill.companyid, taxpercentage
                        order by taxpercentage
                        )
                        select billtaxdetail.companyid, billtaxdetail.taxpercentage, 
                        billtaxdetail.receivable + case when additionalcharge.receivable is null then 0 else additionalcharge.receivable end receivable, 
                        billtaxdetail.tax + case when additionalcharge.tax is null then 0 else additionalcharge.tax end tax, 
                        billtaxdetail.itax + case when additionalcharge.itax is null then 0 else additionalcharge.itax end itax, 
                        billtaxdetail.rounding + case when additionalcharge.rounding is null then 0 else additionalcharge.rounding end rounding
                        from billtaxdetail 
                        left outer join additionalcharge on additionalcharge.taxpercentage = billtaxdetail.taxpercentage
                        and additionalcharge.companyid = billtaxdetail.companyid";

            List<SalesTaxSummary> lst = new List<SalesTaxSummary>();
            DateTime today = _reportcreteria.fromdate.Date;
            DateTime nextdate = _reportcreteria.todate.AddDays(1).Date;
            NpgsqlConnection conn = CreateConnection();

            try
            {
                conn.Open();
                string query = string.Format(SQL_SalesTaxSummaryModified, " and billtype!=9 ");

                NpgsqlCommand command = null;
                command = GetCommand(query, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxSummary item = new SalesTaxSummary();
                        item.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        item.taxamount = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.igst = reader["itax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["itax"]);
                        item.amount = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - (item.taxamount + item.igst);

                        item.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);

                        item.cgst = Math.Round((item.taxamount / 2), 2);
                        item.sgst = Math.Round((item.taxamount / 2), 2);
                        item.taxamount += item.igst;
                        item.total = Math.Round(item.amount + item.taxamount, 0);
                        lst.Add(item);
                    }
                }

                query = string.Format(SQL_SalesTaxSummaryModified, " and billtype=8 ");

                command = GetCommand(query, conn);
                command.Parameters.Add("locationid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.locationid;
                command.Parameters.Add("companyid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.companyid;
                command.Parameters.Add("counterid", NpgsqlTypes.NpgsqlDbType.Bigint).Value = _reportcreteria.counterid;
                command.Parameters.Add("fromdate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = today;
                command.Parameters.Add("todate", NpgsqlTypes.NpgsqlDbType.Timestamp).Value = nextdate;
                command.Parameters.Add("isb2b", NpgsqlTypes.NpgsqlDbType.Boolean).Value = _reportcreteria.isb2b;
                using (System.Data.IDataReader reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        SalesTaxSummary item = new SalesTaxSummary();
                        item.companyid = reader["companyid"] == DBNull.Value ? 0 : Convert.ToInt64(reader["companyid"]);
                        item.taxamount = reader["tax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["tax"]);
                        item.igst = reader["itax"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["itax"]);
                        item.amount = (reader["receivable"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["receivable"])) - (item.taxamount + item.igst);


                        item.taxpercentage = reader["taxpercentage"] == DBNull.Value ? 0 : Convert.ToDecimal(reader["taxpercentage"]);

                        item.cgst = Math.Round((item.taxamount / 2), 2);
                        item.sgst = Math.Round((item.taxamount / 2), 2);
                        item.taxamount += item.igst;
                        item.total = Math.Round(item.amount + item.taxamount, 0);
                        lst.Add(item);
                    }
                }
                conn.Close();
            }
            catch (Exception exp)
            {
                if (conn != null) conn.Close();
                WebAPI.Common.Logger.Instance(Context.OrganizationID).Log(exp, WebAPI.Common.Logger.LogType.Error, _reportcreteria);
            }
            return lst;
        }
    }

