            public decimal voucher { get; set; }
            public decimal upi { get; set; }
            public decimal amount { get; set; }
            public String mode { get; set; }
            [JsonIgnore]
            [JsonProperty(Required = Required.Default)]
            public string paymentinfo_json
            {
                set
                {
                    if (!string.IsNullOrEmpty(value) && value != "null")
                    {
                        var paymentinfo = Newtonsoft.Json.JsonConvert.DeserializeObject<Customerpayment.Paymentinfo>(value);
                        if (paymentinfo.paymentmode == 0)
                        {
                            card = amount;
                            mode = "CARD";
                        }
                        if (paymentinfo.paymentmode == 1)
                        {
                            voucher = amount;
                            mode = "VCHR";
                        }
                        if (paymentinfo.paymentmode == 2)
                        {
                            cash = amount;
                            mode = "CASH";
                        }
                        if (paymentinfo.paymentmode == 2)
                        {
                            upi = amount;
                            mode = "UPI ";
                        }
                    }
                }
            }
        }
    }
