        {
            get { return Newtonsoft.Json.JsonConvert.SerializeObject(items); }
            set { items = Newtonsoft.Json.JsonConvert.DeserializeObject<List<Bundleitem>>(value); }
        }
        public List<Bundleitem> items { get; set; }
    }
